INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18999496228', 'Bandoleira Duas Pontas Universal - Teisen', 'Bandoleira para Carabina de Pressão Universal - Teisen A bandoleira universal da Teisen é um equipamento projetado para possibilitar a colocação de bandoleiras nas armas que não possuem zarelho. Fabricada em nylon, com presilha de ajuste de tamanho e elástico. Fácil fixação na coronha, confeccionada em Nylon super resistente. Especificações Fabricante: Teisen Modelo: 2 Pontas Material: Nylon Possui ajuste de tamanho Largura aproximada: 3cm Comprimento: 120cm Compatibilidade: Armas sem zarelho Frontal e traseiro ATENÇÃO: "O uso do produto exige treinamento e equilíbrio emocional." "Deverá ser guardado em lugar seguro e fora do alcance de terceiros."', 40.9, 40.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rdwb-m1d4ot1z268521', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567374315%2F18999496228', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
