INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209712010', 'Atum Sólido Ao Natural Coqueiro', 'O Atum Sólido ao Natural Coqueiro é feito com o lombo do peixe, a parte mais nobre, garantindo um sabor suave e uma textura macia. Fonte de proteínas, vitamina D e ômega 3, o atum é perfeito para incrementar suas refeições de forma saudável. Ideal para saladas, sanduíches e massas.', 14.99, 14.99, NULL, 'Food & Beverages > Food Staples > Canned Food', 'https://cf.shopee.com.br/file/sg-11134201-825bc-mqnel4kddektf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F58209712010', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
