INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44705984289', 'Caixa de Transporte Gatos Nº 1 Premium Cachorros Pequeno Barata', 'Caixa de Transporte Para Transportar Gatos Cães Gato Cachorro de Plástico Resistente CARACTERÍSTICAS: Todo mundo já ouviu falar no ditado: “Quem ama, cuida.” Não é mesmo? Pensando nisso trazemos a melhor solução custo x benéfico para quem busca segurança e design para o transporte do seu pet durante viagens ou consultas ao veterinário. - A alça com desenho ergonômico; - Cores de Exclusivas; - A porta possui a fechadura trava de segurança Lateral; - Produzida com 100% Polipropileno. Durável e resistente. COR: Azul; Rosa; Verde; Preto; Vermelho. MEDIDAS: N2 Comprimento 45,5 cm x Largura 34 cm x Altura 30,5 cm Medidas : N1 Dados Técnicos Composição básica: Produto injetado com 100%PP (Polipropileno) Dimensões: 30,00cm Largura x 42,00cm Comprimento x 28,00cm Altura COMPOSIÇÃO BÁSICA: Produto injetado com 100%PP (Polipropileno). DIFERENCIAIS: Resistente, Prática e Segura! Tudo que você busca para transportar o seu Pet para onde precisar ir! ITENS INCLUSOS: 1 Caixa de Transporte N1 OU 2 com Portinha de 4 travas; GARANTIA: Devido ao nosso incrível controle de qualidade, trazemos os melhores produtos que o mercado pode oferecer! Mas, caso precise, basta nos contatar, que faremos o máximo para te ajudar!', 32.98, 30.99, NULL, 'Pets > Pet Accessories > Travel Essentials', 'https://cf.shopee.com.br/file/sg-11134201-825zq-mkh7zs9i677sd5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908280603%2F44705984289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493597482', 'Tênis Olympikus Dynamic Masculino Esportivo Treino Original Olympikus', 'Tênis Esportivo Dynamic Olympikus Modelo: 43298343 O Tênis Olympikus Dinamic tem cabedal com tecnologia Covergrid, que traz mais segurança, resistência e durabilidade. O efeito 3D cria a ilusão de relevo conforme o ângulo, trazendo um visual moderno que se destaca na academia. A palmilha anatômica de EVA e o solado com duas lâminas de Evasense proporcionam maciez e conforto. Características: - Visual moderno com efeito 3D. - Cabedal confere tecnologia com maior segurança, resistência e durabilidade. - Solado leve e macio que garante conforto durante atividades físicas. Composição: - Cabedal leve, com tecnologia COVERGRID de silicone injetado. - Palmilha: anatômica e composta por tecido poliéster e EVA. - Solado: dupla camada de EVA. * Indicado para quem precisa de resistência e durabilidade nos desafios diários. O Tênis Esportivo Dynamic Olympikus pode ser encontrado aqui na Usee Brasil! Sobre a Usee Brasil: A Usee Brasil é uma empresa brasileira que oferece uma variedade de produtos de alta qualidade, desde roupas e acessórios até itens para casa. Tenha uma experiência conosco!', 399.99, 269.99, NULL, 'Sports & Outdoors > Sports Footwear > Running Shoes', 'https://cf.shopee.com.br/file/sg-11134201-82626-mj5z4z03dzia2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349198275%2F23493597482', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598579751', 'Engate Reboque Reforcel Fixo Renault Logan 2013 2014 2015 2016 2017 2018 2019 2020 2021 2022 2024 de reforçado bOM', 'Engate Reboque Renault Logan 2013 2014 2015 2016 2017 2018 2019 2020 2021 2022 2024 Reforcel Rabicho Tração 500Kg Haste Fixa O que é engate? Com o engate rabicho seu carro ganha mais uma opção no transporte de cargas e vai conseguir tracionar um peso maior, ampliando sua capacidade de carga e tracionando caretinhas, trailers, transbikes e reboques em geral. Fabricado em aço resistente e excelente acabamento, possui homologação pelo INMETRO e certificação nos padrões das montadoras, adicionando mais proteção e segurança para a parte traseira do veículo. Em caso de dúvida consulte o profissional ou nossos canais de atendimento sobre a compatibilidade do produto. Quais as características do produto? Tração máxima de 500KG de carga (verifique a limitação do seu veículo) Peso máximo sobre a bola de 30KG Com haste fixa Sem necessidade de furação no veículo Fabricado em aço carbono altamente resistente Pintura eletrostática a pó; Excelente acabamento Esfera cromada maciça de 50mm de diâmetro Tomada totalmente funcional para instalação elétrica Não possui superfícies cortantes Encaixe sob medida Plaqueta indicativa com dados técnicos Homologado pelo INMETRO e normas exigidas pelo orgão fiscalizador *Recomendamos que a instalação seja feita por profissional especializado. Qual o conteúdo da embalagem? 01 engate 01 bola 01 capa 01 tomada elétrica Kit de fixação (a maioria dos veículos utilizam o próprio parafuso original) NÃO NOS RESPONSABILIZAMOS PELO FRETE DE DEVOUÇÃO CASO A PEÇA NÃO SIRVA. TIRE TODAS AS SUAS DÚVIDAS ANTES DA COMPRA.', 341.96, 338.55, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rate-maoxu53fcgo3af', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1069588064%2F23598579751', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
