INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897174899', 'Ball Free Suplemento Para Gatos 70g', 'Ball Free Gato Pasta Oral 70G Indicado para gatos; - Favorece a eliminação das bolas de pelo de maneira natural; - Fácil de administrar; - Com sabor especial para estimular o consumo; - Promove o bem estar do felino, - Disponível em embalagem com 70 g. Quem tem gatinhos em casa já sabe o quanto eles estão propensos a apresentar uma quantidade elevada de bolas de pelos no organismo. Foi pensando em ajudar os tutores a cuidar dos seus felinos que a Agener União criou o Ball Free Gatos! O Ball Free é bom não só por ajudar na eliminação das bolas de pelos do seu pet, mas também por oferecer diversos benefícios durante seu uso no animalzinho. Confira alguns deles a seguir: - Possui fórmula com extrato de malte; - Facilita a eliminação natural das bolas de pelo, - É feito com as principais vitaminas e aminoácidos.', 71.9, 59.9, NULL, 'Pets > Pet Healthcare > Vitamins & Supplements', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m32bklc9iryd78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F23897174899', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
