INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9050384126', 'Anilha 10kg Emborrachada PVC Furo Standard Preta ( 01 Unidade )', 'Projetada para a prática de halteres, a Anilha Emborrachada vem com alças laterais, que facilitam o transporte, atribuindo segurança ao levantamento de peso. É revestida com PVC, material que protege a pele das mãos do atrito e oferece maior aderência e conforto. Com o equipamento e a ajuda de profissionais, é possível aumentar a massa muscular de maneira satisfatória, promovendo a manutenção da saúde e da forma física. Característica : Furo Standard para barras de 1 1/8" (Furo Comum) / 30mm. OBS.: Venda por unidade. Maior higiene e proteção contra impacto Produto para uso profissional ou residencial. Cores diferenciadas para cada quilo, facilitando o usuário na identificação do peso. Não enferrujam. Menor ruído no manuseio. Maior durabilidade. Conteúdo da Embalagem: 1 unidade da Anilha 10kg Emborrachada PVC Furo Standard Preta As cores apresentadas no site são meramente ilustrativas e podem ou não corresponder com exatidão à tonalidade aplicada. Imagem meramente ilustrativa e a descrição do produto é de responsabilidade do fabricante.', 200.0, 200.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/96de78e40754fe4bca3d14b76bc38025', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F9050384126', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
