INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7675845372', 'Tio Nacho Leave-in De Tratamento Reconstrutor Total 100ml', 'Leave-in de Tratamento Reconstrutor Total Aloe Vera Puro Tio Nacho 100ml - 1 Unidade A linha Tio Nacho Reconstrutor Total oferece um tratamento reparador intenso para cabelos danificados. Sua fórmula combina Aloe Vera puro 100% orgânico, Geleia Real e extratos de origem natural ricos em aminoácidos, que fortalecem e reparam profundamente a fibra capilar, oferecendo a nutrição que seu cabelo precisa. Fios totalmente reconstruídos, hidratados e protegidos, com mais brilho e aspecto saudável. - Elimina o dado no 1° uso e protege contra futuros - Cabelos 10x mais fortes e resistentes - Hidrata por 24h - Mantém o frizz controlado - Repara totalmente de dentro para fora. Modo de uso: Aplique o Leave-in após o banho, sobre o cabelo ainda molhado, distribuindo no comprimento dos fios, da metade até as pontas. Não enxágue. Penteie como de costume.', 48.9, 48.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-luqr0hl00pk535', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F7675845372', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15864043361', 'Cadeira de Praia e Piscina Master Plus 120 Kgs Alta em Alumínio Kit Com 2 Peças MOR', 'Cadeira de Praia e Piscina Master Plus Alta em Alumínio Kit Com 2 Peças 2112 Azul MORCombo com 2 cadeiras para praia e piscina, em alumínio.A Cadeira Master Plus Alumínio é um item que não pode faltar na sua casa.Em alumínio, ela fica ainda mais leve e durável, mesmo em regiões litorâneas.É excelente para praia, campo ou para um final de tarde com os amigos na varanda.Prática e fácil de carregar, ocupa pouco espaço quando dobrada, cabendo em qualquer cantinho.Anatômica, possui tubos estrategicamente posicionados para não pressionar as costas nem as articulações do corpo, tornando-se confortável para pessoas de todas as estaturas.Tem o encosto mais alto e o assento mais largo para adaptar-se às pessoas de mais idade, mais altas ou com sobrepeso.Dessa maneira, ela é mais confortável, mais estável e segura.Extremamente resistente, conta com estrutura fabricada pela Mor em alumínio de excelente qualidade.Além disso, suas peças plásticas são feitas em polipropileno, sua tela em 100 % poliéster com revestimento em PVC, além de suas sapatas antiderrapantes, que proporcionam ainda mais segurança ao utilizá-la.Tem capacidade para suportar até 120 Kg.DADOS TÉCNICOS:Quantidade: 2 unidades.Material: Alumínio.Cor predominante: Azul.Capacidade: 120 kg.Altura: 94,50 cm.Largura: 61,00 cm.Comprimento: 58,00 cm.Peso: 2,02 kg.Código de Fábrica: 002112Marca: MORGarantia: 3 meses* Imagens meramente ilustrativas.', 389.9, 389.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/edf35f03f6fdbf713b2a1ceaeba5ce2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F15864043361', NULL, NULL, '2026-07-28T02:11:31.708458+