INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697590355', 'Kit 5 Toalhas Rosto para Salão de Beleza SPA Hotel 48x80cm BF Casa', 'A linha branca de Toalhas Madri da marca Teka é produzida no mais puro algodão e possui 440g/m-b2, que proporciona alto nível de conforto e excelente absorção. Além disso, são muito duráveis e fáceis de lavar e limpar, o que garante a praticidade que você e seus clientes merecem. Ofereça o melhor e eleve seu negócio com a Linha Profissional da Teka. Características: Modelo: Madri Marca: Teka Tecido 90 Algodão e 10 Poliéster Gramatura: 440g/m-b2 Ótima absorção Toque macio Esse kit contém: 5 Toalhas de Rosto Dimensões: 48x80cm', 209.0, 151.0, NULL, 'Home & Living > Bathrooms > Towels & Bathrobes', 'https://cf.shopee.com.br/file/sg-11134201-7rd66-lweqjz2nk42d69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1264071501%2F22697590355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201363043', 'Energético Hudema Energy Drink 473 ml Edição Limitada Lata Black 4 Opalas', 'A Hudema Energy Drink chega acelerando com a sua Edição Especial de Lançamento, trazendo latas colecionáveis exclusivas inspiradas na trajetória do Opala Carbon na Arrancada Brasileira . São ilustrações únicas, cheias de atitude, estilo e velocidade! São 16 Latas Colecionáveis da Linha Hudema Energy Drink, sendo 8 latas de energético Zero Açúcar e 8 latas de energético Com Açúcar. Compre todas as latas aqui. Desenvolvido com fórmula exclusiva que combina taurina, cafeína e inositol, este energético potencializa seu desempenho físico e mental, ideal para dias de alta exigência e momentos de lazer. Destaques do produto: - Edição Limitada com design exclusivo inspirado no Lendário Opala Carbon de Josimar Hudema da Lista Área 43, maior Campeão de Armagedons da história, para você colecionar e experimentar essa nova emoção. - São 473 ml de energia concentrada para maior disposição durante o dia - Fórmula funcional que melhora o foco, a resistência e revitaliza o corpo - Refrescante, com sabor marcante e equilibrado - Produto aprovado para consumo imediato, pronto para te acompanhar onde precisar Não perca a oportunidade de colecionar e experimentar essa Edição limitada do Hudema Energy Drink, que já está fazendo barulho entre os fãs de carros e bebidas energéticas. Garanta já o seu e sinta o poder da energia que vai além do comum! P4OP', 22.0, 22.0, NULL, 'Food & Beverages > Beverages > Chocolate Drinks', 'https://cf.shopee.com.br/file/sg-11134201-8225e-mhrx6ls7qh3c7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F288347041%2F58201363043', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22791735036', 'Café Cápsulas Intenso c/ 10 Und Nespresso', 'Produzido com grãos 100% arábica e cuidadosamente torrado até a perfeição, este café de torra escura oferece um perfil de sabor robusto e encorpado, com notas de chocolate e caramelo, possuindo uma doçura sutil e acidez leve. Ideal para os apreciadores de café com um amargor mais presente. Nossas cápsulas de alumínio selam o frescor e o aroma do café gourmet, proporcionando uma experiência rica e autêntica a cada xícara. Compatíveis com máquinas Nespresso®, elas oferecem uma extração ideal, garantindo um café encorpado e saboroso. Aproveite a conveniência sem abrir mão da qualidade.', 33.9, 33.9, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-8261u-mkb4bqpn5v5s3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F654119500%2F22791735036', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
