INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293729034', 'Junta Homocinetica Roda Cofap Courier 1997 A 2006 Escort 1997 A 2003 Fiesta1996 A 2006', 'Seja Bem-vindo(a)!! É um prazer imenso tê-lo em nosso anuncio. Abaixo algumas informações sobre o Produto e Aplicação. Por fim, conheça um pouco mais sobre a nossa loja. Produtos: 1 Juntas Homocinética Fixa JHC08128. Marca: Cofap. Aplicação: Veículo: F. Courier; Motor: 1.4 16v; Ano de fabricação: 1997, 1998, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006; Observação: Transmissão Manual SEM ABS. Veículo: F. Escort; Motor: 1.6 8v Zetec Rocam; Ano de fabricação: 1997, 1998, 1999, 2000, 2001, 2002, 2003; Observação: Transmissão Manual SEM ABS. Veículo: F. Escort; Motor: 1.8 16v Zetec Rocam; Ano de fabricação: 1997, 1998, 1999, 2000, 2001, 2002, 2003; Observação: Transmissão Manual SEM ABS. Veículo: F. Fiesta; Motor: 1.4 16v Zetec; Ano de fabricação: 1996, 1997, 1998, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006; Observação: Transmissão Manual SEM ABS. Veículo: F. Fiesta; Motor: 1.8 16v Argentino; Ano de fabricação: 1996, 1997, 1998, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006; Observação: Transmissão Manual SEM ABS. Ficha Técnica: Fixa: Lado Roda (SEMI-EIXO); Medidas: 22 Dentes Interno - 25 Externo TRAVA EXTERNA; Código original: 97FU4K258CA 1525279; Observação: Para Ambos Os Lados (Esquerdo E Direito). Garantia 90 dias. Sobre a Loja: A RV Autopeças é uma empresa que trabalha exclusivamente com o setor de peças para veículos leves e médios, sendo eles nacionais ou importados. Oferecemos peças com qualidade, prazo de entrega, parcerias com as melhores marcas e eficiência no atendimento. Temos uma equipe de profissionais qualificados para orientar o cliente nas suas mais variadas necessidades relacionadas à manutenção do seu veículo. Oferecemos também um amplo estoque de peças e envios diários. Visamos constantemente o aperfeiçoamento e melhoria dos serviços para a satisfação total do cliente.', 221.77, 221.77, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rcf4-m6ed691d8ndg6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373135807%2F22293729034', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25448147699', 'Spray Hidratante de Couro 180g Proteção e Renovação Automotivo Roupas', 'COMERCIAL VIPASA DISTRIBUIDORA Spray Hidratante de Couro 180g Mundial Prime AE0400003 Proteção e Renovação Hidratante para Couro Spray 180g Mundial Prime para Bancos, Sofás e Jaquetas Spray Restaurador e Hidratante de Couro 180g Mundial Prime AE0400003 Hidratante Spray para Couro Automotivo e Residencial 180g Mundial Prime Spray Conservador de Couro 180g Mundial Prime Limpeza e Hidratação Hidratante para Bancos de Couro Spray Mundial Prime 180g Spray para Couro Ressecado e Proteção 180g Mundial Prime AE0400003 Hidratante e Protetor de Couro em Spray Mundial Prime 180g Descrição Completa e Detalhada O Spray Hidratante de Couro Mundial Prime AE0400003 foi desenvolvido para hidratar, proteger e revitalizar superfícies em couro natural e sintético, proporcionando maior conservação, brilho suave e aparência renovada. Sua fórmula auxilia na prevenção do ressecamento, rachaduras e desgaste causados pelo uso diário e pela exposição ao tempo, mantendo o couro com aspecto limpo, macio e protegido. Possui aplicação prática em spray, garantindo melhor distribuição do produto e facilitando o uso em diferentes superfícies. Indicado para uso automotivo e residencial, o hidratante pode ser utilizado em bancos de couro, sofás, cadeiras, poltronas, bolsas, jaquetas, sapatos e diversos acessórios confeccionados em couro. O produto promove limpeza leve e hidratação simultânea, ajudando a conservar a textura original do material sem deixar resíduos excessivos. Características do Produto Marca: Mundial Prime Modelo: AE0400003 Tipo: Spray hidratante para couro Conteúdo: 180g Aplicação prática em spray Hidrata e revitaliza superfícies em couro Auxilia na prevenção de ressecamento e rachaduras Proporciona brilho suave e aparência renovada Indicado para couro natural e sintético Uso automotivo e residencial Indicações de Uso Recomendado para: Bancos automotivos em couro Sofás e poltronas Cadeiras revestidas em couro Jaquetas e bolsas Sapatos e acessórios Superfícies em couro natural ou sintético Modo de Uso Certifique-se de que a superfície esteja limpa e seca. Agite bem a embalagem antes de usar. Aplique o produto diretamente sobre a superfície ou em um pano limpo e macio. Espalhe uniformemente em movimentos circulares. Aguarde alguns instantes para absorção. Se desejar, finalize com pano seco para melhor acabamento. Benefícios Hidrata e protege o couro Ajuda a prolongar a vida útil do material Mantém a aparência original Fácil aplicação em spray Ideal para manutenção preventiva Pode ser utilizado em ambientes automotivos e residenciais COMERCIAL VIPASA DISTRIBUIDORA.', 23.99, 23.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-820m4-mo7br2a387pgc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F25448147699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
