INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097473665', 'ELETROVENTILADOR RADIADOR CHEVROLET VECTRA', 'MOTOR VENTILADOR RADIADOR SE QUISER CONFIRMAR A APLICAÇÃO ANTES DA COMPRA, PODE CONTAR COM A GENTE. VOCÊ PODE: CONFERIR O CÓDIGO ORIGINAL DA PEÇA OU, SE PREFERIR, ENVIAR UMA FOTO AQUI NO CAMPO DE PERGUNTAS RESPONDEMOS COM ATENÇÃO E RAPIDEZ PRA TE AJUDAR A ACERTAR NA ESCOLHA. ESPECIFICAÇÕES TÉCNICAS · VOLTAGEM: 12V CÓDIGOS ORIGINAIS · BOSCH - F.006.KMO.612 CÓDIGOS SIMILARES APLICAÇÕES GM VECTRA 2.0, 96 > 05; 2.2, 97 > 05 REFERÊNCIA · CEMAK: CK-2.612 GARANTIA 3 MESES INFORMAÇÕES IMPORTANTES PRODUTO NOVO ACABAMENTO DE ALTA QUALIDADE BOA DURABILIDADE PARA USO NO DIA A DIA DA OFICINA ANTES DA COMPRA PARA GARANTIR A APLICAÇÃO CORRETA, RECOMENDAMOS: CONFERIR O CÓDIGO ORIGINAL DA PEÇA COMPARAR COM AS IMAGENS E ESPECIFICAÇÕES DO ANÚNCIO SE PREFERIR, PODE NOS CHAMAR NO CAMPO DE PERGUNTAS FICAMOS À DISPOSIÇÃO PRA TE AJUDAR A CONFIRMAR ANTES DA COMPRA. INSTALAÇÃO A INSTALAÇÃO DEVE SER REALIZADA POR PROFISSIONAL QUALIFICADO. ISSO GARANTE O MELHOR DESEMPENHO DA PEÇA E EVITA QUALQUER TIPO DE PROBLEMA NO SISTEMA. SOBRE ATENDIMENTO E SUPORTE SE HOUVER QUALQUER DÚVIDA OU NECESSIDADE APÓS A COMPRA, PODE CONTAR COM A GENTE. EM CASO DE DIVERGÊNCIA EVITE UTILIZAR-SE DO CAMPO RECLAMAÇÃO, NESTE CASO, NOS CHAME PELO CHAT QUE NOSSA EQUIPE ESTÁ PRONTA PRA TE AJUDAR DA FORMA MAIS RÁPIDA E SIMPLES POSSÍVEL. INFORMAÇÕES DO PRODUTO TODAS AS INFORMAÇÕES TÉCNICAS SÃO FORNECIDAS PELO FABRICANTE. SOBRE A PEÇA DO MECÂNICO A PEÇA DO MECÂNICO TRABALHA COM FOCO EM QUEM VIVE DA MECÂNICA E PRECISA DE AGILIDADE, CLAREZA E CONFIANÇA NO DIA A DIA. SE SURGIR QUALQUER DÚVIDA ANTES OU DEPOIS DA COMPRA, PODE CHAMAR. A IDEIA É FACILITAR SEU TRABALHO.', 260.0, 260.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk19qb1i5fk1cc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1213682031%2F23097473665', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
