INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098739287', 'Umidificador de Ar Portátil Ultrassônico Silencioso 5V USB ON-UM613 Led Decorativo', 'Umidificador de Ambiente ON-UM613 – Design moderno e alívio imediato para o clima seco! Refresque o ar e melhore sua qualidade de vida com o Umidificador ON-UM613. Equipado com tecnologia ultrassônica silenciosa, ele é ideal para ambientes como quartos, salas, escritórios e até o carro. Seu design moderno e colorido se destaca na decoração, ao mesmo tempo em que proporciona um clima mais agradável e saudável. ✓ Tecnologia ultrassônica: alívio rápido contra o ar seco ✓ Silencioso e portátil – ideal para uso doméstico e no trabalho ✓ Visual moderno com iluminação decorativa sutil ✓ Alimentação prática via USB (ideal para notebooks e power banks) ✓ Compacto, eficiente e de fácil operação Especificações Técnicas: - Modelo: ON-UM613 - Tecnologia: Ultrassônica - Alimentação: 5V via porta USB - Iluminação: LED decorativa Conteúdo da Embalagem: 1x Umidificador de Ar ON-UM613 1x Cabo USB 1x Manual do usuário', 40.0, 27.32, NULL, 'Home Appliances > Small Household Appliances > Air Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcghatc6ilo213', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F23098739287', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
