INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200360478', 'Vestido Feminino Longo Com Franzidos Marialícia Preto', 'O Vestido Marialícia é a escolha perfeita para quem busca elegância com conforto. Feito em tecido de viscose sarjada, ele possui comprimento longo e recortes assimétricos franzidos por toda a peça, garantindo uma modelagem soltinha e que transmite a leveza que o verão pede. Além disso, conta com alças finas e elástico nas costas. Ideal para passeios ao ar livre, jantares casuais ou encontros especiais, esse vestido promete um destaque charmoso para qualquer ocasião.Detalhes da peça: • Feito em tecido de viscose sarjada • Possui comprimento longo • Possui alças finas • Possui recortes franzidos e assimétricos • Ideal para passeios, jantares ou encontros especiais', 249.9, 124.95, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-825b4-mr1tmwz81ij0be', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58200360478', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
