INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259709289', 'Salsicha Hot-Dog Perdigão', 'A Salsicha Hot-Dog Perdigão é a escolha ideal para um lanche rápido e saboroso! Perfeita para cachorros-quentes, aperitivos ou como acompanhamento em diversas refeições. * Modo de Preparo: Retire as salsichas da embalagem e coloque-as em uma panela com água fervente em quantidade suficiente para cobri-las. Deixe-as aquecer por cerca de 3 a 4 minutos e sirva. Informação Nutricional (porção de 50g): * Valor Energético: 94 kcal * Carboidratos: 1,8g * Açúcares Totais: 0,4g * Proteínas: 6,8g * Gorduras Totais: 6,6g * Sódio: 445mg', 18.79, 18.79, NULL, 'Food & Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zua-miyqbvfbcc8y46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F58259709289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26741666247', 'Kit Pastilhas de Freio P/ Honda Transalp 700 2004-2014 Sem Abs Diafrag (Cerâmica)', 'Kit Pastilhas de Freio Trail Ceramic - Diafrag Pastilhas de freio em material cerâmico de última geração. (Sinterizada) Tecnologia exclusiva para off-road e usos extremos (Cross-Enduro) Aplicação Dianteira e Traseira HONDA TRANSALP 700 SEM ABS 2004 TRANSALP 700 SEM ABS 2005 TRANSALP 700 SEM ABS 2006 TRANSALP 700 SEM ABS 2007 TRANSALP 700 SEM ABS 2008 TRANSALP 700 SEM ABS 2009 TRANSALP 700 SEM ABS 2010 TRANSALP 700 SEM ABS 2011 TRANSALP 700 SEM ABS 2012 TRANSALP 700 SEM ABS 2013 TRANSALP 700 SEM ABS 2014 Conteúdo da Embalagem: 01 Par de Pastilhas de Freio Dianteira (Lado Direito) Diafrag Trail (Cerâmica) 01 Par de Pastilhas de Freio Dianteira (Lado Esquerdo) Diafrag Trail (Cerâmica) 01 Par de Pastilhas de Freio Traseira Diafrag Trail (Cerâmica) Especificações Técnicas: - Sinterizada - Material: Cerâmica - Não agride os discos; - Alta durabilidade comparada as pastilhas orgânicas ou kevlar; - Durabilidade e qualidade; - Maior qualidade na frenagem; - Melhor opção para uso em terreno molhado, seco ou arenoso. Importante Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto. Verifique, antes da compra, se as medidas das pastilhas são compatíveis com a da sua moto.', 119.9, 107.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-824j3-merjv0eh5344b2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F26741666247', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16378223898', 'Chave de Ignição Tornado 250 2001-2005 / Falcon 400 2001-2005 Magnetron', 'Chave de Ignição MAGNETRON Compatível com: HONDA NX4 400 FALCON (2001-2005) XR 250 TORNADO (2001-2005) Conteúdo da Embalagem: 01 Miolo de Ignição 01 Chicote 02 Chaves Código Original: 35100-KPE-900 / 35100-MCG-000 A chave de ignição Magnetron é produzida com material de alta qualidade e garantia de funcionamento perfeito e maior segurança para a sua moto. Mantém o padrão de fabricação da montadora com as mesmas especificações da peça original. Responsável pela função de alimentação elétrica, a chave de ignição permite o desligamento ou a partida (ignição) da moto. A chave também tem a função de fazer o travamento (bloqueio) do guidão, impedindo que moto seja movimentada com facilidade sem o uso da chave. Instalação: - Este produto possuí fácil instalação, não exige que mude a estrutura de sua moto, pois foi confeccionado seguindo as especificações do produto original, para encaixe e funcionamento perfeito. Vantagem: - Agora você pode desfrutar de um produto com qualidade do original, para uma melhor reposição em sua moto e com baixo custo. - Produto elaborado com material de alta qualidade, testado e aprovado dentro das normas de segurança. Importante: - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 129.9, 103.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Ignition', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4sx4mbe2ixcb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F16378223898', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
