INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493241695', 'Lápis Delineador de Sobrancelhas - Color Icon Brow Pencil', 'Color Icon Brow Pencil Lápis Delineador de Sobrancelhas com Escova - wet n wild Sobrancelhas bem definidas fazem toda a diferença na maquiagem. E para garantir que elas estejam sempre impecáveis, apresentamos nosso lápis de sobrancelha, Color Icon Brow Pencil, de ponta dupla! Com uma escova de um lado e uma ponta cremosa e rica do outro, é fácil preparar, desenhar e definir suas sobrancelhas de maneira suave e natural. A escova ajuda a pentear e domar os pelos, enquanto a ponta do lápis preenche falhas e define a forma. Sua textura leve e cremosa desliza facilmente sobre a pele, criando sobrancelhas perfeitas em segundos. Com este lápis de sobrancelha, você verá a diferença que um par de sobrancelhas bem feitas pode fazer na sua aparência. Experimente e descubra por si mesmo por que este é o melhor lápis de sobrancelha que você já usou! Benefícios: Lápis 2 em 1 de ponta dupla; A cor rica e leve dura o dia todo; Escova para pentear Disponíveis nas Cores: Blonde Moments Black Ops Brunettes Do It Better Ginger Roots', 53.32, 39.46, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-7rdwx-lzi55pt2fypg32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F572166540%2F23493241695', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
