INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8311138838', 'Caneca de Vidro Alaska para Cerveja 365ml - Ruvolo', 'A Caneca de Vidro Alaska para Cerveja 365ml é perfeita para quem aprecia uma boa cerveja com estilo e praticidade. Com seu design elegante e robusto, esta caneca de vidro oferece a melhor experiência para degustar sua bebida favorita. Com capacidade de 365ml, ela é ideal para quem quer servir a quantidade perfeita de cerveja, sem perder o toque tradicional de uma boa caneca de vidro. A transparência do material permite que você admire o brilho e a cor da sua cerveja, tornando o momento ainda mais prazeroso. Feita de vidro de alta qualidade, a Caneca de Vidro Alaska para Cerveja é durável e resistente, sendo uma escolha certeira para o uso diário ou para ocasiões especiais. A alça ergonômica proporciona um manuseio confortável, enquanto seu design sóbrio e moderno combina com qualquer ambiente. Seja em uma reunião descontraída com amigos ou em um jantar mais formal, esta Caneca de Cerveja é a combinação perfeita de funcionalidade e estilo. Indicada para: Cerveja. Material: Vidro. Conteúdo da Embalagem: 1 Caneca. Capacidade: 365ml. Medidas: Diâmetro 66mm x Altura 160mm. - Peça medida com o volume máximo até a boca - Diâmetro é medido pela largura maior da peça. - Pode sofrer variação de até 10% de seu volume Dica de uso e preservação: • Recomendamos que a limpeza da peça seja feita a mão para evitar quebras ou danos. • Limpe a sujeira utilizando uma esponja macia, tire o resíduo de sabão e seque bem. • Não utilize abrasivos ou utensílios pontiagudos. • Evite impactos e não exponha o vidro a mudanças bruscas de temperatura pois poderá causar choque térmico e danificar seu produto. • Para realçar ainda mais o brilho da peça, limpe-a com uma flanela que não solte fiapos, levemente umedecida com álcool.', 44.99, 44.99, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/81b37aa370cb0b855b7742cc8d607bfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373594761%2F8311138838', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197354185', 'Tinta Spray Premium Uso Geral 350ML Multiuso Secagem Rápida Uso Interno/Externo', 'Tekspray Tinta Super Color Uso Geral Tinta acrílica de secagem rápida e ótima resistência às intempéries, proporcionam excelentes acabamentos, poder de cobertura e efeito decorativo. Pode ser utilizada em ambientes internos e externos para aplicações em ferro, aço, madeira, cerâmica, gesso, entre outros. Instruções de Uso - Preparo da superfície: 1. Proteja as partes que não serão pintadas com papel, papelão ou plástico. 2. Aplique de 2 a 3 demãos em camadas bem finas. 3. Entre cada demão de verniz, aguarde um intervalo de 1 a 3 minutos. 4. Para o toque aguarde um intervalo de 30 minutos. 5. Para manuseio da peça aguarde um intervalo de 3 horas. 6. Cura total em 24 horas e para testes mecânicos, recomendamos 72 horas. Rendimento aproximado: 1,7 m2 a 2,1 m2 por embalagem.', 38.09, 24.76, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9yf4dxmedrt7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1190424233%2F23197354185', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
