INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792177744', 'Jogo de Chaves de Fenda 5 Peças Tramontina PRO', 'Seja em manutenções industriais ou automotivas, apertar ou afrouxar parafusos se torna mais fácil com a ajuda da Chave Twister da Tramontina PRO. Esta chave de fenda proporciona maior conforto e firmeza na utilização, devido a sua extremidade giratória e as saliências no cabo. Ideal para trabalhos em locais de difícil acesso, as chaves estão disponíveis em ponta chata e cruzada, nos modelos tradicional e toco. É mais uma inovação que compõe a linha de ferramentas industriais da Tramontina PRO. Agilidade e eficiência: características de quem é PRO. Haste em aço cromo vanádio temperada.Acabamento cromado.Ponta fosfatizada e magnetizada.Cabo injetado.Apoio giratório.DIN ISO 2380.Ponta chata.As hastes das chaves de fenda são testadas em máquina de ensaio específica, para verificar o perfeito balanço entre resistência mecânica e dureza.Os dimensionais das pontas são verificados com gabaritos-padrão calibrados e certificados, e a qualidade do fosfato é inspecionada ao microscópio.Apertar ou afrouxar parafusos de fenda simples.As ferramentas são produzidas e testadas conforme normas específicas.* Medidas Chaves de Fenda: Chave de fenda TWISTER ponta chata 3x75mm (1/8x3"), 5x100mm (3/16x4"), 6x100mm (1/4x4"), 6x150mm (1/4x6"), 8x150mm (5/16x6"). Seja em manutenções industriais ou automotivas, apertar ou afrouxar parafusos se torna mais fácil com a ajuda da Chave Twister da Tramontina PRO. Esta chave de fenda proporciona maior conforto e firmeza na utilização, devido a sua extremidade giratória e as saliências no cabo. Ideal para trabalhos em locais de difícil acesso, as chaves estão disponíveis em ponta chata e cruzada, nos modelos tradicional e toco. É mais uma inovação que compõe a linha de ferramentas industriais da Tramontina PRO. Agilidade e eficiência: características de quem é PRO.', 56.4, 56.4, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkpeae4it568ef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23792177744', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892259825', 'Chave de Fenda Isolada Ponta Chata em Aço Cromo Vanádio 3x200 mm (1/8x8'''') Tramontina PRO', 'Seja em manutenções industriais ou automotivas, apertar ou afrouxar parafusos se torna mais fácil com a ajuda das Chaves Easygrip da Tramontina PRO. Seu cabo com formato sextavado proporciona maior conforto e agilidade na utilização. Estão disponíveis com ponta chata, cruzada, trafix, trafix PZ e canhão nos modelos tradicional, toco e com isolação. Escolha o tamanho ideal para o seu trabalho e mãos à obra. Haste em aço cromo vanádio temperada. Ponta fosfatizada. Cabo em PVC verde transparente. Isolação de 1000 V c. a. Produto em conformidade com a NBR9699 e NR10. DIN ISO 2380. As hastes das chaves de fenda são testadas em máquina de ensaio específica, para verificar o perfeito balanço entre resistência mecânica e dureza. Os dimensionais das pontas são verificados com gabaritos-padrão calibrados e certificados, e a qualidade do fosfato é inspecionada ao microscópio. As chaves de fenda isoladas são amplamente testadas, o que promove segurança na sua utilização em locais com tensões de até 1000 V c. a. Indicada para trabalhos em redes de tensão até 1.000 volts c. a. As ferramentas são produzidas e testadas conforme normas específicas.', 19.12, 19.12, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkmeynj6wh743b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22892259825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
