INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22091483864', 'SUPORTE GUITARRA BAIXO CHÃO ASK G5 PORTÁTIL RETRÁTIL', 'SUPORTE DE CHÃO ASK G5 PARA GUITARRA E BAIXO PORTÁTIL RETRÁTIL Atuando em todo território nacional, a ASK tornou-se uma marca respeitada e hoje possui posição consolidada como líder no mercado de suportes para instrumentos musicais, direcionando todo seu trabalho na busca pela sofisticação aliada à excelência em qualidade.Desenvolvido para ser compacto e seguro, o G5 da ASK é um otimo suporte para guitarras e baixo , dobravel, pode ser levado em qualquer bag ou case. Suporte portátil para guitarra ou baixo. Categoria: Instrumento De Corda Peso (kg): 0,410 Capacidade de Carga (kg): 5 Embalagem (C x L x A / cm): 4 x 17,5 x 38 Altura (cm): 24 Largura (cm): 22 Comprimento (cm): 26 Material: Aço / Plástico Características Especiais: Totalmente retrátil, produto compacto que não requer ajustes. Imagens meramente ilustrativas. O anúncio se aplica ao Pedestal B12G. Não acompanha prato.', 58.34, 52.51, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7qvd9-lhxojy3moed41d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1006271683%2F22091483864', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23191743330', 'Máquina de Fazer Pão Panificadora Britânia Multipane PR Automática', 'Panificadora Britânia Multipane PR Automática: Pão fresco e saboroso na hora que você quiser! Imagine acordar com o aroma irresistível de pão fresco assando em casa. Com a Panificadora Britânia Multipane PR Automática, essa experiência deliciosa é possível todos os dias! Versatilidade para todos os gostos: Prepare pães de diversos tamanhos (450g, 600g, 900g e 1200g) e cores (claro, médio e escuro) para atender às suas preferências. Explore 12 programas diferentes para criar pães doces e salgados, geleias, pudins, panetones e muito mais! Praticidade para o seu dia a dia: A função timer permite agendar o preparo do pão com até 13 horas de antecedência, para que ele esteja pronto na hora desejada. A forma removível com revestimento antiaderente facilita a limpeza e garante pães perfeitamente assados. O visor de vidro temperado permite acompanhar o processo de preparo sem precisar abrir a tampa. Facilidade de uso: Basta adicionar os ingredientes, escolher o programa desejado e pressionar um botão. A Multipane PR Automática faz o resto! Com a Panificadora Britânia Multipane PR Automática, você terá pães frescos, saborosos e feitos com carinho na sua mesa todos os dias ESPECIFICAÇÕES TÉCNICAS: Capacidade (kg): 3 Forma antiaderente: Sim Função manter aquecido: Não Timer: Sim Programa de preparo: Sim Ajuste da cor do pão: Sim Base antiderrapante: Não Porta fio: Não Consumo (kWh): - 110V: 0,55kWh - 220V:0,55kWh Potência (W): 110V: 550W 220V:550W Peso (kg): 5.5 Referência: Multipane PR Dimensões (AxLxP): 30,8 x 28,7 x 40,7cm Itens Inclusos: - 1 Panificadora Britânia Multipane PR Automática - Manual do produto Informações importantes: Imagens meramente ilustrativas. Objetos que ambientam as fotos não acompanham o produto. As tonalidades das cores dos produtos podem sofrer alterações de acordo com a calibração do seu monitor. Este produto não inclui montagem e instalação. Não nos responsabilizamos, no ato da entrega, por desmontagens, subir escadas, elevadores ou transporte por guincho para apartamentos. Eventuais despesas são de responsabilidade do cliente. Registro INMETRO: SGS OCP 0040 Garantia Fabricante:12 meses', 810.9, 810.9, NULL, 'Home Appliances > Kitchen Appliances > Specialty Cookware', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lj4bruaddrjkcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F889942432%2F23191743330', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
