INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398402312', 'Carrinho de Bebê e Berço Moises Napoli Preto Cobre Galzerano', 'Carro de Passeio Bebê com Cesto Moises Napoli Preto Cobre Galzerano Praticidade, segurança e conforto são itens importantes num carrinho para bebê, certo? Tudo isso e muito mais você encontra na nova versão do carro de bebê Napoli da Galzerano, um carrinho berço-passeio, que se transforma em cesto-moises e que permite o acoplamento do bebê conforto grid (vendido a parte) em sua estrutura. É conforto na hora do bebê dormir, pois o cesto oferece um espaço aconchegante e é praticidade no transporte e no passeio do bebê, pois o carrinho é compacto e tecnológico. Esse Carrinho de Bebê da Galzerano é indicado para recém nascidos e bebês com peso até 15kg. Principais Características do Carrinho de Passeio para Bebês c/ Moisés Napoli PTC Galzerano: • Carro berço-passeio destinado para crianças a partir de 0 meses com peso até 15 kg;• Assento reversível, também se transforma em moisés;• Protetor frontal removível;• Cinto de segurança 5 pontos;• 2 Rodas dianteiras giratórias;• 2 Rodas traseiras com único sistema de freio;• Acopla Dispositivo de Retenção Cocoon ref. 8181 ou 8184;• Registro do produto no INMETRO – Nº 000714/2023.', 1150.8, 899.99, NULL, 'Mom & Baby > Baby Travel Essentials > Strollers & Travel Systems', 'https://cf.shopee.com.br/file/sg-11134201-7req0-m8nymhpwfvyv44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1479622710%2F23398402312', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
