INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252376755', 'Boné Esportivo Unissex Proteção Uv+ - Snugg', 'O Boné Esportivo Unissex Proteção Uv+ - Snugg é a escolha definitiva para pescadores e apaixonados pela marca que buscam conforto, proteção e autenticidade em cada detalhe. Confeccionado em 100% poliéster, oferece leveza, respirabilidade e resistência, tornando-o perfeito para longos dias de pesca, aventuras ao ar livre ou até mesmo para o uso casual no dia a dia. Seu design clássico e atemporal combina praticidade e estilo, enquanto o bordado em alto-relevo com o logotipo Snugg reforça sua paixão pela pesca esportiva e pela marca referência mundial no setor. O modelo é de tamanho único com regulagem traseira por fecho autocolante ajustável, garantindo encaixe perfeito e máximo conforto para diferentes biotipos. A aba curva protege eficazmente contra os raios solares e reflexos da água, oferecendo não somente estilo, mas também funcionalidade em cada uso. Não perca tempo e garanta já seu Boné Esportivo Unissex Proteção Uv+ - Snugg aqui na Dispropil! Especificações Técnicas: - Marca: Snugg - Modelo: Boné Esportivo Unissex Proteção Uv+ - Snugg - Ref: SBA - Material: 100% poliéster - Tamanho: Único. - Aba: Curva. - Bordado: Alto-relevo com logotipo Snugg - Uso: Atividades ao ar livre, pesca esportiva e casual. Itens Inclusos: - 01 Boné Esportivo Unissex Proteção Uv+ - Snugg', 44.98, 42.74, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/sg-11134201-81zvg-mim0ltp2j8jlae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1063297286%2F58252376755', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
