INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998358537', 'Cilindro Roda Ford Escort 1996 a 2000 - 1356131 - CCR9257', 'Cilindro Roda Ford Escort 1996 a 2000 1356131 CCR9257 (Sedan) 1.8 (16V) - TRASEIRO DIREITO (11/16" OU 17,78mm - SISTEMA VARGA)O Conjunto de Cilindro de Roda é utilizado em veículos cujo sistema de freios é a tambor. Ele aciona os freios na roda quando recebe pressão hidráulica enviada pelo cilindro mestre, assim, as sapatas são empurradas dando o atrito no tambor de freio, fazendo com que a roda freie e pare o veículo.', 67.33, 67.33, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd3n-m7ui51abfz2558', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22998358537', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
