INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40811645699', '5 Baterias Pilha Moeda Cr2032 3v Blister Cartela Elgin', 'Pilha Moeda CR2032 3V Elgin Blister com 5 Unidades Perfeita para relógios, placas de computador e alarmes automotivos, ela garante desempenho consistente, segurança e praticidade para o seu dia a dia. Por que comprar a Pilha Moeda CR2032 Elgin? A Elgin é referência em qualidade e inovação quando o assunto é energia portátil. Com alta durabilidade, tecnologia livre de metais pesados e excelente custo-benefício, essa bateria é a escolha ideal para quem não pode ficar sem seus dispositivos funcionando. Sobre o produto: -Pilha Moeda CR2032 3V. -Marca: Elgin. -Contém: 1 blister com 5 unidades. -Voltagem: 3 Volts. -Dimensões: 3,2 x 20 mm. -Alta durabilidade. -0% de metais pesados. -Economia e qualidade. Indicado para: -Relógios. -Placas de computadores. -Alarmes automotivos. Modo de uso: -Abra o compartimento de pilhas do aparelho. -Retire a pilha antiga, se houver. -Insira a Pilha CR2032 Elgin, respeitando a posição correta dos polos. -Feche o compartimento e utilize o dispositivo normalmente. Precauções: -Não recarregar. -Manter fora do alcance de crianças. -Evitar exposição ao calor excessivo. -Descartar em local adequado para baterias. Com a confiança da marca Elgin, você garante energia contínua, segura e duradoura para seus aparelhos. Adquira já a sua e mantenha tudo funcionando sem preocupações! Surgiu alguma dúvida? Entre em contato com a gente! Boas Compras :)', 22.48, 17.54, NULL, 'Home Appliances > Batteries', 'https://cf.shopee.com.br/file/sg-11134201-825b8-mfsj0ohmgky231', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371678536%2F40811645699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
