INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19457310714', 'Coloração Keune So Pure Color 7 Louro Médio', 'A Coloração Keune So Pure Color Foi desenvolvida com a tecnologia mais avançada para evitar danos a saúde dos cabelos, sua fórmula não contém amônia e é enriquecida com Fitoqueratina e óleo de Argan. A Coloração Keune So Pure Color possibilita 100% de cobertura dos fios brancos, E livre de PPD Parafenilenodiamina (grande causador de alergias), além de possui extratos 100% naturais, que hidrata seus cabelos enquanto colore. Ativos: - Fitoqueratina: Extraída de plantas que proporciona fortalecimento e brilho aos cabelos; - Extrato de Coco: evita que a coloração manche a pele e o couro cabeludo e condiciona os cabelos; - Óleo de Argan: Proporciona fortalecimento dos fios e proteção contra agentes externos; - Jasmin: Hidrata os cabelos, e evita oxidação e o desbotamento da cor; - Sândalo: Auxilia no equilíbrio de couro cabeludo seco e oleoso. Sobre a marca: Produzimos produtos para o cabelo para profissionais desde 1922, mas somos mais que um fornecedor. Seja nosso parceiro e você se juntará automaticamente à nossa família global. E não estamos dizendo isso apenas porque somos uma empresa familiar. Nós realmente nos preocupamos com você, seu salão e a pessoa em sua cadeira. É por isso que fazemos negócios com um toque pessoal.', 128.12, 94.9, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-82595-mqduzknu4tfv11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F19457310714', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
