INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993479453', 'Devocional Na Presença do Pai - Naor Pedroza', '📝 Descrição: O Devocional Na Presença do Pai é ideal para quem deseja começar o dia com uma mensagem de fé, esperança e intimidade com Deus. Com reflexões diárias escritas por Naor Pedroza, esta obra convida o leitor a ouvir a voz do Pai, renovar a mente e fortalecer o coração. Cada devocional é breve, profundo e inspirador, tornando-se um companheiro espiritual para todas as manhãs. Seu formato prático e conteúdo acolhedor fazem deste livro uma excelente opção para quem busca crescimento espiritual e paz interior. 📄 Ficha técnica: Título: Devocional Na Presença do Pai Autor: Naor Pedroza Editora: Vida Ano de publicação: 2024 ISBN: 9786555845433 Idioma: Português Número de páginas: 384 Formato: Brochura Dimensões: 23 cm x 16 cm Peso: 300 g Categoria: Devocional, espiritualidade cristã, vida cristã Indicação etária: A partir de 7 anos 🔍 Palavras-chave: devocional na presença do pai, naor pedroza, editora vida, devocional cristão, fé diária, intimidade com deus, crescimento espiritual, vida cristã, paz interior, reflexão bíblica', 79.98, 79.98, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1pisu9wa6z55a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F23993479453', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
