INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199212589', 'LAMINA DE CORTE MULTIFERRAMENTA, RETA, HCS, PARA MADEIRA, 34 X 2,5 MM, DENTE GROSSO, 1PC// DENZEL', 'Acessório de corte de ranhura reta para Denzel 78231555, 34 x 2,5 mm, com dentes grandes, feito de aço HCS, utilizado como elemento de corte de reposição no MFI. Pode ser usado para cortar madeira, compensados, revestimentos laminados, plástico e drywall. Equipamentos com alto teor de manganês são projetados para cargas intensas, por isso permitem resolver problemas profissionais durante trabalhos de reparação e construção. Vantagens Material durável - o bico é feito de aço ferramenta com alto teor de carbono, portanto é resistente ao desgaste e a altas cargas. Os dentes grandes estão dispostos em duas fileiras - o equipamento oferece uma combinação de alta velocidade e cortes limpos. Escala de trabalho milimétrica - é fácil controlar a profundidade de corte, o que permite obter precisão detalhada ao executar as tarefas atribuídas. Ajuste universal - o acessório pode ser instalado em praticamente qualquer renovador. Marcações claras significam que você pode encontrar rapidamente o acessório certo em seu local de trabalho.', 18.52, 18.52, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821f8-mh7oeijmacjw1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F22199212589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
