INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6451701186', 'Papel De Parede Para Cozinha Cervejas', '🏠 Papel de Parede Autocolante (Adesivo de Parede) Transforme sua parede de forma prática e elegante com nosso Papel de Parede Autocolante, fácil de aplicar e sem necessidade de cola. 📏 Características do Produto • Largura padrão: 50 cm • Autoadesivo: não é necessário usar cola • Limpeza: apenas água, sabão neutro e pano macio com movimentos suaves • Sobreposição: 3 mm de um rolo sobre o outro para encaixe perfeito 📐 Medidas Cada modelo está disponível nas alturas 2,50 m, 2,70 m e 3,00 m. Também fazemos sob medida — basta solicitar no campo de perguntas. • Escolha o rolo com comprimento igual ou superior à altura da sua parede para evitar emendas na vertical; emendas ocorrerão apenas na largura da parede. • Adquira a quantidade necessária ou com sobras, pois caso faltem rolos ou haja necessidade de reposição, as tonalidades podem variar, já que cada pedido é produzido em lote único. 🖌️ Aplicação Recomendada • O produto adere apenas em paredes amaciadas, ou seja, com acabamento em massa corrida seguida de pintura. • Pode ser aplicado também sobre vidros, azulejos, madeiras lisas, mesas e móveis sem texturas, mas marcas podem aparecer no acabamento. • Não adere em paredes rebocadas e pintadas de forma simples, e neste caso não há garantia. 📦 Observações Importantes • Todos os rolos são enviados separados, numerados e identificados no rodapé — abra a embalagem e confira a quantidade e medidas. • Todos os modelos são feitos com gabaritos e conferidos, garantindo que as emendas casem 100% lado a lado, respeitando a sobreposição de 3 mm. • A tonalidade do produto pode variar ligeiramente devido à calibração de cores de monitores ou celulares. 💬 Para qualquer dúvida, entre em contato com nosso suporte pelo campo de perguntas.', 33.9, 33.9, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/br-11134201-7qukw-lhq9scxpg07x71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303439692%2F6451701186', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797728162', 'Tinta Master Premium Lavável Anti Mofo Acrílica Parede Fosca Branco 3,6 L Interior Coral', 'TINTA ACRÍLICA MASTER PREMIUM 3,2L TIPO: ACRÍLICA ACABAMENTO: Fosco AMBIENTE INDICADO: Interno e exterior SUPERFÍCIE DE APLICAÇÃO: Indicado para superfícies de alvenaria, gesso e blocos de concreto. DILUIÇÃO: 40% com água potável RENDIMENTO: até 28m² por embalagem DEMÃOS: 2 a 3 demãos. BENEFÍCIOS: Maior rendimento, excelente cobertura, fácil de aplicar e retocar VOLUME: 3,2L EMBALAGEM: Galão SECAGEM AO TOQUE: 30 minutos SECAGEM ENTRE DEMÃOS: 4 horas SECAGEM FINAL: 4 horas Atuando há mais de 10 anos no mercado, a LB MATERIAIS de Construção oferece tudo o que você precisa para realizar seu sonho de construção e reforma! Em caso de dúvidas, fale conosco deixando a sua pergunta no campo de "Perguntas e Respostas", estamos à disposição para melhor atendê-los. Boas compras, Equipe LB MATERIAIS.', 165.9, 149.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lzp1n2zbyurlf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F705932885%2F22797728162', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20255084603', 'Bioderma Pigmentbio Foaming Creme Esfoliante e Clareador 200ml', 'Pigmentbio Foaming Cream É a 1 Higiene Diária com Ação Clareadora Para o Rosto e Corpo Que Renova, Ilumina e Potencializa Os Resultados de Tratamentos Clareadores. Através Dos Ativos Azelato de Lisina e Andrographolide, o Gel de Limpeza Inibe a Formação da Hiperpigmentação Agindo Diretamente Nas Marcas Escurecidas No Corpo e Rosto Para Ajudar a Uniformizar a Tonalidade da Pele. Graças Ao Ácido Cítrico e às Microesferas de Celulose Biodegradáveis em Sua Composição, Pigmentbio Foaming Cream Promove Uma Microesfoliação Suave e Acelera a Renovação Celular. a Combinação Dos Ativos Ajuda a Remover o Excesso de Melanina Depositado Sobre a Epiderme, Tornando Apele Iluminada, Uniforme e Renovada Desde o Banho. Inovação Bioderma Que Não Agride o Seu Corpo e Nem o Planeta.', 135.9, 132.9, NULL, 'Beauty > Skincare > Face Scrub & Peel', 'https://cf.shopee.com.br/file/sg-11134201-22100-6z1tyefi6niv60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F20255084603', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194657871', 'Cama Montessoriana Solteiro Encanto 100% Espuma Azul Marinho Keiko', 'Os primeiros passos. As primeiras noites dormindo sozinha. As primeiras histórias antes de dormir. As primeiras brincadeiras no próprio quarto. A infância é feita de momentos que ficam para sempre na memória, e a Cama Montessoriana Keiko Encanto foi criada para fazer parte de cada um deles, oferecendo liberdade para explorar, conforto para descansar e segurança para que pais e filhos aproveitem essa fase com tranquilidade. Produzida 100% em espuma de alta qualidade, sem madeira, pregos ou quinas rígidas, ela proporciona um ambiente macio e seguro para dormir, brincar e crescer. Seu design rente ao chão incentiva a independência desde os primeiros anos, permitindo que a criança entre e saia da cama sozinha, com muito mais segurança do que camas convencionais ou berços altos. A Encanto se destaca pela sua elegante cabeceira de 90 cm de altura, com design arredondado e moderno, que valoriza ainda mais a decoração do quarto infantil. Suas laterais proporcionam um confortável apoio para momentos de leitura, descanso e histórias antes de dormir, criando um ambiente acolhedor, funcional e preparado para acompanhar o crescimento da criança. Porque a infância passa rápido... e os melhores momentos começam em um lugar seguro para sonhar, brincar e crescer. Diferenciais - Cabeceira de 90 cm com design arredondado - Ideal para leitura e momentos em família - Estrutura 100% em espuma de alta qualidade - Sem madeira, pregos ou quinas rígidas - Estrutura rente ao chão - Incentiva a autonomia da criança - Colchão removível - Base antiderrapante com isolamento térmico - Suporta até 120 kg Itens Inclusos - Cama Montessoriana - Colchão - 1 travesseiro O colchão é removível, podendo ser substituído futuramente por outro de sua preferência. Atenção às medidas Antes de finalizar a compra, confira as medidas do ambiente e compare com as dimensões do produto. Verifique se haverá espaço suficiente para: - abrir portas; - abrir gavetas e armários; - circular confortavelmente pelo quarto. Essa simples conferência evita transtornos e garante que o modelo escolhido se encaixe perfeitamente no ambiente. Dimensões Largura: 118 cm Comprimento: 218 cm Altura: 25 cm Materiais Cama Montessoriana: Espuma D28 Colchão: Espuma D28 Tecido: 100% Poliéster Acabamento em Bouclé Persa ou Linho (conforme o lote de fabricação) Suporta até 120 kg Base com isolamento térmico A parte inferior da cama possui um acabamento antiderrapante, que também auxilia no controle da umidade e no isolamento do piso, reduzindo o contato direto com o frio. Em regiões muito frias ou com alta umidade, recomendamos utilizar um tapete sob a cama para proporcionar um isolamento térmico ainda maior. Também é importante manter o ambiente ventilado e realizar a limpeza periódica da parte inferior da cama. Sobre o tecido e a cor O acabamento pode variar entre Bouclé Persa e Linho, conforme o lote de fabricação de nossos fornecedores. Independentemente do tecido utilizado, a cor será sempre a anunciada, podendo ocorrer apenas leves variações de tonalidade entre diferentes lotes de fabricação.', 2749.0, 2199.9, NULL, 'Mom & Baby > Nursery > Cribs & Cradles & Beds', 'https://cf.shopee.com.br/file/br-11134207-820l7-mm8w9m49h3b8b8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1374188221%2F22194657871', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798166220', 'Capacete Moto San Marino Preto 58', 'O Capacete Moto San Marino Preto 58 é a escolha perfeita para motociclistas que buscam segurança de alto nível, conforto prolongado e um design elegante. Ideal para trajetos urbanos ou viagens mais longas, este capacete foi desenvolvido para oferecer o melhor desempenho em proteção, com um visual moderno e robusto. Seu acabamento na cor preto transmite sofisticação e discrição, tornando-o ideal para quem busca estilo sem abrir mão da segurança. Detalhe do produto: Visibilidade e Praticidade: O capacete San Marino 58 oferece um sistema de abertura de viseira prático, garantindo que você possa ajustar o visor de forma rápida e fácil durante a pilotagem. A viseira transparente proporciona proteção contravento, poeira e outros elementos externos, mantendo sua visão clara e segura. Alta Proteção: O San Marino 58 é projetado com materiais de alta resistência, proporcionando proteção eficiente contra impactos. Sua estrutura robusta foi feita para absorver choques, garantindo maior segurança ao motociclista em caso de imprevistos. Conforto e Estabilidade: O interior do capacete é acolchoado com materiais de alta qualidade, garantindo conforto durante o uso prolongado. Seu sistema de ajuste oferece um encaixe perfeito, tornando-o confortável e estável, ideal para diferentes tipos de pilotagem.', 349.9, 204.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7qvdr-lg58hnku2awl0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F23798166220', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993642933', 'Aparelho De Jantar E Chá Louça 20 Peças Lírios', 'O Aparelho de Jantar e Chá Louça 20 Peças Lírios é a escolha ideal para quem busca unir elegância, praticidade e qualidade na composição da mesa. Com um design delicado inspirado na beleza dos lírios, o conjunto valoriza desde refeições simples do dia a dia até ocasiões especiais, proporcionando uma apresentação sofisticada e acolhedora. Produzido em cerâmica de alta qualidade, oferece excelente resistência e durabilidade, além de um acabamento liso e brilhante que realça os detalhes florais com charme e requinte. Seu visual versátil combina facilmente com diferentes estilos de decoração, tornando cada refeição ainda mais especial. O conjunto foi pensado para atender até 4 pessoas com praticidade e organização, sendo uma opção completa para compor sua mesa com harmonia e funcionalidade. Além disso, sua estrutura facilita o uso no dia a dia, trazendo mais comodidade para sua rotina na cozinha. Outro grande diferencial é a facilidade de uso e limpeza. O aparelho pode ser levado ao micro-ondas e à lava-louças, otimizando o preparo e a higienização. Sua superfície lisa evita o acúmulo de resíduos, garantindo mais praticidade após as refeições. Para preservar a qualidade do produto, não é recomendado o uso em forno convencional. Principais destaques: • Conjunto completo com 20 peças• Design elegante com estampa floral de lírios• Acabamento liso e brilhante de alta qualidade• Pode ser utilizado no micro-ondas e lava-louças• Ideal para uso diário ou ocasiões especiais• Não recomendado para forno convencional Perfeito para quem valoriza beleza, funcionalidade e praticidade, o Aparelho de Jantar e Chá Lírios transforma sua mesa em um ambiente ainda mais sofisticado e convidativo.', 391.83, 254.9, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-7ra0x-m51r3khnx9aw25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F22993642933', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18199330672', 'Cartão de Memória Sandisk 256gb Extreme Pro Cartão Sd 200Mbs', 'Cartão de Memória Sdxc 256gb Cartão Sd Extreme Pro 200Mbs + Case Classificação de Velocidade de Vídeo V30 Classe c10 Uhs-I U3 4k Ultra Hd - No Brasil Capacidade de armazenamento significativa: Com 256GB de espaço, o cartão SD Extreme Pro oferece uma grande quantidade de espaço para armazenar fotos, vídeos e outros arquivos digitais, tornando-o uma excelente opção para fotógrafos profissionais e videomakers.Velocidades de transferência ultrarrápidas: Com velocidades de leitura de até 200MB/s, este cartão SD facilita a transferência rápida de arquivos de alta resolução, proporcionando uma eficiência excepcional no seu fluxo de trabalho.Classificações de velocidade V30 e C10: As classificações V30 e C10 garantem que o cartão possa suportar a gravação de vídeos em alta resolução, incluindo 4K UHD, o que é essencial para fotógrafos e cinegrafistas.Ideal para dispositivos de alta resolução: Dada a sua alta capacidade e velocidade, este cartão SD é ideal para uso em câmeras digitais de alta resolução, DSLRs e filmadoras que necessitam de armazenamento de alto desempenho para capturar e armazenar imagens e vídeos de alta qualidade.Versatilidade de uso: Este cartão SD é compatível com uma ampla gama de dispositivos que possuem um slot para cartão SD, como câmeras digitais, DSLRs, filmadoras e computadores. Isso oferece flexibilidade para várias necessidades de armazenamento e uso. Garantia 90 dias', 1264.79, 1264.79, NULL, 'Mobile & Gadgets > Accessories > Memory Cards', 'https://cf.shopee.com.br/file/br-11134201-7r98o-maehq8jpo1yx68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163364765%2F18199330672', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497156746', 'Solda Inversora 135A TW140ICM-MMA Painel Digital TEKNA 220V', 'Máquina de Solda Inversora 135A TW140ICM-MMA Painel Digital 220V TEKNA Máquina de Solda Inversora com display digital e ótimo desempenho nos processos de soldagem. Dados Técnicos: Tensão: 220V Frequência: 60Hz Capacidade: 6,2kVA Corrente de entrada: 20A Tensão em vazio: 60V Tensão de trabalho: 25,4V Faixa de corrente: 10 - 135A Ciclo de trabalho: 60% Eficiência: 85% Fator de potência: 0,8 Classe de isolação: F Classe de proteção: IP21S Tipo de refrigeração: Forçada (Ventoinha) Tipo de solda: Eletrodo Funcionalidades: Hot start - Arc Force - Anti Stick Diâmetro (ø) recomendado do Eletrodo: ø1,6 - ø 3,25mm Peso Líquido: 4kg Peso Bruto: 4,4kg Dimensões Caixa (CxLxA): 290x230x210mm Conteúdo da embalagem: 1 Máquina de Solda Inversora Acompanha garra e porta eletrodo Marca: TEKNA Ref: TW140ICM-MMA Garantia: 06 Meses * Imagens Meramente Ilustrativas.', 370.04, 322.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbl8-lofowt9lwm9tb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F22497156746', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14265257426', 'Kit 6 Unidades Faixa Decorativa Infantil Carrinhos', 'Faixa Decorativa Infantil Carrinhos A Faixa Decorativa é uma tendência que mostra a cada dia que veio para ficar. Fácil de fazer, ela cria uma composição diferenciada nos mais diversos tipos de ambientes, criando um destaque todo especial a um cantinho específico na decoração. Além da beleza estética, a faixa decorativa é uma alternativa criativa e de baixo custo para transformar um ambiente comum em um lugar de destaque. Características Técnicas da Faixa Decorativa: Tamanho:1,20 x 0,15 cm O produto é vendido em kit de 6 unidades Material: 100% PVC Vinílico Fosco Auto Colante Textura: Vinílica Fosca (Sem Relevo) Cola: Não Necessita. Observações: Onde pode ser aplicado? Em qualquer ambiente, seja ele interno ou externo, desde que observado os seguintes requisitos: ► A superfície deve ser totalmente lisa (sem textura ou relevo); ► Não pode haver sedimentos como poeira ou pó de qualquer natureza; ► A superfície não pode ser porosa; ► A superfície deve estar preparada com látex ou seladora após aplicação da massa corrida; ► Não pode ser aplicada diretamente sobre parede com massa corrida, precisa de ao menos uma mão de tinta; ► Pode ser aplicado em locais úmidos como banheiro e cozinha, pois o papel suporta água devido à sua textura vinílica, porém, no ato da aplicação, o local deve estar seco; Importante: ► Compre a quantidade correta, pois não há possibilidade de produzir as faixas com as mesmas cores em lotes diferentes devido a vários fatores. ► As cores podem sofrer variação, pois cada monitor ou dispositivo móbile tem uma configuração e qualidade diferente, sendo assim, se houver dúvidas entre em contato com nosso atendimento antes de realizar a compra.', 77.5, 77.5, NULL, 'Home & Living > Party Supplies > Backdrops & Banners', 'https://cf.shopee.com.br/file/437b779626bed2bb3e10a0c021a0861e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303439692%2F14265257426', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297176027', 'Parafusadeira à Bateria 4.8V com Kit 11 Peças HO031 Bivolt MULTILASER Bivolt', 'Parafusadeira à Bateria 4,8V com Kit 11 Peças HO031 Bivolt MULTILASER Parafusadeira Elétrica Multilaser, desenvolvida para você que precisa fazer pequenos reparos e ajustes em sua casa ou como trabalho. Carregamento de 3-5 horas e indicador de bateria para nunca se preocupar, possui dois sentidos de giro, aperte ou desaperte os parafusos com um toque no botão de reversão. Use confortavelmente sua parafusadeira, pois ela te oferece um design compacto e pratico, a luz de LED te auxilia para uso em lugares escuros. DADOS TÉCNICOS: Ferramenta Voltada para o Uso Doméstico Mandril Sem Chave 1/4 Polegada (6,35 mm) Gatilho Eletrônico com Rotação nos 2 Sentidos Tensão Nominal: 4,8V Velocidade sem Carga: 180 RPM Torque Máximo: 3,5 N.M Possui Luz de LED Próximo ao Mandril para Facilitar a Visibilidade Bateria: 12V Tensão de Operação: Bivolt Possui Indicador de Nível de Bateria Tempo de Recarga: 3 a 5 Horas Punho Compacto para Maior Conforto e Controle Excelente Durabilidade e Resistência Acompanha 11 Bits e 1 Prolongador: - 3 Pontas Fendas 25 mm - 4,5 e 6 - 3 Pontas Phillips 25 mm- PH1, PH2 e PH3 - 3 Pontas Pozidriv 25 mm – PZ1,PZ2 e PZ3 - 2 Pontas Allen 25 mm – H2 e H3 - 1 Prolongador Bits Dimensões Aproximadas Parafusadeira (LxAxC): 4x12x15cm Conteúdo da Embalagem: 01 Parafusadeira Sem Fio 01 Carregador Bivolt 11 Bits de 25mm 01 Prolongador para Bits 01 Adaptador para Soquete Manual de Instruções Código de Fábrica: HO031 Marca: Multilaser Garantia: 3 meses * Imagens meramente ilustrativas.', 99.9, 47.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbkf-lp9f8mwe631v4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%