INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259356791', 'Roupeiro Nanda 2 Portas de Correr Jequitiba/Areia', 'Roupeiro Nanda 2 Portas de Correr com pés Jequitiba/Areia - Santos Andirá O Roupeiro Nanda da Santos Andirá é ideal para quartos que precisam otimizar espaço. Seu design inteligente organiza bem o interior, com gavetas de corrediças telescópicas para um deslizamento suave e portas de correr com puxadores de MDF duráveis. É perfeito para melhorar a decoração do quarto e atender suas necessidades de armazenamento. Fabricado em MDP, é espaçoso e resistente, tem o melhor custo benefício para você que procura um roupeiro completo. Veja mais características do Roupeiro Nanda 2 Portas de Correr - Santos Andirá: - Material: MDP. - 2 Portas. - 2 Gavetas. - 3 Prateleiras em MDP. - Puxadores em ABS. - Dobradiças tipo Metálicas. - Escala de Brilho: Verniz Brilhante. - Garantia: 3 meses. - Cor:Jequitiba/Areia. - Dimensões do Produto: (LxAxP) 106 x 191 x 46cm.', 799.0, 639.0, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-820lu-mndc4fookhzc01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1473114980%2F58259356791', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094293856', '🏍️ Escapamento Fazer 150 Factor 125/ Factor 150 Mini Turbo Fortuna Som Grave Esportivo', '🏍️ HB Moto Peças e Acessórios Loja online oficial dos produtos Fortuna Escapamentos 🔧 Qualidade garantida com o melhor preço do mercado! ⚠️ ATENÇÃO – COMPATIBILIDADE Este escapamento é compatível apenas com: ✔️ Yamaha Fazer 150cc – Anos: 2014 a 2025 ✔️ Yamaha Factor 150cc – Anos: 2015 a 2024 ✔️ Yamaha Factor 125cc – Anos: 2016 a 2024 ✅ Pronto para instalação ✅ Encaixa perfeitamente no sistema original ❌ Não precisa de adaptações 🎨 Opções de Cor • Preto com curva preta • Preto com curva cromada • Cromado com curva cromada • Cromado com curva preta 📝 Informe a cor desejada após a compra. 📦 Especificações do Produto • Marca: Fortuna • Modelo: Mini Turbo – Som grave e ganho de desempenho • Material: Aço carbono • Linha: Honda • Condição: Novo • 📄 Com selo do INMETRO – Nº 005343/2020 ✅ Vantagens Exclusivas 🔹 Produto de alta qualidade e ótimo custo-benefício 🔹 Compra 100% segura e garantida pela Shopee 🔹 Produto disponível para envio imediato 🔹 Atendimento antes e depois da compra 🔹 Nota fiscal digital (PDF) 🏁 Sobre a Fortuna Escapamentos A Fortuna é referência nacional no segmento de escapamentos e acessórios para motos. 🚀 Produtos modernos, com tecnologia e segurança 🔩 Desenvolvidos com matéria-prima de primeira linha e componentes importados 📞 Ficou com dúvidas? Fale conosco! A HB Moto Peças e Acessórios está pronta para te oferecer o melhor atendimento. Garanta já o seu escapamento e dê mais potência e estilo à sua moto!', 309.97, 294.48, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/sg-11134201-7rdvz-md264c5ydmws0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fpro