INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209755276', 'Pneu 185/35R17 74V P10 Blackarrow', 'O Pneu 185/35R17 74V P10 Blackarrow é voltado para projetos automotivos e veículos compactos com aro grande, entregando visual agressivo e dirigibilidade extremamente firme. Com perfil 35 (ultra baixo), ele coloca o carro praticamente “no chão”, oferecendo resposta imediata ao volante e alta precisão em curvas. Aqui não tem meio-termo: é estética + controle direto. A largura 185 mm combinada com esse perfil reduzido cria um conjunto focado em controle e estabilidade, principalmente em uso urbano e rodoviário leve. O desenho da banda de rodagem favorece aderência em piso seco e molhado, com sulcos que ajudam na drenagem de água e mantêm estabilidade dentro da proposta. O índice de carga 74 (375 kg por pneu) atende carros compactos, enquanto o índice de velocidade V (até 240 km/h) garante segurança em rodovia. Especificações Técnicas Marca: Blackarrow Modelo: P10 Medida: 185/35R17 Aro: 17 Índice de carga: 74 (375 kg por pneu) Índice de velocidade: V (até 240 km/h) Construção: Radial Tipo: Sem câmara (Tubeless) Classificação: Performance / Perfil Ultra Baixo Aplicação: Uso urbano e rodoviário Indicação: Veículos compactos e projetos automotivos', 323.03, 323.03, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-820lw-mnlf0i0frb40f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1173721007%2F58209755276', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
