INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597138722', 'Bucha Garfo Embreagem Uno 1991 A 1995 Elba Fiorino Premio', 'Este anúncio contém: 01 (Uma) Bucha do garfo de embreagem com anel de borracha. Características: Produto novo; Excelente qualidade e durabilidade; Encaixe perfeito; Pronto para instalação; Fabricado conforme as especificações originais do veículo. Aplicável nos seguintes veículos: Montadora: Fiat; Modelo: Elba 1.3 e 1.5 (Motor Fiasa); Anos: 1988, 1989, 1990, 1991, 1992, 1993, 1994, 1995, 1996. Modelo: Fiorino 1.3 e 1.5 (Motor Fiasa); Anos: 1988, 1989, 1990, 1991, 1992, 1993, 1994, 1995, 1996. Modelo: Uno Mille 1.0 (Motor Fiasa); Anos: 1991, 1992, 1993, 1994, 1995. Modelo: Prêmio 1.3 e 1.5 (Motor Fiasa); Anos: 1985, 1986, 1987, 1988, 1989, 1990, 1991, 1992, 1993, 1994. Importante: Preço unitário; Garantia 3 meses; Alta durabilidade; Qualidade original; Produto com nota fiscal. Antes de realizar a compra, verifique a compatibilidade do produto com o modelo, ano e motorização do seu veículo. Em caso de dúvidas, utilize o campo de perguntas. Nossa equipe terá prazer em ajudar na confirmação da aplicação correta do produto. Quem somos? Loja de Auto Peças e Acessórios para veículos nacionais e importados, há 35 anos atendendo o mercado de reposição. Temos em estoque uma enorme variedade de produtos para motor, câmbio, suspensão, freios e diversos acessórios para seu carro. Trabalhamos com marcas originais e paralelas, oferecendo produtos de qualidade, procedência garantida e preços que cabem no seu bolso.', 23.75, 23.52, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-7rbk4-lnxlnq4phcpy52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1037769766%2F23597138722', NULL, NULL, '2026-07-28T