INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21099247171', 'Conjunto com 2 Espreguiçadeiras com Encosto Reclinável Branco', 'Aproveite o verão e os dias quentes com a Espreguiçadeira Espresso Móveis e desfrute de momentos de lazer com conforto e tranquilidade. Com um design moderno e anatômico, essa peça proporciona um abraço completo ao seu corpo, garantindo o máximo de aconchego. Feita em polipropileno de alta qualidade, essa espreguiçadeira é resistente e durável, perfeita para enfrentar as mudanças climáticas. Além disso, ela conta com proteção UV, garantindo a sua durabilidade e evitando danos causados pela exposição ao sol. Com quatro regulagens de inclinação, você pode escolher ficar levemente inclinado ou completamente deitado, enquanto os quatro pés oferecem uma excelente sustentação. A espreguiçadeira Espresso Móveis é fácil de limpar e totalmente reciclável, tornando-a uma escolha sustentável e consciente. Adquira a sua e torne os seus momentos de descanso e lazer ainda mais agradáveis. Peso (kg): 12 Garantia: 12 Meses Altura (cm): 81 Largura (cm): 75 Comprimento (cm): 173 Suporta Até (kg): 120 Altura do Assento: 29 Origem do Produto: Nacional Ambiente Principal: Jardim e Varanda Encosto Reclinável: Sim Material Principal: Polipropileno Necessita Montagem: Não Resistência ao Sol: Sim Resistência à Chuva: Sim Material da Estrutura: Polipropileno Marca: Espresso Móveis Cor do Produto: Branco Itens Inclusos: 2 Espreguiçadeiras Cor Predominante: Branco', 1143.56, 1143.56, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-824gg-mpjyp117lz4ef5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F21099247171', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6179633050', 'Base para Notebook LED X-Cooler AC123 - Multilaser', 'O suporte para Notebook da Multilaser com Cooler é perfeito para manter a temperatura e ajustar a altura perfeita para você! Ele conta com Superfície de Metal, Luz de LED indicadora de funcionamento e sua altura é ajustável! Características: - Marca: Multilaser - Modelo: AC123 Especificações: - 2 Portas USB 2.0 - Botão ON/OFF - Dimensão do Cooler: 120 x 120 x 25mm - Velocidade do Cooler: 750 ~ 1500RPM - Nível de Ruído: 11DBA - Corrente: 0,4A - Voltagem: 5V DC - Fluxo de Ar: 23 ~ 44CFM - Composição do Material: Plástico ABS / Metal Dimensões e Peso: - Dimensões: 7 x 42 x 32cm - Peso: 300g Conteúdo da Embalagem: - Suporte para Notebook X-Cooler - AC123', 139.91, 125.92, NULL, 'Computers & Accessories > Peripherals & Accessories > Laptop Stands & Foldable Laptop Desks', 'https://cf.shopee.com.br/file/262964247e21e98f30b572196f37b857', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F6179633050', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209458606', 'Perdigão Lasanha à Bolonhesa', 'A Lasanha à Bolonhesa da Perdigão é a escolha perfeita para uma refeição rápida e saborosa, ideal para aqueles dias em que você não quer perder tempo na cozinha. * Modo de Preparo: * Micro-ondas: Leve o produto congelado ao forno micro-ondas por 11 minutos em potência máxima (100%). * Forno convencional: Leve o produto congelado ao forno convencional por 55 minutos a uma temperatura de 200°C . * Forno elétrico: Leve o produto congelado ao forno elétrico por 50 minutos a uma temperatura de 210°C. Ingredientes: Molho bechamel (água, leite em pó integral, amido modificado (1,95%), margarina**, sal, farinha de arroz, noz-moscada, alho, aipo, carne de frango desidratada, aromatizante: aroma idêntico ao natural de frango, realçador de sabor: glutamato monossódico, corante: cúrcuma), molho bolonhesa (molho de tomate, água, carne bovina, cebola, amido modificado (1%), óleo de soja**, sal, açúcar, alho, presunto cozido, cenoura, cebolinha, salsa, manjericão, louro, pimenta-branca, aromatizante: aroma natural de carne bovina, realçador de sabor: glutamato monossódico), farinha de trigo enriquecida com ferro e ácido fólico, água (4,43%), queijo mussarela, presunto cozido, clara de ovo e ovo.', 17.99, 17.99, NULL, 'Food & Beverages > Fresh & Frozen Food > Others', 'https://cf.shopee.com.br/file/sg-11134201-825aq-mqnektizkm4jeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555142%2F58209458606', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
