INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397117810', 'Kit 2 Creme Dental para Sensibilidade Elmex Sensitive Professional 110g', 'CREME DENTAL ELMEX SENSITIVE Tecnologia Pro-Argin + CalSeal. Eficaz para dentes sensíveis. Alívio imediato. Proteção prolongada. Se a gengiva está retraída, a raiz dos dentes fica exposta e vulnerável. Estímulos como o frio, calor, ácido ou toque podem causar desconforto. A cárie na dentina pode desenvolver mais rápido. Tecnologia Pro-Argin + CalSeal: Fórmula exclusiva para proteção diária dos dentes sensíveis, proporcionando alívio imediato. Sela os canais que conectam com o centro do dente, imediatamente bloqueando a sensibilidade. Além disso, cria uma barreira ao redor dos túbulos dentinários expostos, protegendo contra a sensibilidade, enquanto o flúor protege contra a cárie, pis ajuda a remineralizar o esmalte enfraquecido. Modo de usar: Adultos e crianças maiores de 12 anos: colocar em uma escova macia e certificar de escovar todas as áreas sensíveis dos dentes. Escovar 3 vezes ao dia ou conforme orientação do dentista.', 73.78, 73.78, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-823qk-momtkd8rv0nfdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F20397117810', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
