INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259234785', 'Torneira Para Cozinha Gourmet Misturador Monocomando Piranga Pingoo - Prata', 'O Misturador Monocomando Piranga é perfeito especialmente para você que mora em regiões onde o inverno é mais rigoroso e lavar a louça com água quente, se torna uma necessidade para compor o conforto do seu lar.Sem contar na praticidade para lavar louças engorduradas, pois a água quente ajuda a eliminar a gordura com mais facilidade e rapidez. Isso garante a economia de água, detergente e tempo. Além do seu design slim e moderno, a Linha Piranga oferece também atributos técnicos indispensáveis para a sua utilização.O cartucho monocomando permite a precisa regulagem da vazão e da temperatura da água, feita em apenas um comando. Ela garante funcionamento perfeito em baixa e alta pressão. Já o arejador, além de garantir economia de água, evita respingos e proporciona conforto para as mãos.E mais, ela conta com um super acabamento cromado triplo de alta resistência à corrosão, conservando a sua beleza e características originais por muito mais tempo. Especificações: Itens inclusos:', 589.9, 503.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-81ztr-mn63a1p8k9a9e8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1758065666%2F58259234785', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
