INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42022618848', '[OFFICIAL] SEOUL 1988 Sun Pine Tree + Ceramide 15ml/50ml', 'SEOUL 1988 Sun Pine Tree + Ceramide 15ml / 50ml ✈️ Envio direto da Coreia ✨ Protetor Solar Hidratante com Pine Tree & Ceramide Proteção UV + cuidado calmante + suporte para barreira da pele Um protetor solar leve formulado com extrato de pinheiro e ceramida para ajudar a proteger a pele contra os raios UV enquanto mantém a pele hidratada e confortável. Perfeito para pele sensível e cuidados solares diários. 💛 POR QUE VOCÊ VAI AMAR Cuidado Calmante com Pine Tree Ajuda a acalmar e refrescar a pele Suporte para Barreira da Pele com Ceramida Ajuda a manter a barreira da pele saudável e hidratada Textura Leve e Confortável Protetor solar fresco para uso diário sem pesar Proteção UV Diária Ajuda a proteger a pele da exposição solar 📦 OPÇÕES • 15ml (mini) • 50ml 🌸 BENEFÍCIOS PARA A PELE ✔ Proteção UV ✔ Cuidado da barreira da pele ✔ Hidratação calmante ✔ Hidratação confortável ✔ Proteção solar diária 👩‍⚕️ RECOMENDADO PARA ✔ Pele sensível ✔ Pele seca ✔ Usuários diários de protetor solar ✔ Quem prefere protetores leves 🫧 COMO USAR Aplique uniformemente como último passo do skincare antes da exposição ao sol. 📦 INFORMAÇÕES DO PRODUTO Produto: SEOUL 1988 Sun Pine Tree + Ceramide Opções: 15ml / 50ml', 221.63, 79.0, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134207-822x6-mo7u56npi6tk2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F457864097%2F42022618848', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
