INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44462854017', 'Alto Falante Médio-Grave Unlike UNF66 6″ 200W RMS 4 Ohms Cone Celulose Bobina Kapton Potente', 'Alto Falante Medio Grave Unlike UNF66 6 Polegadas 200W RMS 4 Ohms Woofer Automotivo Cone Celulose Bobina Kapton Alta Eficiencia Sensibilidade Instalacao Portas Paineis Som Definido O Alto-Falante Médio-Grave Unlike UNF66 foi desenvolvido para oferecer potencia, definição e durabilidade para sistemas de som automotivo de alta performance. Com 200W RMS de potencia e impedância de 4 Ohms, entrega médios fortes e presença marcante, ideal para uso em portas, painéis ou como complemento de subwoofers. Especificações Técnicas - Modelo: UNF66 - Tipo: Medio-Grave Automotivo - Tamanho: 6" - Potencia RMS: 200W - Potencia Máxima: 400W PMPO - Impedância: 4 Ohms - Sensibilidade: aprox. 97 dB - Frequência de resposta: 120 Hz a 9 kHz - Cone: Celulose prensada - Borda: Tecido impregnado - Bobina: Kapton 38,70 mm (simples) - Carcaca: Chapa de aco reforcada Benefícios do Produto - Construção robusta para maior durabilidade e resistência - Excelente custo-benefício para projetos de som automotivo - Compatibilidade com sistemas de trio, portas e painéis Conteúdo da Embalagem - 1 alto-falante Unlike UNF66 200W RMS 4 Ohms Por que comprar com a LSA - Loja do Som e Acessórios - Especialistas em som automotivo, com experiência e conhecimento técnico - Produtos originais e de procedência garantida - Envio rápido e seguro com rastreamento pelos marketplaces - Atendimento especializado via chat das plataformas - Pós venda ativo para garantir sua satisfação - Amplo catalogo de alto-falantes, módulos, players e acessórios', 189.9, 189.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-7rdyg-mdem3