INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50803346915', 'Rack Retrô para TV até 70 polegadas, Pés em Madeira Maciça Shop 2,20m – Moderno e de Alta Qualidade', 'Descrição: teste 1 O Rack Shop 2180mm é um produto retrô, devido o design dos seus pés em madeira maciça incorporando-o e deixando- o mais nobre e ao mesmo tempo moderno e inovador. Possui três portas em MDF, duas de rotação e uma central basculante, as três possuem uma usinagem para servir de pega para puxador. Sua estrutura é em MDP e MDF de 15 mm. É um produto onde você personaliza seu ambiente deixando-o exclusivo, agradável e aconchegante. Características: - Acabamento: Pintura UV - Escala de Brilho: Acetinado - Formato do móvel: Rack - Garantia: 3 Meses - Inclui manual de montagem: Sim - Material: MDP - Material da Estrutura: Mdp e mdf - Medida do Produto Montado (LXCXA): 38,8cmX218cmX51,2cm - Peso do Produto Montado: 305 - Peso Máximo Suportado: 40 - Produto Necessita de Montagem?: Sim - Quantidade de Pés: 6 - Quantidade de Portas: 3 - Recomendações de manutenção: Pano úmido. Não aplicar lustra móveis. - Tamanho Máximo da Tv: Até 70 Polegadas - Tipo de Pés: Pinus - Tipo de Porta: 2 Rotativas e 1 Basculante - Volumes: 1 - Formato do Móvel: Rack - Tamanho: Médio - Quantidade de Portas: 3 Dimensões: - Altura: 8,30 cm - Largura: 39,50 cm - Profundidade: 226,00 cm - Peso: 30,500 kg Informações importantes sobre a entrega: Não realizamos entregas em locais com acesso por estrada de terra, areia, balsa ou barco. Entrega até o local permitido pela transportadora. Não está inclusa a subida por escadas ou elevadores.', 829.99, 480.99, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/br-11134207-820m6-mq844ynmmxaa43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408578430%2F50803346915', NULL, NU