INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48850961174', 'Uma Questão de Honra | Luciano Subirá', 'O Valor do Dinheiro na Adoração Descubra o Caminho Bíblico para a Verdadeira Prosperidade Financeira. Em "Uma Questão de Honra", Luciano Subirá vai além do conceito tradicional de dízimos e ofertas para revelar que honrar a Deus é um princípio que transforma toda a sua vida. Este livro essencial desvenda os fundamentos espirituais da generosidade, explorando temas cruciais como a Lei das Primícias, a integridade nas finanças, o contentamento e a mordomia fiel. Você aprenderá que a contribuição material é apenas uma expressão de um coração que prioriza Deus em todas as áreas. Mais do que um ensino sobre dinheiro, esta é uma obra transformadora que: Liberta você da escravidão financeira, tornando o dinheiro um servo e não um senhor. Reorganiza suas motivações e prioridades de acordo com a Palavra de Deus. Abre as portas para um relacionamento mais íntimo com Deus e para as bênçãos prometidas aos que O honram. Ideal para quem busca respostas biblicamente fundamentadas para administrar os recursos e experimentar a provisão divina. Transforme sua vida financeira e espiritual começando pelo coração. Especificações Título: Uma Questão de Honra | Luciano Subirá Subtítulo: O Valor do Dinheiro na Adoração Autor(es): Luciano Subirá Ano de edição: 2025 Capa: Brochura Acabamento: Laminação Fosca com Verniz Localizado Miolo: Pólen Páginas: 208 ISBN: 9786559884933 Editora: Mundo Cristão Família: Livros', 33.18, 33.18, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821dt-mgqndz7hzpcc24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F48850961174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43200782874', 'Livro A Família do Pastor | Brian e Cara Croft', 'A Família do Pastor Pastoreando sua família em meio aos desafios do ministério pastoral Como amar e servir a família e a igreja juntos! No livro A Família do Pastor , Brian e Cara Croft trazem a perspectiva de um pastor e de sua esposa sobre o ministério pastoral e identificam os fardos pesados e as expectativas que esse trabalho traz para a vida familiar. Os autores falam dos desafios específicos que os pastores enfrentam como maridos e pais, e discutem as dificuldades e alegrias de ser esposa e filho de pastor, oferecendo conselhos práticos sobre como criar os filhos, destacando as alegrias de servir juntos como família bem como as oportunidades de discipulado e liderança nesse âmbito familiar. Com questões para discussão, este livro é ideal para pastores e seus cônjuges, seminaristas e suas esposas. Título: A Família do Pastor Autor: Brian e Cara Croft Capa: Brochura Páginas: 248 Formato: 14 x 21 x1 cm Peso: 280 g ISBN: 9786557230619 Editora: Fiel', 50.42, 50.42, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9kr2hdjzdq14a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F43200782874', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40600624943', 'Transpondo Muralhas | Eugene H. Peterson', 'Transpondo Muralhas Espiritualidade para o dia-a-dia dos cristãos Nesta inspiradora obra, o professor Eugene H. Peterson usa magistralmente as melhores histórias da vida épica de Davi para nos brindar com vívidas e sábias lições para o dia-a-dia da nossafé e da nossa espiritualidade. Explorando a fundo as experiências de amizade, tristeza, amor, pecado e sofrimento da vida de Davi, bem como as santidade, beleza e solidão. O professor peterson nos leva a uma redescoberta das verdades eternas que se encontram por trás das ricas e emocionantes narrativas da existência de Davi. Título: Transpondo Marulhas Subtitulo: Espiritualidade para o dia-a-dia dos cristãos Autor: Eugene H. Peterson Páginas: 287 Formato: 23 x 16 x 1 cm Peso: 470g ISBN: 9788589829021 Editora: Habacuc', 63.81, 63.81, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9ksovibornm2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F40600624943', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9668126564', 'Meião Futebol Adulto Matis VIII Penalty Azul Marinho', 'Desenvolvido para compor o fardamento do seu time de futebol, o meião modelo Matís VIII da Penalty traz uma estrutura que garante segurança e liberdade aos movimentos. Fabricado com poliéster, elastano, poliamida e elastodieno, proporciona leveza e tecido que evita a formação de pilling (bolinhas). Além disso, seu design é composto predominantemente pela cor preta com branco visto em detalhes na lateral como o logo da marca fornecedora. Por fim, seu material também é um isolante térmico para o atleta e conta com faixa tensora nos tornozelos para maior proteção e pé totalmente atoalhado garantindo total conforto. Contém: 1 Par Tamanho Único: 39 - 44 Composição: 73,5% Poliéster, 13,5% Elastano, 7,0% Poliamida e 6,0% Elastodieno', 28.0, 28.0, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Others', 'https://cf.shopee.com.br/file/e6cee215b192cee390b583aba3ed9366', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F9668126564', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
