INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23992987809', 'Produto para Proteger o Chassi do Carro Inibidor de Ferrugem 1,5L Vintex', 'PULVIFLEX 1,5L - PROTETOR DE CHASSIS DESCRIÇÃO: O protetor de chassis Pulviflex, é um produto que foi especialmente desenvolvido para proteger chassis de veículos em geral, tais como chassis de: Carros, ônibus, tratores, máquinas agrícolas, caminhões etc. Sua exclusiva fórmula contém inibidores de corrosão especiais que protegem a superfície por muito mais tempo, deixando uma fina camada de proteção e brilho. - Inibe corrosão - Não gotejante - Ecologicamente correto MODO DE USO: 1. Pulverize uma fina camada do produto em toda superfície a ser tratada e aguarde de 15 a 30 minutos ou até que se forme um filme transparente', 43.99, 43.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lup84dleqmhs00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F23992987809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
