INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3782647955', 'Aparelho De Som Mp3 Volks Up! Novo Bluetooth Pendrive Rádio', 'O MP3 Player é um produto antenado com as novas tecnologias, pois além de ter um display, ele reproduz áudio MP3 / WMA, Além de todas essas características, ele ainda conta com entradas USB e para cartões de memória, permitindo que arquivos de dispositivos de armazenamento sejam reproduzidos. Ele possui função Bluetooth, memória para estações de rádio FM. O MP3 Player também possui funções como relógio, mudo (sem som), entrada auxiliar e controle de graves e agudos. Ele acompanha um controle remoto, para dar ainda mais autonomia aos passageiros durante passeios e viagens. --------------------------------------------------------------------------------------- MP3 Player Automotivo Rádio FM USB SD Entrada Auxiliar BLUETOOTH. Tela Led Painel Frontal 4 saídas de autofalante Função de relógio real Sintonização de rádio eletrônica Suporte para USB/ SD/ abertura para cartão MMc Compatível com formato de música MP3 Com Bluetooth', 84.03, 72.03, NULL, 'Audio > Media Players > MP3 & MP4 Players', 'https://cf.shopee.com.br/file/2ae299830f324b41c155c508e614972d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F3782647955', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
