INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18697981584', 'H''maston YD-68 Carregador De Indução Magnético Para Apple Watch Carregamento Rápido', '1. Sucção Magnética Forte:Carregador Magnético de Rápido possui um módulo magnético embutido, o relógio está próximo à sucção magnética automática e o design magnético forte é estável e não cai. 2. Entrada de Interface Dupla:Carregador Magnético de Rápido possui entrada de interface dupla, Tipo-c e Lightning duas interfaces podem ser inseridas, não vinculadas pelo cabo de carregamento, você pode escolher livremente. 3. Carregamento Rápido: Carregador Magnético de Rápido pode ser carregado a uma velocidade de carregamento de até 2,5 W e pode ser totalmente carregado em 2-3 horas. 4. Rápida Dissipação de Calor: Carregador Magnético de Rápido é revestido com material de liga de zinco, que possui rápida velocidade de dissipação de calor e alta eficiência, e cuida da saúde da bateria de maneira geral. 5. Carregamento Seguro: Carregador Magnético de Rápido possui um chip inteligente integrado, que pode detectar atividades de carregamento e fornecer proteção contra sobretensão, proteção contra sobrecorrente, proteção contra temperatura e outras funções. 6. Leve e Portátil: Carregador Magnético de Rápido é pequeno e requintado, com cordão próprio, fácil de transportar e sem medo de se perder. 7. Para iWatch: O carregador é adequado para a série S1-S9 do iWatch.', 120.0, 68.99, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2aemf2j4pqed8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1155571749%2F18697981584', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892752873', 'Pulverizador Guarany Modelo Pet', 'Escada de alumínio para uso doméstico. Leve e prático, é indispensável no dia a dia. Dobra-se até 10 cm e é muito fácil de guardar. Seu piso em polipropileno de alta resistência proporciona segurança para o trabalho diário.', 124.87, 99.9, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-81zuz-mn79getbgdmo13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F23892752873', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097729807', 'Banho De Creme Bio Extratus Camomila 1Kg', 'O Banho De Creme Bio Extratus Camomila 1Kg foi especialmente desenvolvido para hidratar, nutrir e iluminar os cabelos claros. Perfeito para o uso semanal, sua fórmula rica em ativos naturais proporciona uma hidratação intensa, deixando os cabelos macios, brilhantes e revitalizados. Indicado especialmente para cabelos loiros ou com luzes, ajuda a intensificar o tom claro dos fios. pH 4,5. Benefícios: - Hidratação intensa; - Nutrição profunda; - Realça cabelos claros; - Protege contra ressecamento; - pH 4,5. Modo de usar: Aplique nos cabelos úmidos após lavar com shampoo, distribuindo ao longo dos fios, principalmente nas regiões mais danificadas. Massageie suavemente e deixe agir por alguns minutos. Enxágue bem. Para melhores resultados, utilize uma touca térmica durante a aplicação. Sobre a marca: A marca Bio Extratus foi idealizada por cabeleireiros amantes da natureza. A história da empresa teve início em 1989, em um salão de beleza em Belo Horizonte, quando os proprietários buscavam uma linha de cosméticos diferenciada, com qualidade e preço acessível. Aliando conhecimento e experiência, os antigos proprietários do salão, que são os atuais proprietários da Bio Extratus, iniciaram uma produção artesanal de cosméticos ricos em ativos naturais. Em 1991, na cidade de Dom Silvério, MG, nasceu a marca Extratus Produtos Naturais, pioneira na utilização do óleo de tutano em cosméticos capilares.', 117.32, 117.32, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-825ap-mqxb4g4cxlondb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F21097729807', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
