INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251806389', 'Lampada Automotiva Mod H4 60/55w Original Philips 12v 12342', 'LÂMPADA H4 PHILIPS PREMIUM STANDARD 4300K 12V 60/55W COM VIDRO DE QUARTZO E PROTEÇÃO UV. ILUMINAÇÃO SUPERIOR, MAIOR SEGURANÇA E CERTIFICAÇÃO INMETRO. PRODUTO NOVO, ORIGINAL E DE ALTA DURABILIDADE PARA CARROS E MOTOS. DESCRIÇÃO LÂMPADA PHILIPS PREMIUM STANDARD H4, DESENVOLVIDA PARA OFERECER MAIOR ILUMINAÇÃO, SEGURANÇA EM CONDUÇÃO NOTURNA E DURABILIDADE SUPERIOR. PRODUZIDA COM VIDRO DE QUARTZO, TEM MAIOR RESISTÊNCIA A CHOQUES TÉRMICOS E PROTEÇÃO UV, PROPORCIONANDO FAIXA DE LUZ MAIS EFICIENTE E TEMPERATURA DE COR DE 4300K. PRODUTO LÂMPADA HALÓGENA H4 PHILIPS PREMIUM STANDARD CÓDIGO H4 4300K POSIÇÃO FAROL – ALTA E BAIXA (H4) TIPO LÂMPADA HALÓGENA AUTOMOTIVA 12V 60/55W MARCA PHILIPS COMPOSIÇÃO TÉCNICA TEMPERATURA DE COR: 4300K VIDRO DE QUARTZO BASE METÁLICA PROTEÇÃO UV ENCAIXE H4 TENSÃO: 12V POTÊNCIA: 60/55W CERTIFICAÇÃO INMETRO ALTA DURABILIDADE ILUMINAÇÃO SUPERIOR EM RELAÇÃO À LÂMPADA COMUM ITENS INCLUSOS 01 LÂMPADA PHILIPS H4 4300K BENEFÍCIOS MAIOR ILUMINAÇÃO MELHOR VISIBILIDADE EM CONDIÇÕES NOTURNAS VIDRO DE QUARTZO RESISTENTE PROTEÇÃO CONTRA RAIOS UV QUALIDADE PHILIPS MAIOR SEGURANÇA AO DIRIGIR LONGA VIDA ÚTIL APLICAÇÃO UNIVERSAL PARA VEÍCULOS E MOTOCICLETAS QUE UTILIZAM LÂMPADA H4 12V 60/55W. GARANTIA 3 MESES CONTRA DEFEITOS DE FABRICAÇÃO ATENÇÃO NÃO NOS RESPONSABILIZAMOS POR MÁ INSTALAÇÃO, USO INADEQUADO OU ADAPTAÇÕES. IMAGENS MERAMENTE ILUSTRATIVAS. PARA DEVOLUÇÃO, O PRODUTO DEVE ESTAR NA EMBALAGEM ORIGINAL SEM AVARIAS. ANTES DE ABRIR RECLAMAÇÃO, ENTRE EM CONTATO PARA SUPORTE. LÂMPADA H4, PHILIPS H4, LÂMPADA 4300K, 60/55W, LUZ HALÓGENA, LÂMPADA FAROL, AUTOPEÇAS, ILUMINAÇÃO AUTOMOTIVA, VIDRO DE QUARTZO, FAROL H4, LÂMPADA MOTO, LÂMPADA CARRO, SEGURANÇA, ILUMINAÇÃO BRANCA, ORIGINAL PHILIPS.', 39.99,