INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254789128', 'Conjunto Infantil Menino Surfing Elian Azul', 'Trazendo um toque de leveza para dias ensolarados, o Conjunto Elian é composto por regata em meia malha e bermuda em tactel com elastano. A regata possui modelagem tradicional e estampa tropical junto com a frase "Surfing Day" (Dia de Surfe). Já a bermuda conta com elástico no cós e estampa em toda a peça, combinando com o tema de praia. Ideal para brincadeiras, passeios e momentos de lazer, esse conjunto é puro estilo e leveza. Aposte nesse look completo que é a cara do verão!Detalhes da peça: • Conjunto composto por regata e bermuda • Feito em meia malha e tactel com elastano • Possui estampa tropical • Possui elástico no cós • Ideal para brincadeiras, passeios e momentos de lazer', 74.9, 59.92, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-825ad-mr1tpgcspx5213', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58254789128', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
