INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210131390', 'Limpador Multiuso Veja Power Fusion Limão', 'Veja Power Fusion é a eficiência de Veja Multiuso, com a poderosa mistura de extrato de limão, bicarbonato e álcool. Máximo poder de limpeza nas sujeiras mais difíceis, restaura o brilho e seca rápido. O melhor multiuso de todos os tempos. Aplique o produto nas superfícies a serem limpas e, em seguida, passe um pano ou esponja macia. Para as sujeiras mais difíceis, deixar o produto agir por alguns instantes. Para superfícies verticais, recomenda-se aplicar o produto diretamente no pano. Atenção: para painéis de fogões: limpar com a superfície fria. Não usar em superfícies de madeira natural. Para superfícies de alumínio, mármore e superfícies pintadas/esmaltadas e com serigrafia, limpar imediatamente após a aplicação. Recomendação: Testar em uma pequena área escondida antes de usar.', 10.99, 10.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8259f-mqnel007hdzfca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676552986%2F58210131390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251986490', 'Ninho Polpa Iogurte Morango e Frutas', 'O Iogurte Ninho Polpa é perfeito para um lanche rápido e nutritivo a qualquer hora do dia. Cada bandeja contém seis unidades com os sabores Morango, Salada de Frutas, Maçã e Banana. Prático e delicioso, é uma ótima opção para levar na lancheira ou consumir em casa.', 14.49, 14.49, NULL, 'Food & Beverages > Beverages > Dessert Drink', 'https://cf.shopee.com.br/file/sg-11134201-825a6-mqnelfi2s64i80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302953%2F58251986490', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
