INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593562628', 'Kit Pré Treino Insane Clown 350g Demons Lab + Creatina Pura Alpex 150g', 'Novo Pré-treino Insane Clown da Demons Lab.Desenvolvido para quem busca atingir níveis insanos de FOCO, FORÇA e PUMP VASCULAR.Fórmula Insana, Pote Insano, Resultado Insano. Somente a maior inovadora em pré-treinos do Brasil poderia trazer essa novidade que vai abalar os principais atletas como você que está lendo isso e procurando um produto com matéria-prima importada, fórmula desenvolvida para foco, endurance e alto rendimento.BENEFICIOS- Massivo Pump;- Melhora na recuperação muscular;- Mais energia;- Melhora na resistencia muscular. "Desperte o verdadeiro poder dentro de você com a Creatina Monohidratada Alpex Nutrition! Projetada para impulsionar seus resultados de treino, nossa fórmula de alta qualidade, oferece o suporte necessário para alcançar seus objetivos. Aumente sua força, potência e resistência com cada dose, elevando sua performance a um novo nível. A Creatina Monohidratada Alpex Nutrition é a escolha ideal para atletas comprometidos que buscam maximizar seus ganhos. Liberte o seu potencial e conquiste um corpo mais forte e definido. Não aceite menos do que o melhor. Escolha Alpex Nutrition e alcance o extraordinário! Você no topo sempre!', 249.9, 149.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-7rffy-m3azc810b23b43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F325382732%2F23593562628', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
