INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23628796506', 'Kit Shampoo + Condicionador Equilíbrio Cabelos Mistos e Pontas Ressecadas 510ml', 'Você sente que tem dois cabelos em um? Já tentou de tudo para remover a oleosidade e resíduos da raiz dos seus cabelos sem deixar as pontas ainda mais secas? Então o Shampoo Pantene da coleção Equilíbrio Raiz e Pontas com óleo de baobá e algas marinhas é ideal para você. Seu complexo Pro-V Miracle penetra profundamente nos fios equilibrando os cabelos mistos, com pontas ressecadas ou espigadas, purificando as raízes oleosas e eliminando as impurezas e resíduos de produtos. Além disso, sua fórmula com ingredientes hidratantes e purificantes é segura para cabelos com luzes, pois limpa suavemente, equilibrando a oleosidade da raiz para cabelos mais soltinhos, frescos e brilhosos. Mergulhe nas sensações de exuberância, pureza e leveza de coração com a fragrância repleta de notas alegres de laranja, toranja e groselha e notas florais com uma pitada de água de coco que vão transportar você para uma experiencia inesquecível. A coleção Pantene Equilíbrio Raiz e Pontas elimina a oleosidade da raiz e hidrata as pontas. Você sente que tem dois cabelos em um? Já tentou de tudo para remover a oleosidade e resíduos da raiz dos seus cabelos sem deixar as pontas ainda mais secas? Então o Shampoo Pantene da coleção Equilíbrio Raiz e Pontas com óleo de baobá e algas marinhas é ideal para você. Seu complexo Pro-V Miracle penetra profundamente nos fios equilibrando os cabelos mistos, com pontas ressecadas ou espigadas, purificando as raízes oleosas e eliminando as impurezas e resíduos de produtos. Além disso, sua fórmula com ingredientes hidratantes e purificantes é segura para cabelos com luzes, pois limpa suavemente, equilibrando a oleosidade da raiz para cabelos mais soltinhos, frescos e brilhosos. Mergulhe nas sensações de exuberância, pureza e leveza de coração com a fragrância repleta de notas alegres de laranja, toranja e groselha e notas florais com uma pitada de água de coco que vão transportar você para uma experiencia inesquecível. A coleção Pantene Equilíbrio Raiz e Pontas elimina a oleosidade da raiz e hidrata as pontas.', 113.69, 113.69, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-23030-30t9b66ue7nv7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353664457%2F23628796506', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
