INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798920151', 'TRENA DE AÇO 5MTS X 19MM AUTO TRAVA VONDER PLUS', '1 Trena. Possui estojo anatômico em ABS com borracha termoplástica que confere maior resistência e conforto no manuseio e fita em aço com pintura fosca antirreflexo e graduação em milímetros/polegadas, facilitando a leitura e proporcionando maior precisão. Conta também com sistema autotrava, que mantém a fita travada quando esticada e facilita a leitura, alça em nylon e presilha para cinto, auxiliando no transporte e segurança durante o uso. Conta ainda com gancho ajustável. Indicada para medições em geral. Garantia legal: 90 dias Comprimento da trena: 5 m Graduação da trena: mm/pol Largura da fita: 19 mm Material da fita: Aço Acabamento da fita da trena: Pintura fosca Revestimento da fita da trena: Pintado Classe de precisão: Classe II Material da caixa da trena: ABS de alta resistência com borracha termoplástica Sistema de trava da trena: Autotrava Massa aproximada (peso): 0.212 kg', 19.9, 19.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8259e-metyxeso41dv9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F22798920151', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493893662', 'Desentupidora Elétrica 390W DV390 Vonder Com Acessórios Limpeza de Tubulações', 'Desentupidora Elétrica 390W DV390 Vonder A Desentupidora DV 390 é indicada para pias, tanques, esgotos e outras tubulações com diâmetros entre 3/4" e 4". Ideal para uso profissional, ela oferece potência e praticidade para lidar com diversos tipos de obstruções, como graxa, gordura e resíduos mais duros. Conta com sistema de reversão, embreagem que facilita o controle do cabo espiral e acompanha 9 acessórios para diferentes tipos de limpeza, garantindo maior versatilidade. Itens inclusos: 1 chave 7 lances de 2,3 metros de cabo flexível de 16 mm (totalizando 16,1 metros) 1 lance de 5 metros de cabo flexível de 8 mm 9 acessórios para trabalhos diversos Especificações técnicas: Referência: 6864390220 Modelo: DV 390 Massa aproximada: 12,5 kg Sistema de avanço do cabo: Manual Comprimento máximo do cabo de 16 mm: 30 metros Tensão: 220 V~ Potência: 390 W Rotação do motor: 400 rpm Frequência: 60 Hz Capacidade mínima de desobstrução: tubos de 3/4" (19 mm) Capacidade máxima de desobstrução: tubos de 4" (100 mm) Por que escolher este produto: Produto novo e original Pronta entrega e envio em até 24 horas Compra 100% segura', 3999.99, 3999.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mje5axqrm7sy54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F23493893662', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256406662', 'Sabonete Phebo Odor De Rosas Kit 3 Unidades 90g Cada', '*Produto Original* *Atenção:* Venda exclusiva para pessoa física. Pedidos com CNPJ serão cancelados. Kit com 3 unidades de 90g cada. Sabonete de glicerina com base 100% vegetal. Sua fórmula suave forma uma espuma intensa e cremosa que hidrata e dá mais maciez para a pele. Sua fragrância fixa melhor ao corpo, deixando-o perfumado por muito mais tempo.', 17.7, 17.7, NULL, 'Beauty > Bath & Body Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-8260b-mlxfezr79c052d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F58256406662', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
