INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20097679726', 'Livro A era imoral, por Depti Kapoor - Intrínseca', 'Livro A era imoral, por Depti Kapoor - Intrínseca Elogiado romance épico sobre dinheiro, poder, prazer, vingança e tragédias. Nova Déli, três da manhã. Uma Mercedes em alta velocidade sobe a calçada e, num piscar de olhos, cinco pessoas estão mortas. O carro pertence a um homem rico, mas quem é visto ao volante é um jovem funcionário em estado de choque, incapaz de explicar a série de eventos que culminou no crime que acaba de acontecer — ou de prever a trama sombria que está prestes a se desenrolar. À sombra de luxuosas propriedades, entre festas extravagantes, transações comerciais predatórias e uma influência política calculada com frieza, três vidas se entrelaçam perigosamente na esteira do trágico evento. A do suposto autor do crime, Ajay, diligente funcionário nascido na extrema pobreza que alça seu posto como “homem dos Wadia”; a de seu patrão, Sunny Wadia, jovem herdeiro e playboy que, embora careça da fibra implacável do pai, ainda assim deseja provar seu valor e destroná-lo; e, por último, a de Neda, uma curiosa jornalista que se vê presa entre o tédio das restritas ambições da classe média, uma paixão e a possibilidade de corromper os valores morais que sempre conheceu. Alternando com maestria o tempo e as perspectivas da narrativa e veloz como um filme de ação, é um épico que extrapola a Índia contemporânea ao desenvolver uma trama cujo motor são três dos mais básicos elementos de desejo no mundo moderno: riqueza, prazer e poder. Quem opera o centro de controle dessa máquina e seus tentáculos de influência é a família Wadia — amada por uns, odiada por outros, temida por todos —, ao redor da qual uma série de desgraças sucederá. Em meio a tudo isso, poderá a intrincada conexão entre Ajay, Sunny e Neda forjar uma rota de fuga? Ou será justamente o que apertará o gatilho de uma destruição irremediável? Sobre a autora: Depti Kapoor nasceu no norte da Índia e trabalhou por muitos anos como jornalista em Nova Déli. Também autora de A Bad Character, Kapoor hoje vive em Portugal com o marido. Detalhes do Livro: Tradução: Marcello Lino Páginas: 560 Gênero: Ficção - Romance literário Formato: 16 x 23 x 2,7 cm Peso: 744 gramas Tipo de capa: Brochura Lançamento: 13/03/2023 Aviso legal • Idade mínima recomendada: 18 anos.', 89.9, 89.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lus4rfawumhxe3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F20097679726', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13897405333', 'Rack para TV até 65 Polegadas Madesa Cancun com Pés - Rustic', 'Um móvel moderno e fabricado com materiais de alto padrão. Confira o Rack Cancun com Pés da Madesa. O tamanho é ótimo, comportando TV de até 65 polegadas. Possui nichos de espaços variados, entre abertos e fechados. Assim, cabe tudo de maneira organizada, desde aparelhos eletrônicos até objetos de decoração, livros e revistas. Conta com uma porta de correr que permite fechar o lado esquerdo ou direito da abertura central. Por fim, os pés aumentam a altura, complementam o visual e proporcionam melhor sustentação ao rack. O acabamento é no padrão amadeirado Rustic. O processo é feito em Poliéster Protetor com 7 camadas, detalhe que confere mais durabilidade e qualidade aos produtos. Além disso, é ecológico, isento de vapores prejudiciais à atmosfera. Imagens meramente ilustrativas. Itens inclusos: - Um (1) Rack de 64 cm de altura x 180 cm de largura x 32 cm de profundidade com pés em PVC Código do produto: 70085Z5ZPP Obs: A Madesa não disponibiliza serviço de montagem. O produto segue com manual e todas as ferragens necessárias para a instalação. A Madesa possui compromisso com a sustentabilidade. Geramos energia limpa em nossa própria usina, priorizamos fornecedores responsáveis e utilizamos plástico reciclado em nossa produção. Além disso, reinserimos sobras no ciclo de reciclagem e investimos no desenvolvimento de nossos colaboradores e da comunidade. Garantia: Este produto conta com 1 ano de garantia total, sendo 3 meses de garantia legal e 9 meses de garantia contratual. A garantia cobre exclusivamente defeitos de fabricação e vícios ocultos. Não estão cobertos: problemas decorrentes de montagem incorreta, uso inadequado, exposição à umidade, calor ou luz solar direta, modificações no produto ou desgaste natural.', 469.99, 399.99, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-7rd6f-lx8nezi5q6py0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F872473112%2F13897405333', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
