INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394076243', 'Engate Reboque Reforcel Fixo Fiat Siena 1997 até 2008 2009 2010 2011 2012 2013 2014 2015 2016', 'Engate Reboque Fiat Siena 2008 2009 2010 2011 2012 2013 2014 2015 2016 Reforcel Rabicho Tração 500Kg Haste Fixa O que é engate? Com o engate rabicho seu carro ganha mais uma opção no transporte de cargas e vai conseguir tracionar um peso maior, ampliando sua capacidade de carga e tracionando caretinhas, trailers, transbikes e reboques em geral. Fabricado em aço resistente e excelente acabamento, possui homologação pelo INMETRO e certificação nos padrões das montadoras, adicionando mais proteção e segurança para a parte traseira do veículo. Serve no meu carro? Fiat Siena 2008 2009 2010 2011 2012 2013 2014 2015 2016 Todas as versões Em caso de dúvida consulte o profissional ou nossos canais de atendimento sobre a compatibilidade do produto. Qual o modelo do produto? Reforcel - REFT4001 Quais as características do produto? Tração máxima de 500KG de carga (verifique a limitação do seu veículo) Peso máximo sobre a bola de 30KG Com haste fixa Sem necessidade de furação no veículo Fabricado em aço carbono altamente resistente Pintura eletrostática a pó; Excelente acabamento Esfera cromada maciça de 50mm de diâmetro Tomada totalmente funcional para instalação elétrica Não possui superfícies cortantes Encaixe sob medida Plaqueta indicativa com dados técnicos Homologado pelo INMETRO e normas exigidas pelo orgão fiscalizador *Recomendamos que a instalação seja feita por profissional especializado. Qual o conteúdo da embalagem? 01 engate 01 bola 01 capa 01 tomada elétrica Kit de fixação (a maioria dos veículos utilizam o próprio parafuso original) NÃO NOS RESPONSABILIZAMOS PELO FRETE DE DEVOUÇÃO CASO A PEÇA NÃO SIRVA. TIRE TODAS AS SUAS DÚVIDAS ANTES DA COMPRA.', 341.96, 338.55, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ravq-maotuk3xj4ae56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1069588064%2F23394076243', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54808967094', 'Bota Feminina Memphis Texana Country Western Cano Bordado Leve e Confortável - Marrom', 'Bota Feminina Memphis Texana Country Western Impermeável Cano Bordado - Marrom - A bota que não para: estilo Western autêntico com a praticidade da base impermeável para te acompanhar do festival ao dia a dia. O ícone do estilo Western, agora à prova de qualquer clima. A Bota Feminina Memphis Estilo Texana chega para redefinir o conceito de bota country. Se você busca um visual marcante para festivais, rodeios ou para compor um look urbano moderno, este modelo é a escolha estratégica. Ela une a sofisticação dos bordados artesanais à inteligência de materiais modernos. Design Híbrido e Funcional: O grande diferencial da Memphis está na sua construção. A parte inferior é injetada em PVC Microexpandido de alta tecnologia, tornando-a totalmente impermeável. Esqueça a preocupação com poças d''água ou mudanças repentinas no tempo; seus pés continuam secos e o calçado impecável. Estética Western Raiz: O cano alto em material sintético premium apresenta bordados ornamentais em relevo, trazendo a textura e o visual das botas tradicionais do Texas. O acabamento em tom terroso é atemporal e combina perfeitamente com shorts jeans, vestidos fluidos ou calças skinny. Por que a Memphis é sua próxima favorita? Diferente das botas de couro rígido, a Memphis oferece uma leveza surpreendente. O solado tratorado discreto oferece aderência, enquanto o design interno prioriza o conforto para quem precisa de um calçado que aguente o ritmo do dia (e da noite). Características do produtos: - Estilo Boho Chic & Western: Tendência absoluta com bordados clássicos no cano. - 100% Protegida: Base em PVC Microexpandido impermeável — estilosa até sob chuva. - Conforto Prolongado: Material leve e flexível que garante o bem-estar o dia todo. - Calce Facilitado: Zíper lateral discreto para maior praticidade. - Salto Bloco Baixo: Estabilidade e elegância sem cansar os pés. Ficha Técnica: - Marca: Memphis - Gênero: Feminino Adulto - Estilo: Western / Country / Boho - Material do Cano: Sintético Premium com Bordado Western - Material da Base: PVC Microexpandido (Impermeável e Antiderrapante) - Tipo de Salto: Bloco Baixo (Aprox. 3 a 4 cm) - Fechamento: Zíper Lateral Reforçado', 139.9, 79.9, NULL, 'Women Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/sg-11134201-81ztu-mn4jkgshn1fq73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404144117%2F54808967094', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50207468809', 'Caixa Amakha Paris - Media', 'Encante em todos os momentos com as caixas presenteáveis da Amakha Paris, perfeitas para transformar qualquer ocasião em uma experiência inesquecível. Desenvolvidas com design elegante e acabamento sofisticado, elas valorizam ainda mais os perfumes e cosméticos da marca, unindo beleza, cuidado e bom gosto. Ideais para aniversários, datas comemorativas, lembranças especiais ou para surpreender quem você ama, as caixas presenteáveis Amakha Paris transmitem exclusividade e requinte desde o primeiro olhar. Um presente completo, pronto para impressionar, que reflete luxo acessível e fragrâncias marcantes.', 70.0, 70.0, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-82617-mm25x5y4cu886f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1454161052%2F50207468809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58263445022', 'Cilindro Mestre Freio Kombi 1200 Ar 1500 Ar 1960 A 1975 Simples Ferro Fundido 4 Saídas M10x1', 'CILINDRO MESTRE DE FREIO – SBC1247 – ALTA QUALIDADE E SEGURANÇA Garanta máxima eficiência e segurança no sistema de frenagem do seu veículo com este cilindro mestre de freio de alta qualidade, desenvolvido para oferecer excelente desempenho, durabilidade e confiabilidade. Produto novo Cilindro mestre simples Fabricado em ferro fundido Alta resistência e longa vida útil Aplicação VOLKSWAGEN Kombi – motor 1500 Ar – 1967 a 1975 Kombi – motor 1200 Ar – 1960 a 1966 (Consulte a compatibilidade antes da compra.) Especificações Código do produto: SBC1247 Tipo: Cilindro mestre de freio Cilindro mestre simples Material: Ferro fundido Diâmetro: 22,22 mm 4 saídas M10x1 Instalação: Substituição direta Referências Controil: C2084 OEM: 211611011J TRW: RCCM22946 Conteúdo da embalagem 01 Cilindro mestre de freio Importante Recomendamos que a instalação seja realizada por um profissional especializado. Verifique a compatibilidade pelo modelo, motorização e ano do veículo antes da compra. Em caso de dúvidas, utilize o campo de perguntas. Envio Produto com envio rápido e embalagem segura.', 139.9, 125.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-8257z-mq3rnn62f37v5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1229255557%2F58263445022', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
