INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598508920', 'Volante Caminhão Scania 112 113 112E 113E 112M 113H 112H', 'Oferecemos durabilidade e resistência incomparáveis. Nossos volantes foram projetaods para oferecer máxima segurança, garantindo aderência firme e conforto, proporcionando controle absoluto em todas as suas viagens. CONTEÚDO DA EMBALAGEM: • Volante Esportivo Personalizado; • Diâmetro de 370mm; • Cubo Adaptativo; • Emblema; • Parafusos para instalação. COMPATIBILIDADES: • Scania 112 • Scania 113 EXCLUSIVIDADE • Qualidade superior em poliuretano: Volantes com toque macio, controle preciso e resistência excepcional, graças ao poliuretano de alta tecnologia e cubos metálicos que garantem segurança e durabilidade. • Personalização única: Volantes em diversas cores e compatibilidades, ideais para realçar o estilo e a personalidade do seu carro. • Atendimento especializado: Se não encontrar seu modelo em nossa descrição, entre em contato com nossa equipe e nós ajudaremos a encontrar a solução ideal para você. IMPORTANTE: • Verifique a compatibilidade do anúncio com seu veículo. Tire suas dúvidas ANTES da compra. • Entrega rápida: Compras realizadas hoje serão despachadas no próximo dia útil. • Recomendamos a instalação por um profissional. • A instalação dos nossos volantes resulta na perda da funcionalidade do airbag. Eleve a experiência ao dirigir com nossos volantes', 299.99, 240.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mb3r6kpmzpbt2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F954535653%2F23598508920', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
