INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593341040', 'Alto Falante Woofer 12 Pol Bomber Atrack 550w 4 Ohms Bobina Simples', 'Bem vindo(a) a E-zee Shop! Leia atentamente a descrição e ficha técnica do produto. Se ainda surgir alguma dúvida entre em contato com a gente através do Chat que iremos te ajudar :) _______________________________________ Woofer 12 Pol Bomber Atrack 550w 4 Ohms Bobina Simples Woofer Atrack de 12" suporta até 1100W rms de potência em programa musical de Grave Pancadão, perfeito para quem quer reproduzir um grave que faz tremer as estruturas onde quer que passe. Este super projeto possui: aranha em polycotton, cone de celulose, bobina em kapton com fio CCAW, conjunto magnético com ferrites de bário, e carcaça em aço de alta resistência. Especificações • Potência de programa musical: 1100 W RMS (Uso contínuo) • Potência RMS: 550 W RMS (AES) • Impedância nominal: 4 Ohms • Potência (Programa musical): 1100 W • Potência (RMS – AES): 550 W • Resp. em frequência (- 10 dB): 46 - 5000 Hz • Resp. em frequência (- 3 dB): 60 - 3800 Hz • Sensibilidade (Banda Efetiva): 94 dB SPL • Diâmetro da bobina: 90 mm • Altura do enrolamento / Camadas: 22 mm / 2 • Material do corpo da bobina: Kapton • Material do fio da bobina: CCAW • Altura do gap: 9,3 mm • Xmax (deslocamento máx. pico): 6,4 mm • Xlim (antes do dano): 15,7 mm • Diâmetro do imã: 190 x 19 mm • Material do cone: Celulose • Material da centragem: Poliéster + Algodão • Material da carcaça: Aço • Peso líquido: 6,6 kg • Volume alto-falante ocupado na caixa: 3,66 L Conteúdo da Embalagem • Woofer Atrack de 12 • Manual de Instruções', 568.99, 379.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0j6ocuxvbz129', 'https://shope.ee/an_redir?origin_link=