INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794682113', 'MARTELO DE BORRACHA PRETA, CABO DE MADEIRA, 1PC // SPARTA', 'Martelo de Borracha Sparta 1114055 Ferramenta profissional, ideal para colocação de cerâmicas, laminados, endireitamento de metais e montagem de móveis, garantindo precisão e proteção das superfícies. Principais Vantagens: Confiabilidade segura: Cabeça firmemente fixada ao cabo, eliminando riscos de desprendimento durante o uso intenso. Alta resistência mecânica: Cabeça em borracha com dureza de 80 Shore, projetada para suportar trabalhos exigentes sem perder desempenho. Proteção do cabo: Cabo de madeira com revestimento transparente que mantém a estética e protege contra desgaste. Conforto prolongado: Cabeça de 340 g balanceada para uso confortável e redução da fadiga durante trabalhos longos. Versatilidade: Excelente para diversas aplicações que exigem cuidado, precisão e durabilidade. O Martelo de Borracha Sparta 1114055 é a escolha certa para profissionais que buscam uma ferramenta resistente, eficiente e confortável, garantindo resultados precisos em qualquer projeto.', 18.18, 18.18, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821fq-mgz1mdl8lcst52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F22794682113', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20298033031', 'Braço Traseiro + Palheta Traseiro PALIO ATTRACTIVE 2016/2017 - 83622 - 1510044', 'Braço Traseiro + Palheta Traseiro PALIO ATTRACTIVE 2016/2017 12" - Kit - Braço + Palheta', 92.47, 92.47, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rd44-m6v6cbs6zz4id7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20298033031', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898365287', 'Bomba Gasolina GOL 1994/2005 - 71342 - 10107', 'Bomba Gasolina GOL 1994/2005 1.0/1.6/1.8/2.0 - Gasolina - 3 Bar - 12V - 100L/H - MultipontoPodemos dividir as bombas de combustível elétricas em dois tipos, interna e externa ao tanque. A interna trabalha submersa aspirando o combustível diretamente do fundo do tanque para as mangueiras de abastecimento que ligam aos bicos injetores. A externa trabalha fixada ao chassi do veículo, próxima ao tanque ou ao motor, sugando o combustível do tubo coletor localizado no tanque', 69.24, 69.24, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7repv-m832uyxr5ztj8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22898365287', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192823055', 'Radiador Celta 2006 2007 2008 2009 2010 11 Até 2015 Sem Ar - 64374 - I48204/20752523', 'Radiador Celta 2006 2007 2008 2009 2010 11 Até 2015 Sem Ar motor 1.0/1.4 - SEM AR (ALUMINIO MECANICO) MANUAL (552x322x23) O radiador, faz parte do sistema de resfriamento da água que circula pelo bloco do motor, fazendo com que a temperatura não exceda os limites aconselháveis para o funcionamento do motor. A temperatura ideal para a água é de 70º C praa gasolina e de 80º C nos a álcool e a diesel. A água quente que sai do bloco do motor, circula forçadamente pelo interior dos tubos do radiador, onde é resfriada. Essa água é resfriada porque através do bloco, é forçada a circulação de ar, através de um ventilador.', 244.05, 244.05, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rceu-lqtl4rle1hht31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23192823055', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697424441', 'Puff Decorativo Living Sala de Estar 160 cm Roma W01 Suede Bege - Lyam', 'O Puff Recamier Roma, é uma peça versátil que combina estilo e conforto de maneira única. Com seu design contemporâneo, este Puff é mais do que apenas um assento, é um convite para relaxar, acrescentando personalidade e charme ao seu recinto. Vale ressaltar seus detalhes em costura rebatida que trazem o acabamento impecável, sendo assim uma peça de arte que eleva o charme do ambiente que estiver! Meticulosamente elaborado para se encaixar em diversos espaços de sua casa, sua estrutura durável oferece suporte confiável, enquanto seu estofamento traz toques de suavidade e requinte ao ambiente. Em resumo, é uma alegação de estilo deixando qualquer espaço mais convidativo, para relaxar em momentos de tranquilidade. Adquira já o seu! Dimensões do produto (L x A x P) 160 x 51 x 52 cm Características: Estrutura em Madeira Reflorestada. Revestimento em Suede na cor Bege. Detalhes em Costura Rebatida, com ótimo acabamento. Estofado com Espuma D-23. Pés em Sapatas Plásticas. - Por se tratar de estofado as medidas podem ter uma pequena variação de até 3 cm. - A tonalidade do produto real poderá ter ligeira variação devido o lote de tecidos. Observações importantes: - Produto para uso residencial em ambiente interno, não devendo ficar exposto diretamente ao sol, calor e umidade excessivos. - Pode haver alguma diferença de tonalidade entre a imagem e o produto real, por conta do tratamento de imagens e a calibração de cores do seu monitor. - As imagens são meramente ilustrativas, não acompanham objetos de decoração e eletrônicos. - Ao receber a mercadoria, o cliente deve verificar as condições da embalagem, caso haja alguma avaria não assine o comprovante de recebimento. - Montagem, desmontagem e outras instalações serão de responsabilidade do cliente. Não nos responsabilizamos, no ato da entrega, por subir escadas/elevadores ou pelo transporte por guincho em apartamentos. Eventuais despesas são de responsabilidade do comprador. - Confira as dimensões do produto e certifique-se de que passará normalmente por supostos elevadores, portas, escadas e/ou corredores de sua residência.', 643.9, 566.64, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rce3-ltb050crz8qp88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1107280577%2F22697424441', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200400714', 'Par De Palhetas Dianteira Clio De 1999 Até 2017 Dyna', 'Palhetas - DYNA 317 - Produto Novo e Original - Fabricante Dyna - Garantia de 6 meses pelo fabricante. Confira a aplicação completa abaixo. Palheta metálica feita em aço carbono pré-zincado (Alta resistência à intempéries). Lâmina limpadora em borracha natural moldada. Limpeza silenciosa. Para veículos com sistema de conexão tipo gancho (G) Conteúdo da Embalagem: 01 Palheta Dianteira Lado Esquerdo Motorista (Medidas 500mm - 50 cm - 20" Polegadas) 01 Palheta Dianteira Lado Direito Passageiro (Medidas 450mm - 45 cm - 18" Polegadas) Chevrolet Astra de 1999 até 2011 Corsa Hatch Novo de 2001 até 2012 Corsa Sedan Novo de 2001 até 2011 Montana de 2003 até 2010 Honda Civic de 1991 até 2000 Renault Clio de 1999 até 2017 Clio Sedan de 2000 até 2009 Toyota Corolla de 1992 até 2001 Corolla Wagon de 1992 até 2001 Volkswagen Polo Classic de 1997 até 2000 Van de 1997 até 2002 Sobre a marca: A Dyna é referência no mercado de reposição há mais de 65 anos e fornece Originalmente para as montadoras sendo uma das mais importantes fabricantes do mercado mundial. É líder no Brasil e já produziu cerca de 600 milhões de peças. Para entregar o melhor produto, a empresa investe em equipamentos e profissionais altamente qualificados. Pensou Palheta, pensou Dyna ! Quem somos: Somos um distribuidor de auto peças, com mais de 20 anos de experiência e presença nacional. Todos os produtos comercializados diretamente dos fabricantes, garantindo assim sua procedência.', 93.5, 93.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-821ed-mgqvl6vfcsui79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1629511923%2F58200400714', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297897320', 'Bóia Tanque Sensor Nível Fiat Argo 2017 a 2024 - 1333053 - T010129', 'Bóia Tanque Sensor Nível Fiat Argo 2017 a 2024 1333053 T010129 1.8 16v - Flex (Sistema Bosch) O sensor de nível de combustível tem a função de medir a quantidade de combustível presente no tanque e informar a UCE (Unidade de Comando Eletrônico) que, por sua vez, controla a posição do marcador de nível no painel de instrumentos do veículo.', 100.7, 100.7, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rblv-lmxerrl90ndl36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23297897320', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10048344787', 'Fralda Pampers Premium Care Nova Mega Tamanho XXG 24 Unidades', 'Pampers Premium Care , nossa proteção mais suave para a sua pele. É suave como o algodão° e ultra respirável. Também tem canais de ar para uma pele seca e arejada, e uma loção hipoalergênica exclusiva que ajuda a prevenir irritações. Experimente o Pampers Premium Care, a escolha número 1 de pediatras *. ->A escolha N°1 de pediatras* Nossa proteção mais suave para sua pele ->Suave como algodão°: a proteção mais suave da Pampers ->Canais de Ar: para uma pele arejada e sequinha ->Loção hipoalergênica exclusiva: ajuda a prevenir irritações ->Incrível sistema de absorção que oferece até 12 horas de sono sequinho** ->Ajuste cômodo e flexível: esticam e se ajustam aos movimentos do seu bebê ->Barreiras anti-derrames *Pesquisa realizada em setembro de 2017 para 221 pediatras em Argentina, Brasil e Chile sobre a marca de fraldas que eles escolhem para seus filhos °Não contém fibras de algodão **Pode variar de acordo com os hábitos e características do bebê Modo de Usar: Coloque o bebê sobre a fralda, desgrude as fitas e puxe-as, grude as fitas sobre a faixa decorada. Peso Indicado:+ 15 Kg Composição: Celulose, Polímero Superabsorvente, Polietileno, Polipropileno, Poliéster, Adesivos, Elásticos, Fragrância, Petrolato, Álcool Estearílico E Extrato De Aloe Barbadensis.', 77.99, 67.23, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/c8e2f39022e5158e2baafb5d929908a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F10048344787', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997054507', 'Mangueira Radiador Peugeot 206 1998 a 2005 - 131086 - 6500', 'Mangueira Radiador Peugeot 206 1998 a 2005 131086 6500 Superior Radiador MOTOR 1.4 8V (TU3JP) / 1.6 8/16V (tu5jp) - Gasolina (Ø 30mm) O liquido entra no radiador pela "mangueira superior", em geral conectada na parte de cima do radiador. A medida que o liquido desce, ele passa por canais no radiador resfriados por meio de passagem do ar pelas aletas de refrigeração entre os canais. Depois ser resfriado, o liquido sai do radiador pela "mangueira inferior". Em geral, há uma mola dentro dessa mangueira para evitar que ela quebre quando a bomba de agua puxa o liquido do radiador.', 41.66, 41.66, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbk9-lmxiluxg2cs904', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22997054507', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27293827234', 'Creme Facial Antirrugas Eucerin Hy-Fi 3X Effect Noite 50ml', 'Eucerin Hyaluron-Filler 3x Effect Creme Anti-rugas Noite é um tratamento facial antienvelhecimento que atua durante a noite para combater rugas profundas e promover a renovação celular da pele. Sua fórmula combina três ativos poderosos em uma tecnologia exclusiva: o Ácido Hialurônico hidrata intensamente e preenche rugas, a Saponina Bioativa estimula a produção natural de colágeno e ácido hialurônico, e a Enoxolona protege contra a degradação dessas moléculas essenciais para a firmeza e elasticidade da pele. Enriquecido com Dexpantenol, o creme favorece a regeneração da pele durante o sono, oferecendo resultados visíveis em apenas 2 semanas de uso contínuo. Sua textura rica e cremosa tem rápida absorção, ideal para todos os tipos de pele. Dermatologicamente testado, o produto é altamente eficaz e bem tolerado, tornando-se uma excelente escolha para incluir na rotina de skincare de cuidados noturnos com a pele. Resultados percebidos em estudo com 120 mulheres (35–55 anos) após 4 semanas de uso regular: • 100% perceberam redução de rugas profundas; • 100% relataram que não houve formação de novas rugas; • 99% notaram efeito de cuidado intenso; • 98% perceberam recuperação da pele durante a noite; • Hidratação intensa por 24 horas, com melhora contínua com o uso regular.* *Estudo de produto em uso com 120 mulheres, com idades entre 35 e 55 anos, durante 4 semanas de uso regular.', 329.28, 329.28, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-81zut-mid1fp5ftkhsb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F27293827234', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21798998868', 'Água Bi-Desmineralizada Diversos Universal 1959 a 2016 - 196183 - 1010', 'Água Bi-Desmineralizada Diversos Universal 1959 a 2016 196183 1010 Uso Especial para Bateria e Radiadores - (1 Litro) A Água Bi-desmineralizada Radnaq, foi desenvolvida especialmente para aumentar a durabilidade de sua bateria, podendo ser usada em todo o tipo de bateria (automóveis, motos, barcos, caminhões, tratores, empilhadeiras, etc). Também se aplica na diluição de aditivos para refrigeração líquida de sistemas selados como carros, motos e equipamentos que utilizam radiador. A água passa por pré-filtro, filtros de carvão ativado e 2 filtros de resinas trocadoras, eliminando totalmente suas impurezas.', 9.97, 9.97, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-822y4-mo9t3n4ljq4sfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21798998868', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698435146', 'SUPORTE BI-ARTICULADO PARA TV DE 23" A 65", MOD: AR-E13SB03', 'SUPORTE BI-ARTICULADO PARA TV DE 23” A 65” polegadas Marca : MXT Modelo: AR-13SB03 Suporta 23, 24, 27, 29, 32, 39, 40, 42, 49, 50, 55, 65 polegadas Distancia da parede de 5,8 cm a 24,3 cm Inclinação de 0 a 15 graus Padrao Vesa parafusos : 75x75 100X100 200X100 200X200 400X200 300X300 400X400 Peso suportado: 30kg', 79.94, 64.55, NULL, 'Home Appliances > TVs & Accessories > TV Brackets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8z12f2qtfcy6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1418840072%2F22698435146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197478911', 'Válvula Canister Vw Parati 1989 a 1994 - 107179 - 087133', 'Válvula Canister Vw Parati 1989 a 1994 107179 087133 MOTOR AP/CHT Á VÁCUO É um reservatório que contém carvão ativado, ele armazena os gases de combustível que evaporam do tanque, o motor passa a funcionar a válvula do canister que é acionada pelo módulo eletrônico de controle, para que o motor queime os gases de combust. armazenados. A válvula defeituosa pode até mesmo levar o sist. de injeção a adotar um estado de emergência, veículos da VW, não utilizam a luz de anomalia da injeção no painel, assim o motorista não vê o problema, e continua a trafegar com o veículo', 39.85, 39.85, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-823qi-mp16jstrclqk8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22197478911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499005760', 'Filtro Combustível Peugeot 207 2008 a 2013 - 202645 - FCI1630', 'Filtro Combustível Peugeot 207 2008 a 2013 202645 FCI1630 (Blue Lion/Quicksilver/Passion/X-Line/XR) 1.4 8V Flex /(Passion/Quicksilver/XS) - 1.6 8v Flex O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 25.94, 25.94, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbkf-lmqnfr92ondm63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18499005760', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18297740542', 'Guarda Roupa Infantil Ariel 6 Portas 6 Gavetas Branco', 'Guarda Roupa Infantil Ariel 6 Portas 6 Gavetas Branco O Guarda Roupa Ariel e um produto perfeito para quem possui um ambiente com espaco reduzido e ainda procura qualidade e durabilidade no mesmo movel. Combinado com 6 portas, 6 gavetas, 3 prateleiras e um grande Cabideiro, deixando o produto com uma otima divisao interna. O Cabideiro alem de resistente, e ideal para pendurar pares de blusas, camisas acessorios. O maleiro e ideal para guardar malas, cobertores, edredons. Estrutura do produto em MDP. As prateleiras sao perfeitas para colocar roupas como blusas, shorts, regatas, kits de maquiagem, toalhas, caixinhas com acessorios e bolsas menores. As gavetas fixadas sobre corredicas metalicas, sao ideais para guardas blusas dobradas, shorts, malhas e roupas intimas. Indicado tbm para ambientes infantis, como quartos e brinquedoteca. Dimensoes: Altura: 187 cm Largura: 153 cm Profundidade: 40 cm Peso: 71,3 kg Garantia do fabricante: 3 Meses', 738.44, 738.44, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-7rdws-lypgv4m8kwvo76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F18297740542', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
