INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393427378', 'Coralit Fundo Zarcão Proferro Laranja 900ml Alta Proteção Contra Corrosão- Coral', 'Zarcão Proferro Coral Coralit – Fundo Anticorrosivo para Metais Imagine suas superfícies metálicas totalmente protegidas contra ferrugem e corrosão, mantendo resistência, durabilidade e um acabamento profissional por muito mais tempo. O Zarcão Proferro Coral Coralit foi desenvolvido para criar uma barreira protetora eficiente, prolongando a vida útil do metal e garantindo melhor resultado na pintura final. Com excelente aderência e aplicação simples, ele prepara a superfície para receber o acabamento com mais uniformidade e proteção, entregando um resultado mais resistente e duradouro. Benefícios e Características: • Alta proteção anticorrosiva, formando barreira contra ferrugem • Excelente aderência em superfícies metálicas ferrosas • Fácil aplicação com pincel, rolo ou pistola • Secagem rápida para maior agilidade no projeto • Acabamento fosco uniforme e profissional • Melhora a durabilidade da pintura final • Ideal para uso externo em estruturas metálicas Dados Técnicos: Produto: Zarcão Proferro Coral Coralit Tipo: Fundo sintético anticorrosivo Volume: 900ml Cor: Laranja Acabamento: Fosco Rendimento: • Até 12,5 m² por embalagem Diluição: • Pincel/rolo: até 10% com diluente aguarrás • Pistola: até 30% com diluente aguarrás Secagem: • Ao toque: 4 a 6 horas • Entre demãos: 8 horas • Secagem final: 12 a 18 horas Aplicação: Pincel, rolo de espuma ou pistola Aplicação – Passo a Passo: 1. Preparação da superfície: remover ferrugem, sujeira e graxa, lixando se necessário 2. Mistura: homogeneizar bem o produto antes da aplicação 3. Aplicação: aplicar uma demão uniforme com pincel, rolo ou pistola 4. Secagem: aguardar o tempo recomendado antes de novas demãos 5. Acabamento: após seco, pode receber esmalte sintético da linha Coralit para maior proteção Principais perguntas: Acompanha nota fiscal? Sim, todos os produtos são enviados com nota fiscal. O envio é por Correios? Pode ser enviado por Correios ou transportadora, dependendo da disponibilidade da região. Porque não posso comprar mais de 4 unidades no mesmo pedido? Devido às limitações de transporte por peso e volume, o envio é limitado a até 4 unidades por pedido. Só Tintas, sempre a melhor opção. Desde 1977 oferecendo soluções em pintura imobiliária, automotiva e industrial, com mais de 30 lojas físicas no estado do Rio de Janeiro.', 106.73, 66.18, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7rdw1-m1d8ci394mpd66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1219384404%2F23393427378', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
