INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23024988193', 'Piercing Helix Conch Labret Aço Cirúrgico PVD Piercing Tragus 18k Raio Piercing Orelha de Raio【Lomiss piercing】', '💖 💖 🥳 🥳 Bem-vindo a 《Lomiss piercing》🥳 🥳 💖 💖 🎊🎊👍👍Somos uma grande empresa de piercing. O endereço está localizado em São Paulo.Todos os produtos da loja são de alta qualidade. 👍👍🎊🎊 🚚 🚚🚀 🚀 Temos uma grande quantidade de estoque. Enviaremos seu pedido em até 48 horas após o pagamento. 🚀 🚀🚚 🚚 🎉🎉🎫 🎫Clique em "SEGUIR" e obtenha o cupom de desconto "5%off"🎫 🎫🎉🎉 💎- Modelo: Labret 💎- Espessura Da haste:1.2 mm 💎- Comprimento da haste: 8mm 💎- Material: Aço Cirúrgico 💎- Fecho: Rosca 💎Piercing 100% Novo e a Pronta Entrega - Podendo ser Usado: Helix, Tragus, Conch, Nariz, Boca-Medusa e Outros Este piercing labret de aço cirúrgico apresenta um design moderno e elegante em forma de raio. O banho de PVD adiciona uma camada de proteção à peça, garantindo durabilidade e resistência à oxidação. O tamanho é padrão para ser usado em piercings de lábio inferior, apresentando uma barra reta com rosca interna que facilita a colocação e a remoção da joia. Este piercing é ideal para quem busca uma peça de qualidade e estilo para complementar o visual.', 25.9, 25.9, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/br-11134201-23020-53ovc9ax9lnv3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F493729464%2F23024988193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
