INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398462652', 'Mala de Viagem Grande Katerini ABS Expansiva Rodas 360 Up4you', 'A Mala de Viagem Grande Katerini Expansiva ABS Up4you com Rodas 360 e Cadeado é ideal para quem busca espaço, segurança e praticidade em viagens longas, nacionais e internacionais. Produzida em ABS resistente, oferece maior proteção contra impactos e durabilidade durante o transporte. Seu acabamento sofisticado na cor bege proporciona visual moderno, elegante e versátil para diferentes estilos de viagem. O modelo conta com sistema expansivo, permitindo aumentar a capacidade interna para acomodar roupas, acessórios e objetos com ainda mais praticidade. Possui 4 rodas duplas com giro 360°, proporcionando deslocamento leve, silencioso e maior estabilidade em aeroportos, hotéis e rodoviárias. Conta ainda com cadeado integrado com segredo, oferecendo mais segurança para os pertences e praticidade em viagens internacionais. Seu carrinho embutido com regulagem de altura proporciona conforto durante o transporte, além de possuir alça superior e lateral reforçadas, facilitando o manuseio em diferentes posições. O interior é totalmente forrado e organizado, com divisória interna com fechamento em zíper, bolso organizador em tela e cinta elástica com trava para melhor acomodação dos itens durante a viagem. O modelo possui detalhes premium, como acabamento refinado, protetores de canto metalizados e rodas personalizadas Up4you. Mala de Viagem Grande Expansiva ABS Up4you Modelo: MF10379UP-28 Dimensões: Altura: 77 x Largura: 50 x Comprimento: 32 cm Peso: 4,9 kg Capacidade: Grande Classificação: Viagem Longa Material: ABS Expansiva Rodas Duplas com Giro 360° Cadeado com Segredo Carrinho Embutido com Regulagem Alça Superior e Lateral Forro Interno Personalizado Divisória Interna com Zíper Bolso Organizador Interno Cinta Elástica Organizadora Protetores de Canto Metalizados Logo Up4you em Alto Relevo Rodas Personalizadas Up4you Dicas de uso: ideal para viagens longas, férias em família, viagens internacionais e grandes volumes de bagagem. Dicas de limpeza: limpar com pano úmido e sabão neutro. Evitar produtos abrasivos para preservar o acabamento do material.', 389.9, 369.9, NULL, 'Travel & Luggage > Travel Bags > Others', 'https://cf.shopee.com.br/file/sg-11134201-823pa-mopqw0qzhd6z6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251967897%2F23398462652', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
