INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46910146997', 'Boneco Funko Pop! Rambo 2 - John Rambo', 'Entre em ação com o Boneco Funko Pop! John Rambo, inspirado no clássico Rambo 2 : A Missão e no lendário personagem vivido por Sylvester Stallone. Com arco em mãos e pronto para a batalha, Rambo ganha vida neste colecionável com visual marcante e cheio de atitude, representando toda a força e determinação do herói. Com aproximadamente 11 centímetros de altura e acabamento em vinil, a peça apresenta detalhes que se destacam em qualquer coleção. Ideal para fãs de filmes de ação, colecionadores e apaixonados por cultura pop, este Funko Pop! é indispensável para quem busca adrenalina, nostalgia e personagens icônicos em um só produto.', 149.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-820nd-mnyo7n1i2lms07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F46910146997', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
