INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693398124', 'Película para iPad Pro 11" - Hydrogel HD - Gshield', 'DESCRIÇÃOA Película de Hydrogel da Gshield oferece proteção avançada para a tela do seu tablet, garantindo uma experiência duradoura e sem preocupações. Com tecnologia inovadora de hidro nano PET e TPU Soft Gel, essa película protege contra riscos indesejados. O revestimento oleofóbico não só aprimora a resistência a arranhões, mas também minimiza marcas de digitais, proporcionando uma visualização sempre clara e nítida. A película se ajusta perfeitamente às extremidades curvas do seu dispositivo, assegurando uma cobertura total sem comprometer a estética e a funcionalidade. Optar pela Película de Hydrogel Gshield é escolher um escudo sofisticado que combina tecnologia de ponta e durabilidade, mantendo a tela do seu dispositivo sempre impecável. Cuide do seu iPad Pro 11" com estilo e confiança, escolhendo a excelência em proteção que só a Gshield oferece. ESPECIFICAÇÕESMaterial: Hidro nano pet + TPU Soft Gel Marca: GshieldEspessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Grau de transparência: 97% High DefinitionCertificações: US MilitaryDimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais. ITENS INCLUSOS1x Película de Hydrogel1x Espátula de aplicação1x Kit de instalação', 98.97, 98.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rdxb-m0os7672bfni35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22693398124', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12120357196', 'Carregador Portátil Power Bank Universal 5.000mah Usb A + 1 Usb C Power Powerfit Certificado Anatel', 'Carregue celulares, smartphones e outros aparelhos que possuam entrada USB. O Carregador Portátil Powerfit​ da Gorila Shield possui 5.000mAh! Com ele você pode carregar o seu celular onde e quando quiser, dá para fazer até 2 recargas dependendo do modelo do seu aparelho. Vale lembrar que o carregador possui três conectores: 1 USB padrão, uma type c e outra Micro USB V8. Para tornar o acessório ainda mais seguro, ele ainda vem com proteção contra variações de voltagem. ESPECIFICAÇÕES Marca: Gshield Capacidade: 5.000mAh Tamanho: 12x5,8x1cm Peso: 106 gramas Micro USB Input: 5V – 2.4 A USB Output: 5V – 2.4 A 12W Máx Type-C: 5V - 2A Conectores: 1 Lightning / 1 USB V8 / 1 Type-C Obs.: A função da porta Tipo C é apenas para receber carga.', 203.2, 203.2, NULL, 'Mobile & Gadgets > Accessories > Powerbanks & Batteries', 'https://cf.shopee.com.br/file/9c594f5d8362d69b50d0ba42cd7b4b32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F12120357196', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
