INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259450012', 'Pão de Forma Premium Panco', 'Pão de forma Panco Premium, ideal para o seu café da manhã e lanches rápidos. * Zero gorduras trans, garantindo uma opção mais saudável. * Contém glúten e lactose. Ingredientes: Farinha de trigo enriquecida com ferro e ácido fólico, açúcar, gordura vegetal, sal refinado, glúten de trigo, soro de leite em pó, conservadores propionato de cálcio e sorbato de potássio, emulsificantes lecitina de soja e estearoil-2-lactil lactado de cálcio e antioxidante ácido ascórbico. Alérgicos: Contém glúten, lactose, derivados de leite, soja e trigo. Pode conter cevada, ovo, aveia e triticale. Conservação: Após cada consumo, manter a embalagem fechada.', 11.49, 11.49, NULL, 'Food & Beverages > Bakery > Breads', 'https://cf.shopee.com.br/file/sg-11134201-825b5-mqnem6l855oh8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554909%2F58259450012', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098451989', 'Compressor De Ar Elétrico 5,0 Pés Profissional 1000w The Black Tools', 'A The Black Tools é uma marca comprometida com a qualidade e as necessidades do cliente. Nosso objetivo é oferecer as melhores soluções para o seu dia a dia, com um design funcional e inovador. COMPRESSOR DE AR ISENTO ÓLEO POÇO ARTESIANO 1CV 220V CME1000 - The Black Tools Compressor de ar direto de pistão da The Black Tools CME1000 é uma solução confiável e eficiente para atender às necessidades de compressão de ar em aplicações que requerem ar puro e livre de contaminação de óleo; Especialmente projetado para poços artesianos, este compressor oferece desempenho consistente e qualidade de ar excepcional; É uma ferramenta eficiente e compacta, assegurando facilidade no manuseio e conveniência no dia a dia. VANTAGENS: - Motor Potente equipado com um motor de 1CV, o compressor oferece potência suficiente para operar de forma eficiente, garantindo uma taxa de fluxo de ar adequada para as demandas do poço artesiano; - Isso é essencial em aplicações onde um ar limpo e livre de óleo é necessário, como em poços artesianos ou outras atividades sensíveis à contaminação; - O compressor de ar CME1000 é totalmente isento de óleo, o que significa que não há contaminação do ar comprimido com partículas de óleo. CARACTERÍSTICAS: Pressão de operação (Mínimo): 120 lbf/pol² - 8,3 bar; Deslocamento Teórico: 5,0 pés³/min – 141 l/min; Rotação da unidade compressora: 1700 RPM Número de estágios: 01 estágio; Potência do motor: 1000 Watts; Número de pistão: 02 em linha; Número de fases: Monofásico; Número de polos: 04 polos; Frequência: 60 Hz; Tensão: 220V; Marca: The Black Tools Modelo: CME1000 Peso: 14 Kg Dimensões (CxLxA): 34x25x28 Cm Garantia: 06 Meses SKU: 24275', 1100.0, 1100.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7reor-m90ktuiy5kwle0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1499568354%2F22098451989', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
