INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699914928', 'PINO GUIA DISCO DE FREIO FIAT DUCATO/PEUGEOT BOXER/CITROEN JUMPER 2.5/2.8/2.3 1997 A 2017 4221815', 'PINO GUIA DISCO DE FREIO VALOR UNITÁRIO REFERÊNCIA DO PRODUTO: 4221815 A NESTA OFERTA O CLIENTE RECEBE: 1- PINO APLICAÇÕES: FIAT DUCATO 2.5/2.8/2.3 1997 A 2017 PEUGEOT BOXER 2.8/2.3 1999 A 2017 CITROEN JUMPER 2.8/2.3 1999 A 2017 IMPORTANTE: Garantia de 3 Meses. Valor Unitário. Imagens Meramente Ilustrativas. Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto. Não está incluso para pessoa jurídica o valor do de substituição tributária para fora do estado de São Paulo, caso queira a nota fiscal sai no nome de pessoa jurídica, confirme no campo perguntas e respostas o valor do imposto.', 9.3, 9.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-824j4-mfilwcvkw1l695', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1566896523%2F18699914928', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20498091570', 'Cadeira para Carro Joie Every Stage FX Coal 0-36Kg c/ Isofix', 'Cadeira para Carro Joie Every Stage FX Coal 0–36Kg com Isofix – 4 Fases de Uso, Reclinável e com Proteção Lateral A Cadeira para Carro Joie Every Stage FX Coal 0–36Kg com Isofix foi desenvolvida para acompanhar todas as fases do crescimento da criança — do nascimento até aproximadamente os 12 anos. Com design inteligente e estrutura reforçada, ela oferece segurança, durabilidade e adaptação total, reduzindo a necessidade de trocar de cadeira a cada nova etapa. Com a Every Stage FX, os pais ganham tranquilidade e praticidade no dia a dia. O sistema Isofix proporciona instalação firme e rápida, evitando erros de encaixe e garantindo estabilidade máxima durante o trajeto. Além disso, o modelo conta com proteção lateral avançada (Guard Surround Safety), que absorve impactos e preserva a integridade da criança em qualquer direção. A Cadeira Infantil Joie Every Stage FX combina tecnologia e conforto: o assento possui 10 níveis de altura ajustáveis e encosto expansível, acompanhando o crescimento da criança sem necessidade de adaptações complexas. Seu revestimento premium é suave ao toque e feito com tecido inteligente, que evita o superaquecimento e proporciona viagens mais agradáveis. Cada detalhe da Cadeira Auto Joie Every Stage FX foi pensado para facilitar a rotina dos pais: os ajustes são intuitivos, os botões são sinalizados com cores contrastantes e os bolsos laterais permitem guardar itens essenciais, como mamadeiras ou chupetas. É o tipo de produto que entrega segurança, conforto e praticidade real — não apenas na teoria, mas no uso diário. A britânica Joie é reconhecida mundialmente por seus produtos que unem qualidade, inovação e sustentabilidade. Presente em mais de 80 países, a marca segue os mais rigorosos padrões internacionais de segurança e oferece equipamentos que realmente crescem junto com a família. Vantagens do Produto Acompanha todas as fases: grupos 0+, 1, 2 e 3 (0 a 36kg) Sistema Isofix para instalação rápida e firme Pode ser usada de costas ou de frente para o movimento 4 posições de reclino (frente) e 2 posições (costas) Proteção lateral Guard Surround Safety contra impactos Concha interna reforçada em aço para maior estabilidade Ajuste simultâneo de altura e largura (Grow Together + AutoAdjust) Cinto de 5 pontos com ajuste fácil e compartimento de armazenamento Revestimento premium e respirável, com toque suave Bolsos laterais para acessórios e objetos do bebê Marca britânica premiada, referência em segurança infantil Certificações e Segurança Certificada pelo INMETRO: Nº 000820/2021 OCAN - DRC.0490/20-02 Estrutura em aço de alta resistência Sistema de proteção lateral Guard Surround Safety Cinto de segurança de 5 pontos, testado conforme normas internacionais Garanta agora a Cadeira para Carro Joie Every Stage FX Coal 0–36Kg com Isofix e proporcione ao seu filho viagens mais seguras e confortáveis em todas as fases da infância. Invista em segurança e tranquilidade duradoura — escolha Joie.', 2976.0, 1599.0, NULL, 'Mom & Baby > Baby Travel Essentials > Car & Motorbike Seats', 'https://cf.shopee.com.br/file/sg-11134201-7rd5n-m7jidyg4xjab37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1479622710%2F20498091570', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098433621', 'Carrinho de Bebê Ivy Gold Berço-Passeio e Moisés Galzerano', 'Carrinho de Passeio Travel System com Cesto Moises Ivy Galzerano Gold O carrinho ivy combina robustez com modernidade e praticidade, em um design leve e compacto. Seu tecido, com proteção UV50+ e resistência à água, garante conforto e segurança, mesmo em condições climáticas adversas. Além disso, o fechamento fácil do carrinho de bebê Galzerano Ivy, aliado ao cesto moisés dobrável, oferece funcionalidade e conveniência para o dia a dia dos pais. É possivel acompanhar ao carrinho tanto o Bebê Conforto Grid quanto o Bebê Conforto Cocoon (** Vendidos Separadamente **). Principais Caracteristicas do Carrinho de Bebê Ivy Gold Galzerano:• Capota com aba retrátil;• Cinto de segurança 5 pontos;• Alça para melhor fechamento e transporte;• Protetor de ombro;• Amplo porta-objeto;• Encosto regulável em multiposições;• Assento reversível, também se transforma em moises; • Fechamento compacto com cesto moisés dobrável;• Protetor frontal removível;• 2 Rodas dianteiras giratórias com travamento e regulagem;• 2 Rodas traseiras removíveis;• Freio único nas rodas traseiras;• Tecido resistente à água;• Tecido do carrinho com UV50+.• Estrutura em alumínio', 1818.7, 1399.0, NULL, 'Mom & Baby > Baby Travel Essentials > Strollers & Travel Systems', 'https://cf.shopee.com.br/file/sg-11134201-7reqp-m8pfwdj752w78a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1479622710%2F22098433621', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793234591', 'Temporizador Irrigação Programável Manual Hortas Jardins', 'Temporizador de Irrigação Manual - Programador de Regas para Jardim Automatize a rega do seu jardim e economize tempo e água com este temporizador de irrigação manual. Ideal para jardineiros e entusiastas de plantas, este dispositivo permite que você controle com precisão o tempo de irrigação, garantindo que suas plantas recebam a quantidade ideal de água, sem desperdício. Características Principais: Fácil Programação Manual: Com um simples giro do seletor, você pode ajustar o tempo de irrigação entre 1 a 120 minutos, de acordo com as necessidades do seu jardim. O temporizador desliga automaticamente após o período programado. Instalação Rápida e Simples: O temporizador é fácil de instalar, bastando conectá-lo à sua torneira e à mangueira de jardim. Vem com conectores rápidos que garantem uma instalação sem complicações e sem vazamentos. Compatibilidade Universal: Compatível com a maioria das torneiras de jardim e sistemas de irrigação, este temporizador é versátil e pode ser utilizado em diferentes configurações de irrigação. Material Resistente e Durável: Fabricado em plástico ABS de alta qualidade, resistente às intempéries e à radiação UV, garantindo longa durabilidade mesmo em condições externas adversas. Economia de Água: Ao permitir uma programação precisa da irrigação, o temporizador ajuda a evitar o excesso de água, contribuindo para a conservação desse recurso e a saúde do seu jardim. Especificações Técnicas: Material: Plástico ABS resistente Cor: Verde e preto Tempo de Irrigação: 1 a 120 minutos Conexões: Compatíveis com sistemas padrão de torneiras e mangueiras Peso: 200g Ideal para: Este temporizador de irrigação manual é ideal para quem deseja manter um jardim saudável com o mínimo de esforço. Seja em pequenos jardins, hortas, ou grandes áreas verdes, ele proporciona praticidade e eficiência na rega, garantindo que suas plantas recebam o cuidado necessário. Adquira já o seu temporizador de irrigação manual e simplifique o cuidado com o seu jardim, garantindo plantas mais saudáveis e uma economia significativa de água! Produto inclui e-book digital complementar, entregue eletronicamente após a compra. Garantia do vendedor: 90 dias', 55.0, 55.0, NULL, 'Home & Living > Gardening > Irrigation Systems', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lz67fcnko5yd60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F386114683%2F22793234591', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393479665', 'Chave Grifo 24'''' Pol Profissional Tubulações Encanamento', 'A chave grifo de 24 polegadas é uma ferramenta robusta e essencial para profissionais que trabalham com encanamentos e instalações hidráulicas. Esta chave ajustável é ideal para apertar e soltar tubos e conexões, proporcionando um encaixe firme e seguro, mesmo em superfícies cilíndricas e irregulares. Código 6628 Características Principais: Material de Alta Qualidade: Feita de aço de alta resistência, a chave grifo é durável e capaz de suportar as condições mais difíceis de trabalho. A pintura com revestimento anti-corrosão também aumenta sua durabilidade, tornando-a ideal para uso em ambientes úmidos. Design Ajustável: A cabeça ajustável permite que a ferramenta se adeque a diferentes diâmetros de tubos e conexões, facilitando o uso em uma ampla variedade de tarefas. Seu sistema de ajuste por rosca permite um encaixe rápido e preciso. Mandíbulas Dentadas: As mandíbulas dentadas garantem um aperto firme e seguro, evitando deslizamentos durante o uso, mesmo em superfícies lisas ou oleosas. Isso melhora a eficiência do trabalho e evita danos aos materiais. Tamanho Compacto de 8 Polegadas: Com 24 polegadas , esta chave grifo é ideal para trabalhos em espaços reduzidos ou em tubulações menores, proporcionando versatilidade sem perder força. Ergonomia e Conforto: O cabo emborrachado oferece uma pegada confortável e antideslizante, reduzindo a fadiga durante o uso prolongado. Isso melhora a precisão e o controle sobre a ferramenta, além de garantir maior segurança. Vantagens: Versatilidade: Ideal para trabalhos em encanamentos, aquecedores de água, instalações de gás, entre outros. A chave grifo de 24 polegadas pode ser usada em serviços domésticos e profissionais. Durabilidade: Com materiais de alta resistência e acabamento anti-corrosão, a chave grifo resiste a impactos e à ação do tempo, garantindo uma longa vida útil. Precisão no Aperto: As mandíbulas dentadas proporcionam um encaixe firme, evitando deslizamentos que possam danificar as peças ou tubulações. Fácil Ajuste: O mecanismo de ajuste rápido facilita a adaptação a diferentes tamanhos de tubulações, otimizando o tempo de trabalho. Aplicações: Encanamentos: Ideal para apertar ou soltar conexões de canos em serviços hidráulicos. Instalações de Gás: Seu uso se estende para a instalação e manutenção de tubulações de gás. Reparos Domésticos: Perfeita para uso em projetos de reparo e manutenção em casa, garantindo versatilidade em qualquer caixa de ferramentas. Garantia do vendedor: 90 dias E-book Digital – Série “à Vida” – Conteúdo Exclusivo Autor: Alex Enrique Editora: LORBEN Ano de publicação: 2025 Idioma: Português Formato: PDF (compatível com celular, tablet e computador) Número de páginas: entre 65 e 95 (varia por volume) ISBN: registrado Produto inclui e-book digital complementar, entregue eletronicamente após a compra. Leve para onde quiser conhecimento prático, direto ao ponto e que você pode aplicar no dia a dia. A Série “à Vida” é composta por e-books independentes que abordam temas essenciais para melhorar sua rotina, sua organização e sua qualidade de vida. Cada volume é escrito com linguagem clara e objetiva, trazendo dicas e estratégias testadas e aprovadas para facilitar o seu cotidiano, seja no trabalho, em casa ou nos seus projetos pessoais.', 145.0, 145.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1hem1ovvpxk1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F386114683%2F22393479665', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19697752885', 'Aparador em Aço 94 cm X 90 cm X 35 cm Prata/Cromado', 'Aparador em aço, cromado, com altura de 94 cm, largura de 90 cm, profundidade de 35cm, com vidro 6mm de 90x35 cm. Pode ser usado para sala de estar, jantar e hall de entrada. Com desing moderno serve para decoração e outros fins como bar ou também para apoio de objetos como livros e porta retratos. Estilo: Moderno Bandeja: Não Possui Formato: Retangular Peso (kg): 13.68 Garantia: 03 Meses Altura (cm): 94 Acabamento: Pintura Largura (cm): 90 Possui Pés: Sim Cor dos Pés: Cromado Possui Adega: Não Possui Vidro: Sim Possui Portas: Não Altura dos Pés: 90 Pés Reguláveis: Não Possui Gavetas: Não Possui Rodízio: Não Suporta Até (kg): 8 Possui Espelhos: Não Profundidade (cm): 35 Escala de Brilho: Brilhante Material dos Pés: Aço Material do Tampo: Vidro Acabamento dos Pés: Cromado Ambiente Principal: Sala de Estar Espessura do Vidro: 6 Material Principal: Aço Necessita Montagem: Sim Possui Prateleiras: Não Resistente à Chuva: Não Sapatas Niveladoras: Não Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem Marca: Criativa Cor do Produto: Cromado Itens Inclusos: 01 aparador e manual de montagem Cor Predominante: Prata Quantidade de Portas: Não Possui Quantidade de Gavetas: Não Possui', 881.16, 881.16, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-824ip-mpo0fmimq1hr78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F19697752885', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
