INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58261148989', 'Golden Gatos Adultos Carne 1kg', 'Independentes, elegantes e exigentes, gatos são seres únicos que possuem particularidades fascinantes. Desde a forma como interagem com seu dono até seus hábitos durante a alimentação, todas as suas preferências devem ser percebidas e respeitadas. Entre suas peculiaridades nutricionais, está a maior exigência quanto ao sabor do alimento. Pensando nisso GoldeN Gatos Adultos Carne foi especialmente desenvolvido para agradar o paladar dos gatos, além de atender a todas as necessidades nutricionais para uma vida longa e saudável._x000D_ _x000D_ Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor_x000D_ _x000D_ Prazo de Validade: Vide Impresso na Embalagem_x000D_ _x000D_ Observações: Imagem meramente ilustrativa', 41.99, 28.99, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/sg-11134201-820ld-mnnclmd98yys10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1760687231%2F58261148989', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
