INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398373760', 'FRIGIDEIRA 24CM DE INDUÇÃO COM ANTIADERENTE CERÂMICO MOU DE TRUFA - OIKOS', '"Conheça a Frigideira Antiaderente Ultra Ceramic Indução Mou Trufa 24cm da oikos! resistente e moderna, é perfeita para fazer suas receitas favoritas! ela tem antiaderente cerâmico de alto desempenho: evita que os alimentos grudem e é livre de toxinas! a frigideira é forjada: o processo confere maior durabilidade, distribuição de calor mais uniforme e melhora na retenção de calor, permitindo que aqueça rapidamente e mantenha a temperatura. a frigideira tem 3,7mm de espessura na borda e 2,3mm no corpo: distribui melhor o calor e evita que os alimentos queimem. possui 5 camadas: antiaderente cerâmico, camada antidesgaste interna, alumínio, camada antidesgaste externa e pintura externa. também tem uma camada extra de aço inox na base de indução! o cabo é em baquelite: resistente a altas temperaturas - não esquenta! pode ser usada em todos os tipos de fogão: indução, gás, elétrico e vitrocerâmico. não pode ir ao forno ou em microondas! processo de cura indicado: basta aplicar uma pequena quantidade de óleo vegetal com o auxílio do papel toalha, aquecer em fogo baixo por 1 a 2 minutos e, após esfriar, é só lavar e secar! a frigideira é de alumínio, baquelite e tem revestimento cerâmico. cuidados: não use objetos pontiagudos ou de metal durante o cozimento; o utensílio mais indicado é o de silicone! leve qualidade e modernidade para sua casa! medidas: comprimento (incluindo cabo): 43cm largura(sem cabo): 24cm altura: 6cm litragem: 1,65l"', 154.9, 109.9, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/sg-11134201-825zn-mlgmuujpf2mdbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F22398373760', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21867666848', 'Escova de Bambu E Pá Para Limpeza - Oikos', 'Esse é o kit escova de bambu e pá para limpeza da OIKOS. Prático: para reunir a sujeira e levar direto ao lixo com a pá Com cerdas flexíveis: não danifica as superfícies. Furo passante: na hora de guardar, é só pendurar. Design ergonômico: a alça é confortável de segurar, protege suas mãos e dá suporte para esfregar. Feita de bambu: material leve, resistente e ecologicamente correto. Durável e higiênico: o bambu é resistente e tem propriedades que evitam a proliferação de bactérias. só precisa lavar e secar de acordo com as recomendações, combinado? Dimensões do produto: Altura:8cm Comprimento: 36cm Largura: 23cm', 87.9, 59.9, NULL, 'Home Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-8260z-mlfaph2da77m54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F21867666848', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42820780320', 'Luminaria Iluminação Colmeia Led 5 Células Sigma Hexagonal Estetica Automotiva Barbearia Quadrado Academia Octonogono', 'A combinação perfeita de iluminação e design. Esta luminária dará vida aos seus espaços para que você possa aproveitá-los ao máximo. Além disso, você pode personalizar seus cantinhos favoritos e dar-lhes detalhes diferenciados. Ilumine seus espaços Este modelo é adequado para lâmpadas com tecnologia LED, que além de contribuir para o cuidado do meio ambiente, duram mais e permitem economizar até 90% mais do que as luzes convencionais. APLICAÇÕES Ideal para iluminação em estéticas automotivas, garagens, lavagens de carros, oficinas mecânicas, salas de exposição e demais locais para realçar o estilo, iluminar o espaço e melhorar a visibilidade para realização de serviços e reparos. VANTAGEM • Pode ser montado no teto ou na parede; • Experiência visual elegante e agradável; • Melhor visibilidade; • Realça detalhes e imperfeições (uso no polimento). Dimensões (cm): 237,3x165,9x44,0 Voltagem: 127/220V Potência (W): 120 Temp. de cor (K): 6500', 799.0, 799.0, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-824gt-mezubjrtygb0c1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F319801107%2F42820780320', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
