INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593687345', 'Envelope Segurança E-commerce - Vabene', 'Pensando em nossos clientes e amigos trazemos para vocês o Envelope Plastico de Segurança E-commerce - Vabene é uma solução prática e inovadora para suas necessidades de armazenamento e embalagem. Fabricado em (PEDB) Polietileno de baixa densidade transparente de alta qualidade, este envelope apresenta uma tecnologia revolucionária com suas fitas Hot-Melt na parte superior, permitindo um fechamento simples e seguro. Isso significa que você terá um fechamento seguro, com sua versatilidade incomparável, este saco é uma escolha ideal para um envio de mercadorias pelos correios, sendo bijuterias, vestuários entre outros produtos. Seja para uso doméstico, comercial ou em viagens, o Envelope Plastico de Segurança E-commerce - Vabene oferece a praticidade e versatilidade que você precisa, podendo lacrar seu o envelope de forma rápida e segura. Envelope conta com 3 versões disponíveis: - Tamanho 15 × 20 cm / 100un. - Tamanho 40 × 50 cm / 50un. - Tamanho 50 × 60 cm / 50un. A Usabilidade do Envelope Plástico Para E-commerce o torna ideal para uma variedade de setores e aplicações, incluindo: - Bijuterias: Mantenha suas preciosidades seguras e organizadas. - Vestuários e roupas: proteja suas roupas de danos e sujeira. - Laboratórios: Ideal para armazenar amostras e outros materiais de laboratório. - Armazéns em geral: organize e proteja seus produtos em armazéns e depósitos. - Viagens: Mantenha seus itens pessoais seguros e acessíveis durante as viagens. - Produtos de limpeza: evite vazamentos e mantenha seus produtos de limpeza seguros. Não perca tempo e garanta já seu Envelope Plastico de Segurança E-commerce - Vabene aqui na Dispropil! Especificações Técnicas: - Marca: Vabene - Material: Polietileno - Modelo: Envelope Plastico de Segurança E-commerce - Vabene - Possui grande versatilidade - Inodoro e Atóxico - Adesivo Hot-Melt - Validade indeterminada Itens Inclusos: - 01 Envelope Plastico de Segurança E-commerce - Vabene', 25.37, 25.37, NULL, 'Stationery > Letters & Envelopes > Envelopes & Angpao', 'https://cf.shopee.com.br/file/sg-11134201-7rbmg-m5smb6ebs31w1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1063297286%2F22593687345', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194636344', 'Suporte Violão Guitarra Baixo 9 Instrumentos Oscar OS889', 'Organizador de instrumentos OS889 Oscar Stands , o suporte ideal para quem busca praticidade, segurança e durabilidade. Construído em aço reforçado, o OS889 comporta até 9 instrumentos (violões, guitarras ou baixos) com total estabilidade e proteção, sendo perfeito para uso em estúdios, palcos, igrejas, escolas de música ou até mesmo para manter sua coleção organizada em casa. Seu acolchoamento emborrachado nos pontos de contato evita riscos e danos ao instrumento, enquanto os pés antiderrapantes garantem firmeza em qualquer superfície. Além disso, o design dobrável e portátil facilita o transporte e o armazenamento, ocupando pouco espaço quando não está em uso. Especificações Técnicas Modelo: OS889 Marca: Oscar Stands Material: Estrutura em aço resistente Cor: Preto Pés: Borracha antiderrapante Medidas: 25 x 61 x 120 cm Peso: 3,6 kg', 399.9, 399.9, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-825ax-mgdya4x9aia302', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F780674849%2F23194636344', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3777522937', 'Jogo Copos Cerveja Atlantik Cristal Ritzenhoff 425ml 2pcs - Ruvolo', 'Esse copo de cerveja traz uma experiência única ao degustar, já que foi produzido com a mais avançada tecnologia no mundo vidreiro. Esse copo foi desenvolvido para os estilos de cerveja escuras Uso: Cerveja Material: Cristal Capacidade: 425ml Diâmetro: 80mm Altura: 140mm SKU: 21008000002 Conteúdo da Embalagem: 2 Peças - Peças medidas com o volume máximo até a boca - Pode sofrer variação de até 10% de seu volume - Diâmetro é medido pela largura maior da peça Recomendamos que as limpezas das peças sejam feita à mão para evitar quebras ou danos; para realçar ainda mais o brilho das peças, limpe-as com uma flanela que não solte fiapos, levemente umedecida com álcool.', 86.99, 86.99, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/2eec9edf5cffc7bfc022404334499ee9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373594761%2F3777522937', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
