INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18199890302', 'Chuteira Futsal Umbro Action Masculino Original Com Nota Fiscal e Garantia', '⚡🔥 Chuteira Futsal Umbro Action Masculino – Domine as Quadras! Este é um produto ✅ original Umbro com garantia, vendido pela 🏪 B2 Online. A Chuteira Futsal Umbro Action é indicada para jogadores iniciantes que querem mostrar talento e técnica 💥 dentro das quadras de futebol indoor 🏟️. Com design moderno e tecnologias inovadoras, oferece conforto, estabilidade e aderência para você driblar 🌀, passar 🎯 e chutar 💪 com máxima precisão. Seu visual é um show à parte 🎨: artes gráficas personalizadas aplicadas em camadas com efeito degradê, garantindo um estilo autêntico e marcante no melhor padrão Umbro. O cabedal é confeccionado em 💎 material laminado de alta qualidade, com grafismos em “layers”, aplicação de verniz incolor para realce, Diamante Umbro em destaque e assinatura do modelo na parte frontal. A palmilha interna em EVA macio com tecido forrado oferece conforto extra 👣, enquanto o solado de futsal em blenda de PVC e TPU garante aderência, tração e durabilidade mesmo nas jogadas mais intensas 🔥. ✨ Destaques do produto: 👟 Gênero: Masculino ⚽ Indicado para: Futebol de Salão / Futsal 🔝 Materiais tecnológicos de alta performance 🎯 Ajuste perfeito com cadarço 🇧🇷 Produto Nacional 📸 Foto real do produto. As cores podem ter mínima variação devido ao ajuste da imagem para representar com fidelidade o tom original.', 162.0, 129.0, NULL, 'Sports & Outdoors > Sports Footwear > Futsal Shoes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mddhb4ivjny94f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F535071110%2F18199890302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
