INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9871155558', 'Corda de Pular Speed Rope Alumínio Rolamento Duplo Embutido Preto - Odin Fit', 'Corda de Pular Alumínio Rolamento Embutido Odin Fit A Corda de Pular Speed Rope Alumínio com Dois Rolamentos Odin Fit é uma corda de pular de alto desempenho. Essa corda é ideal para quem procura por alta durabilidade e por uma corda com manoplas mais pesadas. Ela é ideal para o treinamento de Crossfit, Funcional e MMA. Ótima para o desenvolvimento de agilidade, força, resistência, coordenação motora e equilíbrio. A Corda de Pular Speed Rope Alumínio, possui um cabo de 3 metros, totalmente ajustável, feito de aço galvanizado e revestido por um polímero especial de plástico que evita a disjunção dos filamentos de aço. Sua manopla é de alumínio, e possui dois rolamentos. Um rolamento simples lateral integrado à manopla e rolamento esfera integrado ao rolamento simples, afim de tornar o giro mais rápido e suave, assim, facilitando os movimentos como o Double Under (salto duplo) e Triple Under (salto triplo). Especificações: Comprimento do cabo: 3 metros; Material do cabo: Aço com revestimento de polímero; Comprimento da Manopla: 20 cm; Material das Manoplas: Alumínio resistente, com rolamento duplo (simples lateral e esfera); Peso do conjunto: 210g; Cor: Preto. Contém: 01 (uma) Corda de Pular Speed Rope Alumínio com Dois Rolamentos. Garantia de 3 meses sobre defeitos de fabricação.', 78.9, 78.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/ce3e79651e0e0dc4cc716327f6c0fd0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F407831463%2F9871155558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
