INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23106013647', 'Kit 3 Condicionadores Seda Cocriações Pretos Luminosos 325ml cada', 'O Kit contém 3 Condicionadores Seda Cocriações Pretos Luminosos com 325ml cada. Condicionador Seda com fórmula exclusiva, com melanina, reaviva os fios pretos do seu cabelo. Tratamento condicionador com secagem rápida, para menos tempo secando e menos tempo danificando. COMPARADO COM SHAMPOO SEDA PRETOS LUMINOSOS. Hidratação capilar para pretos lindos e luminosos Brilho e hidratação para o cabelo. Indicado para cabelos pretos que querem mais brilho, maciez e hidratação. Condicionador hidratante Seda pode ser usado diariamente. Não tem nada que faça a gente se sentir melhor do que estar com os cabelos pretos mega iluminados e com hidratação, não é mesmo Pensando nisso, a nova linha de Tratamentos Condicionadores Seda Secagem rápida veio para trazer mais comodidade e cuidado aos cabelos pretos no dia-a-dia, fornecendo hidratação aos fios e passando menos tempo secando e menos tempo danificando. O Tratamento Condicionador Seda Pretos Luminosos Secagem rápida 325ml, proporciona uma secagem rápida dos fios após, proporcionando leveza e tratamento para o cabelo. Os fios ficam secos mais rapidamente, fazendo com que você passe menos tempo secando e danificando os fios e mais tempo livre, podendo ser usado diariamente e sem medo de ser feliz Além disso, é composto por uma fórmula exclusiva que tem melanina na composição, reavivando todos os fios pretos, deixando os cabelos saudáveis e cheios de vida! A melanina é um pigmento encontrado naturalmente na pele e no cabelo. O Tratamento Condicionador Seda Pretos Luminosos secagem rápida 325ml é indicado para cabelos pretos que querem mais brilho e maciez. COMPARADO COM SHAMPOO SEDA PRETOS LUMINOSOS. COM O USO DO SHAMPOO E CONDICIONADOR COMPARADO COM SHAMPOO SEM AGENTES CONDICIONANTES.', 70.5, 70.5, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-22110-ehaihd3jj1jvc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F23106013647', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293249949', 'Kit 2 undidades Ferisept 10mg/ml 45ml', 'Kit 2 undidades Ferisept 10mg/ml 45ml Antisséptico Clorexidina - Ferisept Spray 45ml O que é:Ferisept é um anti-séptico químico, com ação antifúngica e bactericida, capaz de eliminar tanto bactérias gram-positivas quanto gram-negativas. Para que serve:É indicado para a antissepsia da pele e de pequenos ferimentos. Modo de usar:Aplicar o produto em quantidade suficiente para umedecer toda a área, esfregando com gaze estéril. Deixar secar completamente, e, se necessário, repetir o procedimento. Pode ser utilizado em mucosas.', 22.59, 19.99, NULL, 'Health > Medical Supplies > First Aid Supplies', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0ejjwwk1o68e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F22293249949', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
