INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23296938870', 'Capacete Moto Feminino Liberty Four For Girls Rosa Viseira Cristal Inmetro Tamanho 58 - Pro Tork', '#Auto Equip# Seja Bem-vindo(a) ---- Descrição: Capacete Liberty Four For Girls Rosa Nosso modelo tradicional, projetado especialmente para atender ao público feminino, combina estilo com conforto e segurança exclusivo, mesmo em situações de detalhes ou queda. Na Pro Tork, priorizamos a excelência na qualidade, submetendo todos os nossos capacetes a testes rigorosos para garantir a resistência e durabilidade dos materiais utilizados. Especificações Técnica: - Marca: ProTork - Tamanho: 58 - Modelo: LIBERTY FOUR - Cor: Rosa - Material: Acrilonitrila butadieno estireno (ABS) - Injetado em abs de alto impacto - Viseira com espessura de 2mm - Possui cinta jugular com fechamento micrométrico Conteúdo da embalagem: - 01 Capacete Liberty Four For Girls Rosa IMPORTANTE: Garantia de 3 meses Pedidos aprovados até 12h enviamos no mesmo dia (seg a sex) Utilize o campo de “Perguntas e respostas” e esclareça suas dúvidas com nosso suporte técnico.', 109.9, 89.0, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/sg-11134201-7rbla-llz2m4lmclr7e6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F600306931%2F23296938870', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094386910', 'Kit 2x Isolante Colchonete Térmico Aluminizado Guepardo Solteiro 180x50 com EVA Aluminizado Compacto para Camping - Ntk', '# Auto Equip # Seja bem-vindo(a)!!! --- Descrição: Isolante Térmico Solteiro Aluminizado Guepardo - Nautika Conteúdo da Embalagem: - 02 Isolante Térmico Solteiro Aluminizado Guepardo - Nautika Durma com muito mais conforto e proteção em suas aventuras! O Isolante Térmico Aluminizado Guepardo é o acessório indispensável para quem busca noites tranquilas e seguras durante acampamentos, trilhas e expedições. Produzido em EVA de alta qualidade, um material leve, atóxico e sem odor, ele é laminado com alumínio refletivo, que ajuda a manter a temperatura corporal estável ao refletir o calor de volta para você, bloqueando a transferência de frio e a umidade do solo. Além do conforto térmico, sua espessura de 0,6 cm garante amortecimento extra contra solos irregulares, deixando seu descanso ainda mais agradável. Compacto e prático, vem com 2 elásticos para facilitar o transporte e o armazenamento sem ocupar muito espaço na mochila. Com apenas 170g, ele é extremamente leve, ideal para aventureiros que não abrem mão de praticidade, leveza e proteção. Ficha Técnica - Marca: Guepardo - Tipo do Produto: Isolante térmico - Material: EVA com revestimento aluminizado - Dimensões aberto: 180 cm x 50 cm x 0,6 cm - Dimensões fechado: 50 cm x 11,5 cm - Tamanho: Solteiro - Peso: 170 g Importante - Garantia de 6 meses; - Pedidos aprovados até 12h00 de segunda a sexta será enviada no mesmo dia; - Enviamos em até 24h úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - Imagens meramente ilustrativas; - A cor do produto pode variar de acordo com a tela do seu smartphone ou computador; - Utilize o campo de "Perguntas e respostas" e esclareça suas dúvidas com nosso suporte técnico. - Todas as informações divulgadas são de responsabilidade do Fabricante/Fornecedor', 89.99, 89.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/sg-11134201-824h1-mehi28yn3wu9c3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F600306931%2F23094386910', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
