INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293955627', 'Farinha de Trigo Especial Arapongas Premium 5 kg', 'Produzido com grãos de trigo paranaense selecionados, possui alta capacidade de incorporar líquidos e gorduras, é ideal para todas as massas. É uma farinha muito estável durante o processamento, o que facilita muito a modelagem de receitas finas. Possui uma granulometria fina que deixa o produto muito mais leve. Ideal para toda gama de produtos refinados, de confeitos à salgados, pães especiais e pizzas.', 59.0, 39.9, NULL, 'Food & Beverages > Baking Needs > Flour', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbmj6feukq1ue3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1306254852%2F23293955627', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
