INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51159640932', 'Acionador Corrente Comando C/ Catraca Riffel Yamaha YBR 125 Factor 125 XTZ 125 TTR 125', 'Garanta o perfeito funcionamento do motor da sua motocicleta com o acionador de corrente de comando Riffel, desenvolvido com alto padrão de qualidade e precisão. Essencial para manter a tensão correta da corrente de comando, esse componente evita folgas, ruídos indesejados e desgaste prematuro do motor. Aplicação: Yamaha YBR 125 Yamaha Factor 125 Yamaha XTZ 125 Yamaha TTR 125 Diferenciais do Produto: Fabricado com materiais resistentes e duráveis Alta precisão no encaixe e funcionamento Produto novo, com excelente acabamento Marca reconhecida no mercado de motopeças Função: O acionador da corrente de comando é responsável por manter a tensão adequada da corrente interna do motor, garantindo sincronização perfeita entre válvulas e pistão, aumentando a vida útil do motor e melhorando o desempenho da moto. Conteúdo da Embalagem: 01 Acionador de corrente de comando com catraca Benefícios: Redução de ruídos no motor Melhor desempenho e segurança Instalação prática e rápida Excelente custo-benefício Importante: Recomenda-se que a instalação seja feita por um profissional especializado para garantir o correto funcionamento do produto.', 51.4, 51.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-820nk-mnloof6ozaired', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F51159640932', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
