INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23419136705', 'Chuteira Campo Penalty S11 Locker Xxi', 'Desenvolvida para dar um show, a Chuteira Campo Penalty S11 Locker XXI é a escolha perfeita para conforto e estilo na hora de bater uma bola com os amigos ou disputar um campeonato. A flexão e movimentação dos pés devem ser feitas de maneira correta, pensando nisso, a Penalty acrescentou a tecnologia Locker: a famosa botinha, que proporciona mais estabilidade e conforto durante os movimentos. Adquira a sua e marque um golaço! Benefícios: Cravos circulares que apoiam no solo. Botinha que permite ajuste anatômico aos pés. Maior resistência do solado. Melhor performance e durabilidade. Alguns diferencias técnicos: A Chuteira Campo Penalty S11 Locker XXI conta com Planilha Plana em Eva com 3,5mmde espessura, proporcionando o máximo de conforto aos pés durante a utilização. Além disso, o produto conta com a tecnologia Hiperflex, são canaletas posicionadas estrategicamente para auxiliar na flexão e movimentação dos pés durante as arrancadas e mudanças de direção.', 193.99, 193.99, NULL, 'Sports & Outdoors > Sports Footwear > Soccer Shoes', 'https://cf.shopee.com.br/file/br-11134207-820lz-mlqogczvej9g7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F23419136705', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
