INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493337374', 'Etiqueta adesiva TP19 transparente Pimaco', 'A PIMACO Multiuso TP Transparente Ø19mm é a solução perfeita para quem precisa de etiquetas versáteis, discretas e de alta qualidade para diversas aplicações. Com seu formato redondo e transparente, essa etiqueta oferece uma alternativa prática para organizar, identificar ou personalizar itens sem comprometer a estética do ambiente ou do objeto etiquetado. Ideal para uso em escritórios, escolas, lojas ou até mesmo em casa, a etiqueta Pimaco é perfeita para quem busca praticidade e eficiência. Detalhes: - Tamanho: Ø19 mm - Quantidade de folhas 5 - Quantidade de etiquetas por folha 20 - Quantidade de etiquetas por envelope 100.', 19.2, 15.36, NULL, 'Stationery > Notebooks & Papers > Labels & Stickers', 'https://cf.shopee.com.br/file/sg-11134201-8262t-mlqk6xbvw7b96e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1350081126%2F22493337374', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
