INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19998020338', 'Caneca Mini Tina Hello Kitty e Amigos', 'Depois de um dia cheio de aventuras, você precisa de uma mãozinha na hora daquele cafezinho? A gente te ajuda! Com essa caneca, a hora de juntar a turma para aquele cafezinho é muito mais divertido e completo! Não importa se é noite do café ou chá, essa caneca acompanha todas as suas aventuras! A caneca é importada, possui detalhes incríveis que vão fazer você se apaixonar! Com 100ml de capacidade, é a companhia perfeita para quem ama a hora do café da tarde! Feita em cerâmica, com uma base empilhável perfeita que te ajuda na hora de organizar as suas minis tinas! Não importa se é um cafezinho ou um chá, essa caneca te acompanha em todas as suas aventuras! Especificações: Altura: 5,5cm| Largura: 5cm| Comprimento: 5cm| Material: Cerâmica| Capacidade: 100ml Cuidados e recomendações de uso: Lavar com água, esponja macia e detergente neutro. Não vai ao micro-ondas, nem a lava-louças. Não utilizar químicos e abrasivos. Choques ou quedas podem trincar ou quebrar o produto, pois trata-se de um produto de Cerâmica.', 29.9, 29.9, NULL, 'Home & Living > Dinnerware > Tea Pots & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8259n-mqnplh8v1hxqbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F19998020338', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
