INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46151694956', 'Não bagunce a matemática | Mais de 70 projetos práticos para crianças', 'Quer aprender matemática de forma diferente e divertida? A matemática não se trata apenas de números e fórmulas. També se trata de usar sua imaginação e pensar fora da caixa! Este livro prático celebra o lado maluco da matemática, o lado que quebra as regras e abraça a criatividade. Descubra truques geniais com números, códigos legais e formas impossíveis enquanto você desenha, faz e experimenta seu caminho pelo alucinante mundo da matemátca. Se acabar parecendo uma bagunça, você está fazendo certo! Para crianças a partir de 8 anos, com letra bastão, e respostas no final do livro. 23x26cm 96 Páginas', 19.9, 11.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821dl-mh8dpeydjle0a7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F46151694956', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20359672370', 'A Sabedoria de Deus | Timothy Keller', 'Provérbios é o livro da sabedoria divina e nos ensina a basear nossa conduta e decisões diárias em Deus.Neste devocional, Tim Keller — juntamente com sua esposa, Kathy — oferece a seus leitores reflexões novas e inspiradoras para cada dia do ano e baseadas em diferentes passagens desse livro sapiencial. Com sua capacidade marcante de relacionar uma compreensão profunda da Bíblia com o pensamento contemporâneo e com as questões práticas que todos enfrentamos, Keller desvenda a poesia magistral e os valiosos ensinamentos de Provérbios e nos guia em direção a uma nova compreensão do que significa viver uma vida boa.A sabedoria de Deus é ideal para iniciar ou intensificar uma vida devocional. É um livro ao qual os leitores poderão recorrer todos os dias, ano após ano, para cultivar um relacionamento mais íntimo e pleno com Deus e com o próximo. Também pode ser lido em conjunto com "Os cânticos de Jesus", devocional de Keller inspirado em Salmos. 13x18cm 400 Páginas', 47.9, 46.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-22110-4f07uw5e8ejv74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F20359672370', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52251329194', 'Tenis Menino Cano Alto Adventure Mini Pe MP2401S', 'A Bota Adventure Mini-pé MP2401S combina durabilidade e conforto. Feita com material sintético de alta qualidade, possui cadarço para um ajuste perfeito e palmilha de EVA para maior conforto. Seu solado de PVC micro expandido oferece excelente tração e resistência, ideal para suas aventuras ao ar livre. Prepare-se para qualquer desafio com a Bota Adventure Mini-pé! Para o conforto merecido, é importante que escolha corretamente a numeração conforme o guia de tamanhos que você encontra nesta mesma página. Equipando os passos do seu garotinho para aventuras inesquecíveis! Adquira agora! Medidas: 28 - 18,5cm 29 - 19,5cm 30 - 20cm 31 - 20,5cm 32 - 21,5cm 33 - 22cm 34 - 22,5cm 35 - 23,5cm Produto ORIGINAL e com Garantia. *Após comprar, não esqueça de avaliar nosso produto e nosso atendimento, seu feedback é muito importante para nós, com ele temos como medir onde manter a qualidade e onde melhorar.*', 159.99, 79.99, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81zu4-mksiwaciel1f9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F325939221%2F52251329194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21273011268', 'Kit Cuba Pia Louca Cerâmica Banheiro Com Torneira e Válvula S01', 'Decore seu banheiro com este kit de sobrepor contendo cuba, torneira e valvula que nao e apenas uma tendencia no mundo do desenho, mas tambem lhe dara espaco suficiente em seus lados para colocar itens de higiene pessoal. Sobria e minimalista As linhas curvadas e simples de seu desenho , dara um toque moderno e minimalista a este importante espaco da sua casa. Duravel e facil de usar Feita em ceramica legitima, este artefato oferece excelente qualidade e durabilidade, e tambem e uma oportunidade estetica para decorar seu banheiro, ao qual trara personalidade e estilo. Medidas da cuba: (A) 14 cm (L) 38,5 cm (C) 38,5 cm Medidas da torneira: (A) 15 cm (L) 4,5 cm (C) 12 cm Medidas da Valvula: (A) 9 cm (L) 6,7 cm', 542.79, 479.22, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lk5oz6u7ftlv0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376221066%2F21273011268', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
