INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51604273920', 'Livro Atlas dos dinossauros - Descobertas Magníficas com abas para', 'Descubra as maravilhas dos dinossauros! Embarque em uma incrível jornada pelo mundo e levante as abas para encontrar curiosidades sobre os répteis enormes e seus habitats. Editora: Ciranda Cultural Edição: 1, 2025 Autor: Manuela Guaccio Ilustrador: Elisa Bellotti Idioma: Português Páginas: 14 Dimensões: L 21.60 x A 27.50 x E 1.40 ISBN: 9786526120088 Coleção: Descobertas magníficas Linha Editorial: Ciranda Cultural - Coedição Faixa Etária: + 4 anos Assuntos (tags): Textos informativos, Dinossauro, Aprendizado, Descoberta, Abas, Curiosidade, Hábitos, Espécies, Ciranda Cultural, Conhecimento, Educação infantil, Livro presente, Presente, Criança, Pré-história BISAC: Não Ficção Infantil / Não Ficção Infantil / Animais / Dinossauros e Criaturas Pré-Históricas Linha de Produto: Abas Encadernação: Lombada quadrada Acabamento: Laminação fosca e verniz localizado Material: Cartonado', 69.9, 69.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-825zr-mj72kux4datc6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F51604273920', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
