INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44956514263', 'TÊNIS EVERLAST CLIMBER PRO 3 UNISSEX BRANCO/ROSA', 'O Climber Pro 3 é um novo modelo que se destaca pela sua funcionalidade e conforto nos treinos. Fabricado com material respirável e sola emborrachada para o maior conforto e segurança durante as atividades. Tecnologia: Ener-g: Entressola composta por super polímero de alta densidade que garante estrutura e amortecimento ao calçado. E-Shield: Tecido tecnológico que evita o odor nos pés. E-Grip: Tecnologia que melhora a aderência e a absorção de suor, oferecendo mais segurança durante o treino. Principais características: Tipo de amarração: Cadarço Tipo de pisada: Neutra Altura do cano: Baixo Indicação: CrossTraining Conteúdo da embalagem: 1 par Garantia do Fabricante: Contra defeito de fabricação Material/Composição: NYLON/FREQUENCIA/EMBORRACHADO Lingueta: Mesh Palmilha: Eva Cabedal: KNIT/TPU Solado: Eva / Borracha Limpeza e conservação: Limpe com pano umedecido Cuidados com o produto: Para retirar odores, deixe em local seco e arejado por 12 Horas Informações básicas Referência: SEUA227 Nome: Tênis Everlast Climber Pro 3 Marca: Everlast Gênero: Unissex Faixa etária: Adulto Grupo / Sub-grupo: Calçados / Tênis Origem: Nacional', 399.99, 300.0, NULL, 'Sports & Outdoors > Sports Footwear > Training Shoes', 'https://cf.shopee.com.br/file/sg-11134201-8261w-ml6oqs1ma7t035', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F628754867%2F44956514263', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
