INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18898149996', 'Shampoo Pós-Progressiva 300ml - Fashion Gold', 'Preserve o seu liso sem frizz e com brilho espelhado.Se você alisa os seus cabelos, você precisa escolher produtos que mantém o seu liso perfeito e alinhado por um tempo até duas vezes maior.Os shampoos convencionais podem remover o efeito do alisamento até 5 vezes mais rápido, além de remover os nutrientes do fio a cada lavagem, deixando-os sem ressecados e sem brilho. Por isso, o Shampoo Pós-Progressiva da linha Protect & Control é o que o seu cabelo precisa para evitar essa perda do liso perfeito.O Shampoo Pós-Progressiva desenvolveu a Trehalose, uma molécula exclusiva que retém água e previne o ressecamento, tornando-se uma grande aliada para manter a saúde e beleza dos seus fios.Sua formulação única, limpa sem danificar os fios, promovendo uma hidratação profunda e tratamento intenso. Além disso, sua fórmula concentrada proporciona maior rendimento, possibilitando um número muito maior de lavagens do que outros shampoos tradicionais, sem afetar os efeitos da sua progressiva.Tudo isso para manter o seu liso de dar inveja por muito mais tempo.', 126.9, 105.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-820mb-mqdolmutgqo16d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1350034564%2F18898149996', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
