INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498342292', 'Óleo Lubrificante do Motor 20w50 Mineral Castrol Actevo Essential', 'O Óleo Lubrificante Castrol Actevo Essential 20W50 1L é um dos Lubrificantes para moto mais confiáveis do mundo. Mais que óleo, é engenharia líquida que protege contra os problemas que sua moto enfrenta todos os dias. A manutenção da sua moto pode custar caro, mas o uso de lubrificantes de qualidade inferior pode colocar em risco a proteção do seu motor, e depreciar o valor da sua moto. Trata-se de um lubrificante mineral que oferece a proteção essencial para o seu motor, com tecnologia Castrol que o mantém limpo e proporciona a fricção ideal para o desempenho da embreagem, oferecendo a confiança de uma marca usada por milhares de motociclistas em todo o mundo. Indicado para uso em motocicletas dos principais fabricantes de motos que exigem óleos de motor API SL (ou especificação anterior) e JASO MA. Prazo de Garantia 3 meses de garantia legal', 41.72, 41.72, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-82620-mjzoy9cocv0ldd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F641270782%2F23498342292', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698822863', 'Kit 2 Pneus 205/70R15 95S Aplus Aro 15', 'DESCRIÇÃO DO PRODUTO O Kit com 2 Pneus Aplus 205/70R15 95S foi desenvolvido para veículos de passeio, SUVs e utilitários leves, oferecendo segurança, conforto e desempenho confiável no uso urbano e rodoviário. Com desenho moderno da banda de rodagem, proporciona ótima aderência em piso seco e molhado, estabilidade em curvas, frenagens seguras e desgaste uniforme para maior durabilidade. PRINCIPAIS BENEFÍCIOS Excelente aderência em piso seco e molhado Rodagem confortável e silenciosa Maior estabilidade em curvas e frenagens Desgaste uniforme e maior vida útil Boa eficiência no consumo de combustível Direção segura e confiável Ideal para uso urbano e rodoviário Ótimo custo-benefício Estabilidade em altas velocidades Excelente durabilidade ESPECIFICAÇÕES TÉCNICAS Marca: Aplus Medida: 205/70R15 Índice de carga: 95 (615 kg por pneu) Índice de velocidade: S (até 180 km/h) Construção: Radial Tipo: TL (sem câmara) Aro: 15 Categoria: SUV / Passeio / Utilitário leve Aplicação: Uso urbano e rodoviário Quantidade: 2 pneus COMPATIBILIDADE Toyota SW4 Mitsubishi L200 / Triton Mitsubishi Pajero Sport (versões aro 15 compatíveis) Nissan Frontier Nissan X-Terra Chevrolet S10 Chevrolet Blazer Chevrolet Tracker Ford Ranger Hyundai Tucson Hyundai Santa Fe Kia Sportage Volkswagen Amarok (versões compatíveis) Outros SUVs e picapes que utilizam a medida 205/70R15 PERGUNTAS FREQUENTES O KIT É COMPOSTO POR QUANTOS PNEUS? Este anúncio refere-se a um kit com 2 pneus. O PNEU É NOVO? Sim, produto novo de fábrica. PODE USAR EM ESTRADA E OFF-ROAD LEVE? Sim, indicado para uso urbano, rodoviário e off-road leve. PRECISA DE CÂMARA? Não, é modelo TL (Tubeless), sem câmara. TEM BOA DURABILIDADE? Sim, com desgaste uniforme e vida útil prolongada com manutenção adequada. INFORMAÇÕES IMPORTANTES Produto novo e original Não trabalhamos com pneus remold Garantia de 5 anos pelo fabricante', 1283.16, 969.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdxn-mdlyt1u0kbs480', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1311743114%2F23698822863', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
