INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998651390', 'Copo Infantil com Canudo Silicone Dino World Blue 300ml KikkaBoo', 'Copo Infantil com Canudo de Silicone Dino World Blue 300ml KikkaBoo é o copo de treinamento é uma ótima solução para os pequenos quando estão passando pela transição da mamadeira para o copo comum. Além do bico com canudo este item conta com um bico em silicone que ajuda no desenvolvimento e na habilidade de a criança beber no copo comum. Tudo isso pode ser feito com o mesmo copo, adicionando acessórios diferentes do conjunto. comece com as alças de silicone que acompanha o produto e depois remova, quando seu filho estiver pronto para segurar o copo como se fosse um copo de verdade. O copo conta com o sistema antivazamento, para a tranquilidade dos pais.', 89.9, 29.9, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfk1ps3j30g790', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1419417476%2F22998651390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
