INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21198199048', 'Océane Edition Pocket Palette Casual - Paleta de Sombras 7,0g', 'Océane Edition Pocket Palette Casual - Paleta de Sombras 7,0g Paleta de sombras possui acabamentos cintilantes e matte, para um look poderoso e com toques de cor. contém 5 cores cintilantes e 4 cores matte, são tons versáteis e modernos com alta fixação e pigmentação. Perfeitos para criar diferentes looks. Conselho de Aplicação Com um pincel para sombra, pegue um pouco da cor desejada e retire o excesso com batidinhas. Aplique sobre a pálpebra com movimentos de vai e vem.', 112.6, 112.6, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-7rat7-ma46tbhbd0cs5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F21198199048', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193536085', 'Shampoo Truss Professional Uso Obrigatório 300ml', 'O Shampoo Truss Professional Uso Obrigatório 300ml foi especialmente desenvolvido para cabelos quebradiços, desidratados e quimicamente tratados. Ele proporciona uma limpeza suave, além de oferecer reconstrução imediata, blindagem contra danos, maior flexibilidade e maciez. Sua fórmula é enriquecida com Monoi Oil e Nano Reconstruction, que penetram profundamente na fibra capilar, promovendo mais suavidade e brilho aos fios. Conta ainda com ação antidesbotamento, antifrizz e antiquebra, sendo ideal para uso diário. Benefícios: - Limpeza suave; - Reconstrução imediata; - Blindagem contra danos; - Ação antifrizz e antiquebra; - Suavidade e brilho aos fios. Modo de usar: Aplique nos cabelos molhados, massageando suavemente o couro cabeludo até formar espuma. Deixe agir por 2 minutos e depois enxágue. Reaplique se necessário. Sobre a Marca: A TRUSS tem presença global em mais de 50 países e oferece uma linha completa de tratamento capilar altamente sofisticada para os mais renomados profissionais cabeleireiros e pode ser encontrada nos melhores salões de beleza do mundo.', 148.49, 109.99, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-8258y-mqotgfi8ssnf21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F23193536085', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
