INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198676130', 'Kit 24x Bebida Vegetal NotCo NotMilk Original 1L', 'Descubra o sabor e versatilidade do Leite Vegetal NotCo NotMilk Original 1L. Feito com ingredientes 100% vegetais, esse leite vegano é uma opção deliciosa e saudável para substituir o leite convencional. Fonte de cálcio e vitaminas essenciais para o seu dia-a-dia. Cremoso e com sabor suave, é perfeito para beber puro, adicionar a receitas ou preparar seus smoothies, vitaminas, cafés e chás preferidos. É a escolha perfeita para pessoas com restrições alimentares: sem lácteos, sem lactose, sem glúten, sem colesterol. Experimente agora e se surpreenda!', 431.76, 388.58, NULL, 'Food & Beverages > Beverages > Non-dairy Milk', 'https://cf.shopee.com.br/file/sg-11134201-7ra3f-mbic1sfo1vdoca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1567163664%2F23198676130', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21158590507', 'Coral Massa Corrida Pva 25kg', 'Massa Corrida COMPRE APENAS 1 UNIDADE POR VEZ 30KG É O LIMITE DE PESO, E NÃO NOS PERMITE O ENVIO DE 2 OU MAIS PRODUTOS Fácil de aplicar, lixar e um alto poder de enchimento no preparo das parede. Para proteger e manter sua pintura bonita e nova por muito mais tempo é necessário fazer uma boa preparação da superfície. A Massa Corrida Coral é indicada para uniformizar, nivelar e corrigir pequenas imperfeições em superfícies internas de alvenaria e concreto. Com alto poder de enchimento, elevada consistência, ótima aderência, sua secagem é rápida e seu odor é baixo. De consistencia cremosa, tambem é mais fácil de aplicar, econômica e mais resistente. Sua fórmula proporciona também proporciona uma maior facilidade para lixar. Uma lata de 25KG rende até 75m² por demão (Rendimento estimado. Pode variar de acordo com o tipo e condição da superfície). Informações: Rendimento: 75 m²/Kg Secagem ao toque Ao toque: 30min Entre demãos: 3h Final: 5h Número de demãos: 2 Características do produto -Alto poder de enchimento -Alta resistência e poder de preenchimento Materiais de aplicação Espátula ou desempenadeira de aço.', 225.84, 158.09, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-22100-21315v1y58iv63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F21158590507', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
