INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20364289425', 'Cozinha Completa c/ Buffet/Aparador Paris Multimóveis MP2043 Madeirada/Preta', 'A Cozinha Completa com Buffet/Aparador Paris Multimóveis MP2043 tem um excelente custo benefício e um amplo espaço interno. Os módulos são individuais (exceto o nicho para fogão/geladeira que é anexo ao armário aéreo) e você pode montar da maneira que se adaptar melhor ao seu ambiente. Produzida em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), pés com regulagem de altura de 17 a 20cm (permitem um perfeito nivelamento dos módulos), puxadores em ABS com acabamento cromado e tampos em MDP 15mm com pintura de alta resistência. O balcão possui tampo removível (compatível apenas com pia sob medida). Para deixar sua cozinha mais bonita e organizada, possui compartimento especial para utensílios mais altos e módulo aéreo com nichos. Acompanha, ainda, um buffet/aparador com 4 portas para deixar sua casa mais bonita e completa. O design clean permite que ele seja utilizado em qualquer ambiente. Conteúdo da Embalagem: 1 (um) armário aéreo com nicho lateral e horizontal de 166cm 1 (um) paneleiro duplo de 62cm 1 (um) balcão com tampo de 105cm 1 (um) buffet/aparador 4 portas Dimensões do produto montado: Cozinha - Altura: 184cm - Largura: 228cm - Profundidade: 27cm (aéreos e paneleiro) - 44,5cm (balcão com tampo) Espaço do nicho para fogão/geladeira - Altura: 162cm - Largura: 61cm Aparador - Altura: 70cm | Largura: 123cm | Profundidade: 32cm *Você pode consultar as medidas internas na imagem técnica do produto. Disponível nas cores: Preto Acetinado Texturizado - Madeirado/Preto Acetinado Texturizado - Preto Acetinado Texturizado/Lacca Fumê Brilho *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem..', 1669.9, 1199.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-22100-7vl4o5whu4ivac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F20364289425', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18657590345', 'Cozinha Compacta 3 peças com Leds MP2019 Veneza Up Multimóveis Branca', 'A Cozinha Compacta 3 peças com Leds MP2019 Veneza Up Multimóveis tem um excelente custo benefício e um amplo espaço interno. Produzida em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), pés retrô em polipropileno, que deixam o ambiente mais estiloso, puxadores em ABS e tampo em MDP 15mm com pintura de alta resistência. Os módulos são individuais e você pode montar da maneira que se adaptar melhor ao seu ambiente. O balcão possui tampo removível (compatível com pia de 120 cm). Para deixar sua cozinha mais bonita e organizada, possui módulo para forno e microondas, além de compartimento especial para utensílios mais altos. As luminárias em LED, que acompanham a cozinha, proporcionam um visual mais bonito e moderno, deixando o ambiente aconchegante e confortável. Com design minimalista e de fácil instalação, você pode escolher em qual lugar do móvel deseja fixar. Com luz brilhante, as luminárias funcionam com 3 pilhas AAA. Conteúdo da Embalagem: 1 (um) armário aéreo 120cm 1 (um) balcão com tampo 120cm 1 (um) armário para forno e microondas 62cm 1 (um) kit com 2 Luminárias LED Dimensões do produto montado: Cozinha - Altura: 203cm | Largura: 182cm | Profundidade: 32cm (aéreo) - 53cm (paneleiro e balcão com tampo) *Você pode consultar as medidas internas na imagem técnica do produto. Disponível nas cores: Branco - Preto Acetinado Texturizado *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem..', 1629.9, 1199.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7qvg7-li0fjwlri0gd9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F18657590345', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18257607928', 'Armário 2 Portas Lavanderia Multiuso Multimóveis CR8002 Branco', 'O Armário 2 Portas Lavanderia Multiuso Multimóveis é produzido em MDP com pintura UV, que garante maior durabilidade, além de um acabamento superior. Prático e funcional, possui 4 prateleiras (suportam 5 Kg cada) para manter o seu ambiente organizado. Seu design minimalista, torna o móvel muito versátil, podendo ser utilizado de diversas maneiras e em qualquer ambiente. Conteúdo da Embalagem: 1 (um) armário Dimensões do produto montado: Altura: 183cm | Largura: 52cm | Profundidade: 36cm *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 389.99, 349.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-22100-2o2fi8if34ivc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F18257607928', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
