INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251782010', 'Tênis Skechers Alus Glide-Step Feminino Off White', 'TecnologiasHyperArc: Otimiza a transição do calcanhar à ponta, oferecendo passada mais eficiente e estável.EcoFlight: Entressola leve e responsiva, feita com materiais sustentáveis.Slip-Ins: Permite calçar o tênis sem usar as mãos, graças ao calcanhar estruturado.Arch Fit: Palmilha com suporte certificado para o arco do pé, reduzindo pressão e melhorando o conforto.Goodyear: Borracha de alta durabilidade e tração superior na sola.Hands Free Slip-Ins: Versão avançada do Slip-Ins, com reforço no calcanhar que mantém a forma para calce totalmente automático.Lavável na máquina: Permite lavar o tênis na máquina sem deformar, garantindo limpeza prática e segura.Composição cabedal (parte superior): Têxtil com detalhes em sintéticoForro: Material têxtil com acolchoamento reforçadoSolado: EVA macio, colado de 5cmPalmilha: Em EVA; fixadaCor predominante: BegeIndicado para: CorridaOrigem: ImportadoGênero: FemininoAjuste: CadarçoPeso aproximado: 650g o par n° 37', 525.9, 525.9, NULL, 'Sports & Outdoors > Sports Footwear > Running Shoes', 'https://cf.shopee.com.br/file/sg-11134201-822wq-mi3oo9ao9se9f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F58251782010', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
