INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799466229', 'Tênis Mizuno Wave Vitality 7 Masculino - Cinza-Azul', 'O Produto Nome:Tênis Mizuno Wave Vitality 7- Masculino Gênero: Masculino Indicado para: Corrida, Academia, Running, Caminhada. Para iniciantes e avançados Material: Mesh Categoria: Caminhada e Corrida Adicionais do Produto: Recurso Mizuno Wave, que garante a efetividade inicial de amortecimento do tênis durante 500 km de uso, garantindo 100% da performance do sistema Composição: Parte superior (cabedal): Em Tecido Airmesh. Solado: Tecnologia X10, um composto de Borracha e Carbono. Peso do Produto: 286 g (o peso do calçado varia de acordo com a numeração). Pisada: Neutra Garantia do Fabricante: Contra Defeito de Fabricação Origem: Nacional Marca: Mizuno Descrição O Tênis Mizuno Masculino Wave Vitality 7com seu design moderno, conta com cabedal respirável para garantir mais conforto aos seus pés entre uma passada e outra, a placa Wave garante maior estabilidade, e também ajuda a dissipar a energia e amortecer cada passada. O calcanhar é acolchoado para maior suporte e o fecho em cadarço garante ajuste firme e eficaz. Já a entressola é confeccionada em EVA e o solado emborrachado, oferecendo amortecimento leve e suavidade para você superar seus limites e ir cada vez mais longe.', 379.98, 379.98, NULL, 'Sports & Outdoors > Sports Footwear > Hiking Shoes', 'https://cf.shopee.com.br/file/sg-11134201-823pr-moqr1ql4eb5td2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F354869565%2F23799466229', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
