INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211024636', 'Vestido Xadrez Bege Em Malha De Alfaiataria Quintess', 'Adicione um toque de elegância britânica ao seu guarda-roupa com nosso Vestido xadrez em malha de alfaiataria. Com um padrão xadrez clássico e sofisticado, este vestido valoriza a silhueta, sendo ideal para diversas ocasiões. O tecido jacquard alfaiataria proporciona conforto e caimento impecável. Versátil, combine com blazer para o trabalho ou acessórios marcantes para um evento casual chic. Expresse seu estilo com esta peça atemporal e cheia de charme!', 149.9, 149.9, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-823qp-mogt9kjosf7xd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1452260505%2F58211024636', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
