INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45412393659', 'Um início nada perfeito | Mih Tanino', 'O preço da fama pode ser mais alto do que se imagina... Mih Tanino sempre sonhou com os holofotes, mas logo descobriu que a busca pela popularidade esconde diversas armadilhas. Antes de ter a chance de fazer um intercâmbio quase perfeito, outra oportunidade fez seus olhos brilharem: estrelar uma série de TV! No entanto, o que parecia a realização de um sonho se revela uma grande decepção. Mas os desafios não começam nem terminam nas telas. Na escola, Mih precisou lidar com situações difíceis, comentários maldosos e até episódios de bullying — e, conforme sua visibilidade crescia, tudo isso parecia ganhar uma nova proporção. Em sua escalada ao topo das redes sociais, Mih atraiu inimizades até então inimagináveis. E logo percebeu que crescer diante de todos também tem um preço. Em quem confiar quando todos parecem querer apagar a sua luz? Título: Um início nada perfeito | Mih Tanino Autor: Mih Tanino Páginas: 256 Formato: 17 x 24 cm Edição: 2026 Capa: Brochura Peso: 0,380 kg ISBN: 9786553480568 Editora: Editora Maquinaria', 41.9, 41.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824h6-mpkxc5k7ixabf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F45412393659', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
