INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28036873324', 'Bíblia Sagrada | Letra Supergigante | NAA | Capa Luxo Cinza Peixe', 'Bíblia Sagrada | Letra Supergigante | NAA | Capa Luxo Cinza Peixe Com design elegante e letra supergigante, esta Bíblia oferece uma leitura mais confortável e acessível. A tradução utilizada é a Nova Almeida Atualizada (NAA), lançada em 2017 pela SBB após uma revisão cuidadosa da tradicional Almeida Revista e Atualizada. O resultado é um texto fiel às Escrituras, com linguagem atual e em conformidade com o português padrão do Brasil. Ideal para quem busca clareza sem abrir mão da reverência bíblica. Páginas:2160Dimensões:13,5 x 20 x 4 cm', 113.37, 113.37, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rav2-ma4hr21yjv7ze5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F28036873324', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
