INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205737633', 'Perfume Mawwal Zuhoor Red Feminino 100ml Eau de Parfum', 'Um mergulho profundo na fragrância Zuhoor Red da Mawwal é um oriental gourmand feminino criado para a noite, para a intensidade, para momentos em que presença não é opção, é intenção. Profundo e envolvente, ele mistura doçura e calor em uma composição que cresce na pele. Não é apenas uma fragrância que floresce; é uma assinatura que se espalha, permanece e deixa rastro. Sensual, quente e persistente, Zuhoor Red traduz força e feminilidade em perfeita harmonia. Notas Olfativas Topo: Pera Abertura suculenta e levemente adocicada, trazendo frescor envolvente e um toque frutado elegante. Corpo: Fava Tonka e Jasmim A fava tonka adiciona calor gourmand e cremosidade viciante, enquanto o jasmim entrega floralidade sofisticada e sensual. Fundo: Baunilha Base quente e marcante, responsável pela fixação duradoura e pelo rastro doce e intenso. Zuhoor Red é uma fragrância feita para ser sentida e lembrada.', 363.0, 272.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-8262y-ml3rgh3hips286', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1642951702%2F58205737633', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499254002', 'Jaqueta Menina Puffer - Kidstok', 'Jaqueta Menina Puffer - Kidstok A jaqueta traz modelo puffer, confeccionada em 100% poliamida com forro em poliéster. Possui capuz removível e fechamento em zíper bolsos laterais. Acompanha bolsão para amarzenamento! Características Gerais do Produto: • Composição Parte de Cima: 100% poliamida/ Forro 100% poliéster • Cor: Off White e Rosê • Gênero: Feminino • Fechamento: Zíper. • Modelagem: Normal • Outros: Modelagem padrão. Consulte a tabela de medidas. Garantia: • Sem Garantia', 189.9, 189.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Outerwear', 'https://cf.shopee.com.br/file/sg-11134201-7rd4s-lv0grkuml07jaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688191470%2F21499254002', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23830829847', 'Bíblia de Estudo para Mulheres | BKJ 1611 | Letra normal | Capa Luxo Vermelha', 'Bíblia de Estudo para Mulheres A Bíblia De Estudo Para Mulheres Mulher Guiada Pelo Espírito, É Um Devocional Escrito Por Várias Mulheres Inspiradas Que Se Propuseram A Aumentar O Desejo De Conhecer A Deus Mais Intimamente. O Cerne Dessa Obra Se Desenrola Por Suas Páginas De Encorajamento E Impacto Em Cumprir Os Planos De Deus. O Estudo Se Baseia Em Um Plano De Ação Contendo Regras As Quais Possuem A Fonte Em Uma Passagem Bíblica Específica – Preparação Para O Estudo. Conta Com Elementos Adicionais Os Quais Envolvem Instruções Específicas Na Comunhão Da Mulher Em Seus Relacionamentos Pessoais E Íntimos. Contido Nela Estão Artigos De Ensinamento, Testemunhos Sobre O Poder De Deus, Perfis De Mulheres Sobre O Passado E O Presente Na Caminhada De Fazer A Diferença No Reino. A Bíblia De Estudo Para Mulheres – Mulher Guiada Pelo Espírito, Possui Textos Na Versão Da Bíblia King James 1611, Lançada Pela Bvbooks, Que Contém A Versão Original Da Bíblia King James 1611. O Apêndice Final E A Proposta Do Estudo Em Sala Ou Em Grupo Reforçam Os Conhecimentos Dispostos E Os Princípios Que Fundamentam O Crescimento Espiritual Na Caminhada Com Deus Título: Bíblia de Estudo para Mulheres Linguagem: King James 1611 Capa: Vermelha Acabamento: Capa Luxo Borda: Prata Índice: Não Harpa: Não Palavras de Jesus em destaque: Sim Letra: Normal Fitilho: Sim Páginas: 1.866 Dimensões: Altura: 21 cm Largura: 14 cm Profundidade: 4,5 cm Peso: 0,880 kg ISBN: 9786586996371 Editora: Bvbooks', 199.05, 199.05, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-36all89mihov40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2