INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28023256177', 'Nillkin Iceblade Prop Case Para Samsung Galaxy S25 Ultra Phone Cases Flip Cover Lente Capa Protetora Traseira', 'Estojo Prop de lâmina de gelo de pele: O estojo Iceblade Prop é feito de materiais ecológicos à base de bio derivados de milho e cana-de-açúcar, reduzindo as emissões de carbono ecológicos à base de biomateriais derivados de milho e cana-de-açúcar, reduzindo as emissões de carbono e promovendo a Oferece excelente resistência à corrosão e permanece claro e não amarelado ao longo do tempo, potencializando seu apelo estético. O design estético funcional apresenta linhas elegantes que lideram uma nova tendência urbana. O suporte de capa de espelho de alumínio aeroespacial, com seu design de cápsula espacial, proporciona um visual de ponta enquanto protege a lente e serve como suporte para telefone. É integrado com borracha macia Bayer importada, oferecendo proteção superior. Notas de compra de notas de compra 1. Se você tiver dúvidas ao comprar. Você pode consultar o atendimento ao cliente da loja. 2. Bens não pré-venda estão basicamente disponíveis em estoque. Enviado em 24 horas após a compra. 3. Você pode seguir nossa loja. Torne-se um fã da nossa loja. Receba nossos cupons de fãs. E desfrute de descontos especiais e notificações de cupom de 50% do tempo até a semana.', 134.1, 105.54, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7ra3m-m4vialkst64ue5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F285436073%2F28023256177', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899256277', 'Par Lanterna Traseira Palio Weekend 2001 2002 2003 2004 Tricolor Lente Lisa Acrilico', 'Par Lanterna Traseira Palio Weekend 2001 2002 2003 2004 Tricolor Características: Produto novo de ótima qualidade; Feito sob medida, encaixe perfeito; Não acompanha lâmpadas e soquetes. Especificações técnicas: Cor: tricolor; Cor da carcaça: preta; Lente lisa em acrílico resistente. Compatível com os modelos: Palio Weekend de 2001 a 2004. Código original: 46840548; 46840549. Garantia: 90 dias Dica: De um novo visual para o seu carro, aqui você encontra os melhores produtos com os melhores preços. Importante: NÃO somos responsáveis pela má instalação ou mal uso do produto, para evitar transtornos procure por um profissional especializado.', 391.12, 352.01, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lv514jjr7zc974', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242764769%2F18899256277', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56454752316', 'Açucareiro com Colher e Tampa Lyor Colméia de Cristal 210ml', 'Açucareiro de Cristal Lyor Colméia com Colher e Tampa Adicione modernidade e brilho ao seu café com o Açucareiro Colméia da Lyor. Esta peça em cristal de alta qualidade destaca-se pelo seu design contemporâneo em relevo, que reflete a luz de forma única e traz uma textura sofisticada para a mesa posta. Completo com tampa e colher, ele é o equilíbrio perfeito entre a estética refinada e a funcionalidade necessária para o seu dia a dia. Por que o Açucareiro Lyor Colméia é essencial para você? Design Geométrico Exclusivo: O padrão em relevo inspirado em colmeias oferece um visual moderno e elegante, transformando o açúcar em um elemento decorativo. Cristal de Alta Transparência: Material premium que garante brilho permanente e clareza impecável, permitindo ver o conteúdo com pureza. Capacidade Ideal de 210ml: O tamanho perfeito para servir com generosidade sem ocupar espaço excessivo na bandeja ou na mesa de café. Solução Completa: Acompanha tampa que protege o conteúdo e uma colher de cristal coordenada, garantindo higiene e praticidade total. Qualidade Reconhecida Lyor: Marca líder em utilidades domésticas, garantindo uma peça com acabamento superior e grande durabilidade. Destaques que valorizam sua experiência: Cantinho do Café Estilizado: Sua estética clean e moderna combina com diversos estilos de decoração, do industrial ao clássico, elevando o visual do seu aparador. Serviço Prático e Higiênico: A tampa possui o encaixe ideal para manter o açúcar preservado, enquanto a colher facilita a dosagem exata. Versatilidade Gourmet: Além de açúcar, sua transparência e estilo permitem servir adoçantes em sachê, mel ou até geleias com sofisticação. Especificações Técnicas: Marca: Lyor. Linha: Colméia. Material: Cristal de Alta Qualidade. Capacidade: 210ml. Composição: 01 Açucareiro, 01 Tampa e 01 Colher. Dicas de Cuidado para sua Peça de Cristal: Limpeza: Lave com detergente neutro e esponja macia para manter o brilho e não riscar o relevo geométrico. Secagem: Seque logo após o enxágue com um pano de microfibra para evitar manchas de água e manter a transparência cristalina. Conservação: Evite choques térmicos e o uso de produtos abrasivos para preservar a integridade do cristal por muito mais tempo.', 43.0, 27.99, NULL, 'Home & Living > Dinnerware > Tea Pots & Sets', 'https://cf.shopee.com.br/file/sg-11134201-82616-mk15eqmx73swf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F56454752316', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
