INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598562267', 'ENGATE FIAT ARGO 2017 A 2025 FIXO 700KG FT4042 BRUCKE', '**ESTE ENGATE NÃO SERVE PARA TRANSBIKE, ELE É FEITO SOMENTE PARA CARRETINHAS!!** HOMOLOGADO PELO INMETRO Produto analisado, testado e aprovado em todas as etapas da avaliação garantindo total segurança para você e sua família. Engate para reboque fabricado em aço carbono de excelente qualidade e resistência. Engate de alta resistência no tracionamento de carretas, trailers, moto aquática, lanchas, etc. Não é necessário fazer furos na maioria dos veículos para a fixação do produto. Caso queira saber se o seu veículo precisa furar basta utilizar o campo de perguntas que iremos responder. Nosso engate é completo, acompanha kit com pino bola, tomada de engate e acabamento cromado. BRUCKE é o melhor custo benefício do mercado nacional quando falamos em engates. Especificações Técnicas: - Tração máxima de 700 kg - Sem solda na cabeça do engate - Fabricado em aço carbono - Pintura eletrostática (anticorrosiva) - Bola de engate cromada - Acabamento cromado (chapa) - Tomada de engate cromada - Regularizado de acordo com resolução n°197 do Contran - Homologado pelo INMETRO', 461.17, 424.28, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Hitch', 'https://cf.shopee.com.br/file/sg-11134201-7raub-maka7eskurfnb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F329035577%2F23598562267', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
