INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197762854', 'Devocional 365 dias Priorize Deus 2025 | Capa Dura | Michel Simplício', 'Priorize Deus é o devocional mais completo do Brasil. Esta ferramenta extraordinária disponibiliza uma série de recursos pensados para levar o leitor a um relacionamento diário com Deus, o que causará enorme impacto na sua vida prática e no entendimento da fé. Cada uma das 365 reflexões do livro é acompanhada de perguntas-chave, um plano anual de leitura bíblica e ministrações em áudio com acesso por QR Code, além de seções adicionais nas páginas finais. Tudo elaborado com extrema responsabilidade e dedicação para tornar a experiência do leitor com o Senhor impactante e transformadora.', 49.99, 45.0, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8dw3eoz48oh94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F23197762854', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
