INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204082742', 'Redken All Soft Moisture Restore - Leave-in 150ml', 'Leave-in para cabelos secos e opacos. Redken All Soft Moisture Restore adiciona brilho instantâneo, além de hidratar profundamente os fios. O Leave-in Redken All Soft Moisture Restore promove um tratamento sem enxágue que funciona retendo as moléculas de umidade perdidas por exposição ao solar, ferramentas de calor e também processos químicos, graças a sua formulação com Ácido Hialurônico. O produto também controla o frizz e oferece proteção térmica, com ação que sela a cutícula dos fios, com um pH ácido, para reter a umidade e equilibrar o pH do cabelo **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 171.9, 171.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-82606-mjyiood831tx8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58204082742', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499292518', 'Deva Curl Styling Cream - Creme Modelador 250g', 'Creme modelador para cabelos cacheados. Deva Curl Styling Cream mantém os cachos naturalmente definidos, protege do frizz e hidrata. O Creme Modelador Deva Curl Styling Cream tem fixação leve e possui uma formulação rica em ativos botânicos que proporcionam condicionamento durável ao longo do dia, enquanto garantem toque sedoso e efeito memória para uma finalização durável e à prova de umidade. Leve o seu Styling Cream Deva Curl e garanta fios alinhados, com uma curvatura super bonita e duradoura. Você vai amar! **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 61.9, 61.9, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-8262u-mjyitsvwpclide', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F23499292518', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204143503', 'L''Oréal Paris Elseve Hialurônico - Máscara Capilar 300g', 'Creme de Tratamento Preenchedor para cabelos secos ou ressecados. Elseve L''Oréal Paris Hidra Hialurônico promove hidratação profunda, brilho, leveza aos fios. A Creme de Tratamento Preenchedor Elseve Hidra Hialurônico, L''Oréal Paris, é o tratamento que você precisa para acabar com a desidratação. A fórmula deste creme de tratamento é enriquecida com Ácido Hialurônico: Ativo capaz de reter até 1000x seu peso em água, conhecido por preencher e preservar da hidratação profunda. Elseve Hialurônico é ideal para realizar uma transformação dos fios, sejam eles cabelos secos, mistos ou oleosos. Retém a umidade na fibra capilar por muito mais tempo, para manter as madeixas, hidratadas, soltas e livres de frizz, sem pesar. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 37.9, 37.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8260q-mjzr5migjegw41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58204143503', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
