INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208068990', 'Jaqueta Feminina Plush Com Capuz Dianna Preto', 'A Jaqueta Feminina Plush Dianna é o toque de aconchego que faltava no seu guarda roupa. Confeccionada em plush de alta qualidade, ela oferece uma textura aveludada extremamente macia e confortável, ideal para dias com temperaturas amenas. O modelo conta com o prático bolso canguru e capuz, garantindo um visual esportivo e funcional. O fechamento em zíper frontal permite versatilidade no uso, sendo a peça perfeita para compor looks casuais ou momentos de lazer com muito estilo.', 149.99, 149.99, NULL, 'Women Clothes > Jackets, Coats & Vests > Jackets', 'https://cf.shopee.com.br/file/sg-11134201-825a3-mr1qzpe83thef0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F58208068990', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893684260', 'Macaquinho Feminino Infinita Cor Verde', 'Macaquinho Feminino desenvolvido em Molecotton Viscose Light, com estampa rotativa. Possui mangas amplas, abertura nas costas com amarração em laço, e elástico na cintura, proporcionando mais conforto ao vestir.A peça única que não pode faltar no guarda-roupa, confortável e versátil, ideal para diversas ocasiões! Combine com: tênis ou sandálias e muitos acessórios. Composição: 97% Viscose 3% Elastano', 94.99, 94.99, NULL, 'Women Clothes > Jumpsuits, Playsuits & Overalls > Overalls', 'https://cf.shopee.com.br/file/sg-11134201-8259a-mr1x5ndbiebqb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F23893684260', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250021244', 'Pneu Pirelli Scorpion Seal Inside 205/55 R17 HT Aro 17 91V', 'Aumente a sua segurança com a avançada tecnologia do pneu Pirelli Scorpion Seal Inside 205/55 R17 HT Aro 17 91V. Este pneu proporciona distâncias de frenagem seguras e uma aderência superior, proporcionando-lhe tranquilidade ao volante. O índice de velocidade V indica especificamente a capacidade de velocidade máxima de até 240 Km/h, enquanto o índice de carga máximo é indicado por 91 (615 Kg).', 965.62, 798.8, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdx3-mdf088hnwij882', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F540643031%2F58250021244', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194403149', 'Tênis Via Marte Detalhe em Tela Feminino', 'Tênis Via Marte Detalhe em Tela FemininoO Tênis Via Marte Detalhe em Tela Feminino é a escolha perfeita para quem busca unir estilo, conforto e leveza em um só calçado. Com design moderno e feminino, ele combina acabamento em napa, camurça e tela respirável, proporcionando um visual delicado sem abrir mão da funcionalidade e da praticidade para o dia a dia. Versátil e cheio de personalidade, o modelo pode ser facilmente combinado com jeans, saias, vestidos ou produções casuais urbanas, criando looks autênticos e descontraídos. Seu solado em PVC leve garante estabilidade e comodidade durante o uso, enquanto o fechamento em cadarço tradicional assegura ajuste firme e seguro aos pés. Além disso, detalhes como pingente decorativo reforçam o charme do design e a identidade da marca. Com a qualidade reconhecida da Via Marte, o Tênis Detalhe em Tela entrega ótimo custo-benefício e é confeccionado em materiais de alta durabilidade. Sua palmilha em EVA macio proporciona amortecimento eficiente e conforto prolongado, tornando o modelo ideal para rotinas dinâmicas e cheias de movimento. Seja para passeios, encontros informais ou até mesmo para o uso diário, ele se adapta a diferentes estilos e ocasiões. Ao escolher o Tênis Via Marte Detalhe em Tela Feminino, você garante um calçado original, fabricado no Brasil, que alia moda, conforto e resistência em cada detalhe. Uma opção indispensável no guarda-roupa feminino para quem deseja se destacar com elegância e atitude. Características TécnicasMarca: Via Marte Modelo: Tênis Categoria: Casual / Urbano / Dia a dia Material: Sintético com detalhes em tela Forro: Tecido Palmilha: EVA macio Solado: PVC cristal tipo “caixa”, leve e estável Detalhes Adicionais: Fechamento em cadarço, pingente lateral decorativo, design moderno Garantia: 90 dias contra defeito de fabricação Origem: Fabricado no Brasil Produto Original: Sim Acompanha Nota Fiscal: Sim', 279.99, 279.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-82629-mlfdt5wev37n58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1414893337%2F23194403149', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23199009811', 'Vestido Acinturado Em Ribana Canelada Rovitex Vermelho', 'O vestido acinturado em ribana canelada da Rovitex é uma peça que valoriza a silhueta e adiciona estilo ao seu visual. O design acinturado oferece um caimento impecável, enquanto o tecido ribana canelada proporciona conforto. Versátil e moderno, esse vestido é ideal para diversas ocasiões, desde encontros casuais até eventos especiais. Combinando elegância e praticidade, o vestido acinturado em ribana canelada da Rovitex é uma escolha que realça sua aparência com classe e conforto.', 99.99, 99.99, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-8258h-mr0ldyh6xp8mff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F23199009811', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21877219578', 'Mochila Cavalera Juvenil Feminina Reforçada Escolar', '📌 𝗖𝗔𝗥𝗔𝗖𝗧𝗘𝗥𝗜𝗦𝗧𝗜𝗖𝗔𝗦: • Mochila com 2 compartimentos • Bolsos laterais • Forro personalizado • Puxadores e logo personalizado • Alça acolchoadas e ajustáveis • Divisória interna • Bolso principal com amplo espaço interno • Bolso frontal com amplo espaço interno • Mochila autentica e resistente 📝𝗙𝗜𝗖𝗛𝗔 𝗧É𝗖𝗡𝗜𝗖𝗔: • Material: Poliéster • Medidas Aproximada: (AxLxP): 41x32x13cm • Peso: 0,490kg • Litros: 16,5 litros • SKU: CV7248Z ⚠️ 𝗖𝗨𝗜𝗗𝗔𝗗𝗢𝗦 𝗗𝗘 𝗖𝗢𝗡𝗦𝗘𝗥𝗩𝗔ÇÃ𝗢: • Evite carregar excesso de peso • Embalar objetos com cantos vivos cortantes • Para limpeza, utilize apenas pano úmido ou esponja macia e sabão neutro. Não expor a luz do sol para secar • Não utilizar nenhum produto químico para limpeza • Conservar em local seco e arejado ❓𝗤𝗨𝗘𝗠 𝗦𝗢𝗠𝗢𝗦? A Oh My Bag, varejo constituído para a revenda de Mochilas, Bolsas e Malas de Viagem, vem se especializando no varejo online e se tornando referência em qualidade e confiança. Com abrangência em todo território nacional, a Oh My Bag com centro de abastecimento próprio e estoque permanente. Isso tem tornado a loja um sinônimo de tranquilidade na compra e agilidade na entrega. Emitimos Nota Fiscal para Pessoa Física e Jurídica (CNPJ) Produtos a pronta entrega', 149.9, 149.9, NULL, 'Women Bags > Backpacks', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lik9elu60a7ke8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F441234830%2F21877219578', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692994506', 'Jacques Janine Hair Care Liss Shampoo Sem Sal 450ml Condicionador Leave-in 440ml Brilho Reduz Volume', 'O SHAMPOO + LISS FOI ESPECIALMENTE DESENVOLVIDA PARA ALINHAMENTO DOS FIOS E REDUÇÃO DO VOLUME. SUA FÓRMULA VEGANA CONTÉM QUERATINA VEGETAL E CERAMIDAS VEGETAIS QUE AUXILIAM NA REPARAÇÃO DA FIBRA CAPILAR, MELHORANDO A TEXTURA, REDUZINDO O VOLUME E PROPORCIONANDO BRILHO INTENSO AOS CABELOS. / O CONDICIONADOR LISS POSSUI FÓRMULA VEGANA QUE CONDICIONA E TRATA OS FIOS PROPORCIONANDO UM LISO DURADOURO, A PRESENÇA DOS ATIVOS: QUERATINA VEGETAL E CERAMIDAS VEGETAIS AUXILIANA REPARAÇÃO DA FIBRA CAPILAR, MELHORANDO A TEXTURA, REDUZINDO O VOLUME E PROPORCIONANDO UM BRILHO INENSO AOS FIOS. SHAMPOO APLIQUE NO CABELO MOLHADO E MASSAGEIE SUAVEMENTE O COURO CABELUDO COM A PONTA DOS DEDOS ATÉ OBTER ESPUMA, ENXÁGUE, REPITA SE NECESSÁRIO. PARA UM MELHOR RESULTADO, UTILIZE A LINHA COMPLETA. / CONDICIONADOR APLIQUE SOBRE O CABELO JÁ LAVADO, DISTRIBUINDO O PRODUTO DO COMPRIMENTO ATÉ AS PONTAS, MASSAGEANDO SUAVEMENTE EM MOVIMENTOS DE CIMA PARA BAIXO. DEIXE AGIR DE 3 A 5 MINUTOS E ENXAGUE PARA UM MELHOR RESULTADO UTILIZE A LINHA COMPLETA. PRECAUÇÕES: USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. EM CASO DE ALERGIA A QUALQUER UM DOS COMPONENTES DA FÓRMULA, SUSPENDA O USO. AQUA, CETEARYL ALCOHOL, CETRIMONIUM CHLORIDE, ALCOHOL, GLYCERIN, CETYL ALCOHOL, PARAFFINUM LIQUIDUM, PARFUM, STEARAMIDOPROPYL DIMETHYLAMINE, PROPYLENE GLYCOL, ISOPROPYL PALMITATE, HYDROLYZED KERATIN, CYCLOPENTASILOXANE, LACTIC ACID, DISODIUM EDTA, BHT, ALPHA-ISOMETHYL IONONE, BENZYL SALICYLATE, DIMETHICONE, CYCLOHEXASILOXANE, LINALOOL, PEG-75 LANOLIN, LIMONENE, HEXYL CINNAMAL, HYDROXYCITRONELLAL, CITRONELLOL, METHYLCHLOROISOTHIAZOLINONE AND METHYLISOTHIAZOLINONE, GLYCOL DISTEARATE, GLYCINE SOJA OIL, GLUCOSYL CERAMIDE, PHENOXYETHANOL, METHYLPARABEN, BUTYLPARABEN, ETHYLPARABEN, TOCOPHEROL, PROPYLPARABEN.', 53.9, 44.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-820lx-mmjg0vpzwdmvc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248946294%2F23692994506', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45105511913', 'Lixeira Retangular Lyor de Metal com Pedal e Tampa Preta 5L', 'Lixeira Retangular Lyor de Metal com Pedal e Tampa Preta 5L Apresentamos a Lixeira Retangular de Metal com Pedal e Tampa em Bambu Preta da Lyor, uma escolha elegante e prática para a gestão de resíduos em sua casa. Com capacidade de 5 litros, esta lixeira combina funcionalidade e design moderno, proporcionando uma solução eficiente e esteticamente agradável. Design Retangular ModernoA forma Retangular confere um design contemporâneo à lixeira, tornando-a uma adição sofisticada para diferentes ambientes, desde cozinhas até banheiros. Material ResistenteFabricada em metal resistente, a lixeira garante durabilidade e robustez, proporcionando uma solução confiável para o descarte diário de resíduos. Tampa em BambuA tampa em bambu adiciona um toque natural e elegante ao design da lixeira, proporcionando um contraste atraente com a cor preta do metal. A Lixeira Retangular de Metal com Pedal e Tampa em Bambu Preta da Lyor é a escolha perfeita para quem busca uma lixeira que una funcionalidade e estilo. Transforme a gestão de resíduos em uma experiência elegante com este item durável e bem projetado. Lyor - Soluções completas para o seu Lar. Contém: 1 Lixeira Lava Louça: Não Microondas: Não Forno: Não Fogão: Não Freezer: Não Medidas Produto: Altura 28,00cm x Largura 14,10cm x Comprimento 28,00cm Peso: 1,08Kg Cor: Bege Material: Metal Lavar com detergente neutro, esponja macia e secar imediatamente.', 200.0, 140.99, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-82607-mk148sjcbzeo7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F45105511913', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497562506', 'Kit Jacques Janine J18 Shampoo Sem Sal Condicionador Leave-In Brilho Maciez 240ml', 'A linha J18 foi especialmente formulada para cabelos danificados e quimicamente tratados. Ao penetrar nas camadas mais profundas da fibra capilar, esta linha reestrutura os fios, reconectando as cadeias polipeptídicas quebradas e restaurando a integridade do cabelo. Enriquecida com um poderoso complexo molecular biomimético, J18 oferece uma reparação intensiva e duradoura. As micropartículas de brilho holográfico presentes na fórmula proporcionam uma luminosidade excepcional, elevando o brilho dos seus cabelos a outro nível. Experimente a linha J18 e redescubra a beleza e a vitalidade dos seus cabelos, com um tratamento revolucionário que os deixará radiantes e saudáveis. Contém: - 01 Shampoo Shampoo J18 240ml; - 01 Condicionador J18 240ml.', 111.9, 84.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rd5g-lw7amtrbrcupf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248946294%2F22497562506', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56556656269', 'Mini Processador De Alimentos 160w 360ml Com Função Pulsar 2P Britânia', 'Mini Processador De Alimentos 160w 360ml Com Função Pulsar 2P Britânia ATENÇÃO: ESCOLHA A VOLTAGEM NA VARIAÇÃO --- Descrição --- - Com o Mini Processador de Alimentos Britânia 2P é possível triturar alimentos com facilidade em apenas um toque. - A lâmina em aço inoxidável é resistente e durável, perfeita para triturar alimentos com precisão e eficiência. - Além disso, sua jarra com capacidade para 360ml é transparente, permitindo observar os alimentos e controlar o grau de trituração de diversas receitas gostosas. - Esse Mini Processador de Alimentos possui ainda trava de segurança e função pulsar para ajudar no processamento de nozes, coco, torradas, carne, cebola, entre outros. - Sua vida ainda mais prática com o Mini Processador da Britânia! - --- Características --- • Trava de Segurança: o aparelho só funciona com a jarra/copo encaixados na posição correta; • Tritura os alimentos com apenas um toque; • Jarra transparente com capacidade para 360 ml; • Permite visualizar o processo e a quantidade preparada; • Lâmina em aço inoxidável; • Função Pulsar; • Composição: Plástico e metal; • Potência de 160W. • Modelo: Mini 2P; • Possui trava de segurança: Sim; • Funcionamento: O aparelho só funciona com a jarra/copo encaixados na posição correta. --- Dimensões --- - Do Produto - • Altura: 14,6 cm; • Largura: 20 cm; • Comprimento: 10,5 cm; • Peso: 0,686 kg. - Da Embalagem - • Altura: 15,7 cm; • Largura: 21,5 cm; • Comprimento: 12,3 cm; • Peso: 0,792 kg. --- Composição da Embalagem --- • 1 Mini Processador 2P; • 1 Jarra 360ml; • 1 Manual. — Perguntas Frequentes — O produto é original? Sim, pirataria é crime e deve ser denunciado à Shopee. Acompanha Nota Fiscal? Sim. O produto tem a garantia legal do fabricante? Sim. Consulte o campo garantia do anúncio. Estoque limitado – Garanta já o seu! Compre agora e aproveite nossas promoções especiais!', 189.99, 139.99, NULL, 'Home Appliances > Kitchen Appliances > Food Processors & Meat Grinders', 'https://cf.shopee.com.br/file/br-11134207-820la-mlc27toje879d3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1042011939%2F56556656269', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57208520334', 'Conjunto Coração Cravejado Prata 925 + Caixa Presente Ane Silva Joias', 'O Conjunto Coração Cravejado em Prata 925 é uma joia delicada, romântica e sofisticada. Composto por colar e brincos em formato de coração com pedras cravejadas e zircônia central transparente, o conjunto entrega brilho intenso e um visual elegante. Acompanha caixa personalizada Ane Silva Joias, tornando a peça perfeita para presentear com charme e significado. - Material: Prata 925 - Pedra: Zircônia transparente - Detalhe: Corações cravejados com pedra central - Itens do conjunto: Colar + Brincos - Acompanha: Caixa personalizada Ane Silva Joias - Fecho: Argola tradicional - Acompanha: Certificado de garantia de autenticidade Uma joia perfeita para presentear alguém especial ou para quem ama acessórios românticos com brilho marcante.', 635.0, 349.0, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/br-11134207-820lz-mmur2b1dnw8y67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340468765%2F57208520334', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399195780', 'Fogão Elétrico Fama FFG01 Inox 2 Bocas 2000W', 'Compacto, prático e simples, o Fogão Elétrico Fama FFG01 é ideal para sua cozinha! Aproveite toda praticidade com o fogão elétrico FFG01, fácil de transportar de um lugar para o outro sem necessitar de muito espaço. Com 2000W de potência, ele é ideal para uso com qualquer tipo de panela. Possui chapas de ferro fundido e antiaderente que garantem maior agilidade no aquecimento, além de durabilidade e resistência. O fogão Fama FFG01 é elétrico e não precisa de gás. Conta com regularem de temperatura que proporciona mais versatilidade na hora de preparar as suas receitas. Portátil, ele pode ser levado para qualquer lugar. Um fogão para completar sua cozinha, no espaço que você precisa! • Fogão Elétrico para vários tipos de panelas • Possui dois queimadores (Base de aquecimento) • Seletor de temperatura independente para cada queimador • Base de aquecimento em Ferro fundido • Corpo em aço inox • Pés antiderrapantes • Luz indicadora de funcionamento(vermelha).', 269.9, 269.9, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/sg-11134201-8258d-mq3foa1xcnpc6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811879342%2F20399195780', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21863108218', 'Jogo de Panelas Brinox Ceramic Life Magnólia Smart Plus - 5 e 7 peças', 'Seja Bem-Vindo(a) à Mimorada! Jogo de Panelas Brinox Ceramic Life Magnólia Smart Plus - Agora com novo design! - Mais Modernidade, Qualidade e Sofisticação! *Este conjunto não é compatível com fogões de indução, verifique em nossa loja as linhas de panelas para fogões de indução ou solicite no chat de atendimento. Conjunto de panelas é um dos itens mais importantes em uma cozinha. Por isso, você precisa se certificar em adquirir o que há de melhor, tanto em qualidade quanto em praticidade e claro, tecnologia. Para sua comodidade, na Brinox Shop você encontra o jogo de panelas 7 peças Ceramic Life Magnólia. Trata-se de um conjunto de panelas que conta com frigideira, caçarola, fervedor, wok e panela com tampa. O kit de panelas que vai deixar sua cozinha muito mais funcional e bonita. O kit de panelas da Brinox é uma ótima escolha para deixar sua cozinha muito mais bonita e funcional. Afinal, são panelas fáceis de usar, com cores que combinam com o ambiente e acima de tudo, saudáveis, ideais para preparar aquela comida deliciosa. O conjunto de panelas Brinox conta com a tecnologia Mineral Resist, uma nova geração de antiaderente que não deixa a comida grudar, tampouco estragam as panelas. Panela Brinox traz saúde para você e sua famíliaOutro ponto positivo da panela Brinox que você encontra nesse kit é você não precisa exagerar no óleo, por exemplo. Sem contar que as panelas, frigideiras e demais peças que compõem o conjunto são livres de metais pesados. Além disso, a panela Brinox conta com o revestimento Soft-Touch, que permite mais maciez e conforto no toque de alças e cabos, evitando que eles superaqueçam. Confira o jogo de panela em cerâmica ideal para as suas necessidades. Não perca mais tempo e adquira o seu jogo de panela em cerâmica da marca referência em produtos de alta qualidade e performance. Aqui na Brinox Shop você tem entrega rápida e pode comprar online com pagamento facilitado. Consulte também as opções em descontos e tenha em sua casa o melhor jogo de panelas em cerâmica. Certificação compulsória certificada pelo OCP 0003, registros 003900/2020, 003901/2020 e 003899/2020 e classificação de antiaderência A (ótima), conforme Portaria Inmetro 499/2021. Composição 7 Peças: 01 caçarola com tampa Ø24 01 caçarola com tampa 20cm 01 frigideira Ø20cm 01 panela com tampa Ø16 01 panela com tampa 18cm 01 fervedor Ø11cm 01 Wok Composição 5 Peças: 01 caçarola com tampa Ø 22cm 01 frigideira de Ø22cm 01 panela com tampa Ø16 01 panela com tampa 18cm 01 fervedor de Ø11cm.', 708.99, 708.99, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ltxx1uzf5od05e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F21863108218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206825900', 'PROTETOR MODULO ANTI FURTO FACTOR 150 2025 26', 'Protetor de Módulo Anti Furto Yamaha Factor 150 2025 / 2026 – Chapa Reforçada Proteja o módulo eletrônico da sua moto contra furtos com o Protetor de Módulo Anti Furto para Yamaha Factor 150 2025 e 2026. Desenvolvido em chapa de aço reforçada, oferece maior segurança e durabilidade, dificultando a remoção do módulo e aumentando a proteção do sistema eletrônico da motocicleta. Ideal para quem deseja mais segurança no dia a dia, seja em estacionamentos, na rua ou em viagens. Características do Produto Compatível com Yamaha Factor 150 2025 e 2026 Fabricado em chapa de aço grossa e resistente Sistema anti furto que protege o módulo eletrônico Produto novo e de ótima qualidade Encaixe perfeito no local original da moto Instalação simples Conteúdo da Embalagem 01 Protetor de Módulo Anti Furto Parafusos para instalação Benefícios Protege o módulo contra furtos Material resistente e durável Ótimo custo-benefício Produto de fácil instalação Compatibilidade Yamaha Factor 150 – modelos 2025 e 2026', 68.9, 68.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Engine Protector', 'https://cf.shopee.com.br/file/sg-11134201-8260e-mlqs0mvzgjyn48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397577506%2F58206825900', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497453753', 'Lixeira com Tampa Basculante 5L Cor Neutra Coza', 'Mais praticidade e elegância na organização da sua casa com a Lixeira Com Tampa Basculante 5L Coza, unindo funcionalidade e design minimalista. A Lixeira Basculante ajuda a manter a casa limpa, seja na cozinha, no banheiro ou no escritório. Com tamanho ideal, adapta-se muito bem a pequenos espaços. A tampa basculante facilita o descarte de resíduos, e o design do aro garante que o saco de lixo fique discretamente escondido, proporcionando um ambiente visualmente mais atraente. Fabricada em polipropileno, um material durável e de fácil limpeza, possui capacidade de 5 Litros e dimensões de Ø20 x 21,5 cm. A lixeira é na cor Cinza Frio, um tom neutro e sofisticado, que traz a sensação de tranquilidade, criando um ambiente convidativo e acolhedor. O compromisso da Coza com tecnologia e sustentabilidade reflete-se em produtos 100% recicláveis, provenientes de fontes 100% renováveis. A Linha de Lixeiras da Coza oferece uma solução completa para todos os ambientes e necessidades.', 53.99, 40.5, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/sg-11134201-7rd42-ltz76aoundfy26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F22497453753', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
