INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798014989', 'Colchão King Size D45 Connect Com Massageador 25x193x203 Keiko Colchões', 'Colchão Keiko Connect – O Futuro do Conforto e Bem-Estar Itens Inclusos: 1 Colchão Keiko Connect + 2 Travesseiros Keiko Você merece dormir em um colchão que faz mais por você. O Keiko Connect vai além do conforto. Ele foi pensado para quem quer acordar disposto, leve e com a sensação de ter descansado de verdade. Um verdadeiro upgrade no seu sono – e na sua vida. - Tecnologias Exclusivas: Massagem Vibratória com Ciclos Infinitos: A vibromassagem proporciona uma sensação de descanso profundo. Tecnologia que ajuda na sensação de relaxamento muscular. Espuma D45 com Densidade Progressiva: Conforto e firmeza na medida certa, com adaptação ao corpo para noites mais agradáveis. Sistema de luzes Colorzen: Iluminação suave que transforma o quarto em um ambiente acolhedor e relaxante. Malha premium com toque suave e acabamento tecnológico: Mais conforto, frescor e qualidade para noites tranquilas. Suporte de até 150 kg por lado: Durabilidade e conforto por muito mais tempo. - 10 ANOS DE GARANTIA Com uma garantia de 10 anos, o Colchão Keiko Connect é sinônimo de durabilidade e confiança. Um investimento em qualidade de vida e bem-estar por muitos anos. - ATENÇÃO PARA PORTADORES DE MARCAPASSO Este colchão utiliza tecnologias como magnetoterapia, infravermelho longo e turmalina negra, que não são recomendadas para pessoas com marcapasso ou dispositivos sensíveis a campos eletromagnéticos. Para sua segurança, recomendamos que esses usuários consultem orientação médica antes da compra.', 4691.25, 3755.9, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-820lb-mn4tx03xmlmo01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1374188221%2F22798014989', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
