INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693347777', 'Lava Autos 500ml Shampoo Concentrado Automotivo Vonixx / Vintex', 'Shampoo Lava Autos 500ml - Lataria Automotivo Vonixx / Vintex Mantenha seu carro sempre brilhando com o Shampoo Lava Autos Vonixx! Formulado especialmente para a lataria automotiva, este shampoo de 500ml proporciona uma limpeza profunda e eficaz, removendo sujeira, poeira e resíduos sem agredir a pintura. Características: Fórmula concentrada: Apenas uma pequena quantidade é necessária para uma limpeza poderosa. pH neutro: Seguro para todos os tipos de pintura, garantindo proteção e brilho. Rendimento alto: Ideal para quem busca qualidade e economia. Fácil aplicação: Espuma rica e fácil de enxaguar, deixando a superfície limpa e lustrosa. Transforme a lavagem do seu carro em um momento de prazer e cuidado. Com o Shampoo Lava Autos Vonixx, sua lataria ficará impecável! Experimente e sinta a diferença', 18.2, 18.2, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rdy6-m0lkrhjiouyx2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341544056%2F22693347777', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
