INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194385783', 'Leite Condensado Semidesnatado Bag 5kg Piracanjuba', 'Leite Condensado Semidesnatado Piracanjuba Bag 5kg O Leite Condensado Semidesnatado Piracanjuba 5kg é a escolha ideal para confeitarias, padarias, restaurantes, indústrias alimentícias e serviços de food service que buscam praticidade, economia e qualidade superior em suas produções. Com 6% de gordura, apresenta textura uniforme e sabor adocicado na medida certa, sendo mais leve que o leite condensado integral, sem perder a cremosidade característica. Esse equilíbrio garante excelente rendimento e consistência em receitas variadas, desde sobremesas clássicas até preparações profissionais de confeitaria e panificação. Embalado em bag de 5kg, proporciona maior eficiência no manuseio, reduz desperdícios e é ideal para grandes volumes de produção, atendendo perfeitamente à rotina intensa de cozinhas profissionais. Diferenciais e Benefícios ✅ Semidesnatado – mais leve, com 6% de gordura. ✅ Textura uniforme e sabor equilibrado – ideal para receitas doces e recheios cremosos. ✅ Alto rendimento – perfeito para uso profissional em grandes produções. ✅ Praticidade – embalagem bag de 5kg, fácil de armazenar e manusear. ✅ Versatilidade – indicado para pudins, brigadeiros, mousses, tortas, recheios, coberturas e muito mais. ✅ Qualidade Piracanjuba – confiança de uma marca reconhecida no mercado. Informações do Produto Marca: Piracanjuba Tipo: Leite Condensado Semidesnatado Peso Líquido: 5kg Teor de gordura: 6% Embalagem: Bag (uso profissional/food service) Conservação: Antes de aberto: armazenar em local fresco, seco e ao abrigo da luz. Após aberto: manter refrigerado entre 1 °C e 10 °C e consumir em até 7 dias. Informações para Alérgicos Contém leite e derivados. Não contém glúten. 👉 O Leite Condensado Semidesnatado Piracanjuba Bag 5kg é a solução perfeita para quem precisa de qualidade, praticidade e economia em larga escala, garantindo resultados padronizados e saborosos em todas as receitas.', 96.5, 96.5, NULL, 'Food & Beverages > Dairy & Eggs > Milk', 'https://cf.shopee.com.br/file/sg-11134201-824gw-meg95g4vf0nba2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1607520022%2F23194385783', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19399546413', 'Creme Desodorante Antitranspirante Herbíssimo Bisnaga Care Linhaça E Coenzima Q10 55g', 'COEZIMA Q10 + LINHAÇA melhora a elasticidade e a firmeza da pele após 3 semanas de uso. PRIMEIRÍSSIMAS NO SKINCARE PARA AS AXILAS 72H de proteção e hidratação Livres de petrolatos e parabenos Livres de corantes Firmador Dermatologicamente testado ATIVE SEU MODO PODEROSÍSSIMO PIRAMIDE OLFATIVA Topo: tangerina, laranja, damasco, pessêgo, abacaxi e folhas verdes. Corpo: gerânio, rosa, jasmim e lírio. Fundo: musk, vanilla, acorde e calda de açúcar. MODO DE USAR: Abriu, apertou… e pronto: proteção no modo poderosíssimo ativado. Passa uma quantidade ali na medida (sem exagero, tá?) e espalha sem pressa. Seca rapidinho é só esperar um segundinho antes de se vestir. Resultado? Axilas protegidas, hidratadas e zero drama. Simples, potente e bem Herbizado! PRECAUÇÕES: Axila é o território. Nada de sair passando por aí. Se a pele estiver irritada ou machucada, melhor dar um tempo, combinado? Deu ruim tipo coceira ou irritação? Pausa tudo na hora e procure orientação médica. E, não se esqueça! mantenha fora do alcance das crianças. COMPOSIÇÃO: ÁGUA, CLOROIDRÓXIDO DE ALUMÍNIO, ÁLCOOL CETÍLICO, GLICEROL, ÁLCOOL CETEARÍLICO, MONOESTEARATO DE GLICERILA, CETOMACROGOL 1000, ÓLEO DA SEMENTE DE GIRASSOL, ESTEARATO DE OCTILA, FRAGRÂNCIA, CITRATO DE TRIETILA, ÓLEO DA SEMENTE DE ALGODOEIRO, PROPANODIOL, ÓLEO DA SEMENTE DE LINHAÇA, CAPRILIL GLICOL, 1,2-HEXANODIOL, EDETATO DISSÓDICO, PENTAERITRITIL TETRA-DI-T-BUTIL HIDROXI-HIDROCINAMATO, ÓLEO DA SEMENTE DE ROSA MOSCHATA, ÓLEO DE COCO, ÁLCOOL ESTEARÍLICO, ACETATO DE TOCOFERILA, ÁLCOOL MIRISTÍLICO, ESTEARATO DE SORBITANA, POLISSORBATO 80, ÁCIDO BENZÓICO, POLICAPROLACTONA, DEXTROALFATOCOFEROL, UBIQUINONA, TROPOLONA, METILPROPANODIOL, GOMA DE FALSO-PAU-BRASIL, GLICONOLACTONA, BENZOATO DE ALQUILA C12-15, 4-TERPINEOL1, EXTRATO DA FLOR DE GARDENIA DO TAITI, SORBATO DE POTÁSSIO, BENZOATO DE SÓDIO, GLICONATO DE CÁLCIO, EXTRATO DE CASCA DE SALGUEIRO BRANCO1, SALICILATO DE BENZILA, CITRONELOL, CUMARINA, GERANIOL, HEXIL CINAMAL, LIMONENO, LINALOL.', 26.99, 11.69, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/br-11134207-820mf-mmukk17v5kw2b9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436104412%2F19399546413', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899445932', 'Néctar de Uva Del Valle', 'O Néctar de Uva Del Valle é uma opção deliciosa e refrescante para o seu dia a dia. Feito com o autêntico sabor da uva, ele contém até 50% de suco ou polpa em sua composição, garantindo uma experiência única a cada gole. Além de saboroso, o Néctar de Uva Del Valle é livre de adição de açúcares, conservantes e corantes artificiais, tornando-o uma escolha saudável para diversas ocasiões. Aproveite o sabor da fruta em um néctar prático e saboroso.', 9.79, 9.79, NULL, 'Food & Beverages > Beverages > Juice & Juice Vinegar', 'https://cf.shopee.com.br/file/sg-11134201-8259p-mqnekjhnwzrjdf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554958%2F22899445932', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
