INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18872974058', 'Quebra cabeça Disney Frozen 200 Peças - Toyster 8033', 'Quebra cabeça Disney Frozen 200 Peças - Toyster 8033 QUEBRA CABEÇA DISNEY FROZEN 200 PEÇAS - TOYSTER 8033 Divirta-se montando esse incrível quebra-cabeça de 200 pecas das princesas e personagens de Frozen - Disney. Pecas em papel e papel cartão. Com alta qualidade de impressão para valorizar cada detalhe da imagem do quebra-cabeça. Pode ser montado em família ou amigos. E um ótimo passa tempo para crianças, adolescentes e adultos. BENEFICIOS DE MONTAR QUEBRA-CABECA: - Eleva a autoestima - Exercita a memoria - Estimula o raciocínio - Exercita o imaginário - Desenvolve a criatividade - Desenvolve percepção visual - Desperta a atenção e curiosidade - Desenvolvimento neuropsicológico - Estimula habilidades motoras básicas - Incentiva a comunicação e linguagem - Desenvolve aspectos emocionais e afetivo - Estimula o reconhecimento de formas e cores INFORMAÇÕES: Dimensões: 30.9 x 44 cm (montado) Conteúdo: 200 Pecas Recomendação: para crianças a partir de 07 anos de idade Embalagem (C x A x L): 13.2 x 20.5 x 4.5 cm Embalagem (Peso): 0.80 kg Material / Composição: papel e papel cartão Registro: CE-BRI/IQB 002320 NM 300/2002 OCP 0006 Certificado: Órgãos Autorizados - OCP ́S (Organismos de Certificação de Produtos)', 29.99, 29.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-820m3-mqxpaqxlvn5y2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F18872974058', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
