INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992929940', 'Torneira Preta Banheiro Cascata Misturador Monocomando Bica Baixa Quente E Fria Fosco Yesop', '✨ Torneira Misturador Monocomando Cascata Paraná Baixa – Design Moderno e Alta Durabilidade Transforme seu banheiro com elegância e funcionalidade! A Torneira Misturador Monocomando Paraná Baixa com efeito cascata é a escolha perfeita para quem busca sofisticação, conforto e desempenho no dia a dia. 🌟 Destaques do Produto 💧 Saída em cascata de boca plana: fluxo suave e uniforme, proporcionando uma experiência relaxante 🔧 Material premium: fabricada em liga de cobre com núcleo de válvula cerâmica de alta qualidade, garantindo maior durabilidade e resistência 🛡️ Acabamento em cromo triplo com tecnologia PVD: alta resistência à corrosão e brilho duradouro 🌡️ Água quente e fria: ajuste fácil da temperatura, ideal para todas as estações 🎯 Controle monocomando: regula vazão e temperatura com precisão em um único movimento ⚙️ Instalação prática: acompanha acessórios completos para montagem rápida 🏡 Design e Funcionalidade Com um visual moderno e acabamento dourado elegante, esta torneira valoriza qualquer projeto de banheiro ou lavabo. Seu formato compacto (19 x 16,5 x 4 cm) combina perfeitamente com diferentes estilos de decoração. Além disso, seu sistema funciona perfeitamente em baixa ou alta pressão, oferecendo versatilidade e excelente desempenho. 📋 Especificações Técnicas Categoria: Torneira misturadora monocomando Modelo: Y-162 Material: Liga de cobre Tipo de instalação: Mesa (bancada) Diâmetro do cartucho: 35–42 mm Temperatura de trabalho: 0°C a 100°C Pressão nominal: 1,5 MPa Diâmetro do tubo de entrada/saída: 50 mm Aplicação: Lavatório 📦 Conteúdo da Embalagem 1 Torneira misturadora monocomando 2 Mangueiras flexíveis de aço trançado (50 cm) 1 Kit de parafusos para fixação 💡 Ideal para quem deseja unir beleza, tecnologia e praticidade em um único produto. Leve mais conforto e sofisticação para o seu banheiro!', 249.0, 129.0, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lx208mci2auub4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F464586953%2F22992929940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259443327', 'Protetor Diário Carefree Todo Dia sem Perfume', 'O Carefree Todo Dia é o protetor diário sem fragrância ideal para uso diário, especialmente quando não estamos naqueles dias. Ele é feito com microporos e material respirável, permitindo a circulação do ar, absorvendo a transpiração e neutralizando possíveis odores. * Sem fragrância * Dermatologicamente e ginecologicamente testado * Hipoalergênico * Embalagem econômica com 40 unidades', 22.99, 22.99, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/sg-11134201-8258o-mqnelxh3qlu7f1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554829%2F58259443327', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
