INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15295292108', 'Kit 3 Gel Dental Sensodyne Limpeza Profunda 90g', 'GEL DENTAL SENSODYNE LIMPEZA PROFUNDA Gel de uso diário para dentes sensíveis. Refrescância prolongada e limpeza avançada. O Gel Dental Sensodyne Limpeza Profunda foi especialmente desenvolvido para aliviar a sensibilidade nos dentes. Quando o esmalte do dente está desgastado ou a gengiva retraída, a dentina fica exposta. Isso causa a dor da sensibilidade, que vem à tona quando ingere comidas e bebidas quentes ou geladas.', 44.97, 44.97, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-823oo-mokqb5mc4ob2c9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F15295292108', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399247024', 'Retrinal Eyes Avène Creme para o Contorno dos Olhos 15ml', 'Avène Retrinal Avançado 3 em 1 Creme Para a Área dos Olhos 15ml ?Para quem precisa de uma atenção para a área dos olhos na hora do skincare, o Avène Retrinal Avançado 3 em 1 Creme Para a Área dos Olho', 267.89, 267.89, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/sg-11134201-825ah-mr44r4njbojqa6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F18399247024', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23991687612', 'Kit 3 Creme Dental Sensodyne Repair & Protect para Dentes Sensíveis 100g', 'Se você se preocupa com o desconforto nos dentes toda vez que vai tomar um sorvete, comer um doce, beber um café ou ingerir alguma bebida gelada, o creme dental Sensodyne é seu aliado na tarefa de no alívio da sensibilidade nos dentes. Graças a sua fórmula exclusiva com a Tecnologia NovaMin, forma uma camada protetora resistente sobre as áreas mais sensíveis dos dentes*, trazendo mais tranquilidade e conforto para você comer e beber o que quiser. Sua fórmula exclusiva fornece um alívio clinicamente comprovado*, proporcionando proteção duradoura contra a dor de dente causada pela sensibilidade, ajudando a combater o desconforto e auxiliando nos cuidados com a saúde bucal, com escovação diária, duas vezes ao dia. Não é nenhuma surpresa que Sensodyne seja o creme dental número 1 no mundo para dentes sensíveis ¹, com anos de pesquisa científica e que pode devolver a você o prazer de saborear suas comidas favoritas. Aproveite dos benefícios da reparação e proteção diária de áreas sensíveis dos dentes, proporcionados por Sensodyne Repair & Protect, a marca recomendada pelos dentistas². *Com escovação diária, 2x ao dia.', 78.57, 78.57, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-823qb-mokn3e1u9n9eaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23991687612', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250335729', 'Kit 2 Preservativo Jontex Sensitive Leve 8 Pague 7 Unidades', 'Preservativo Jontex Sensitive Leve 8 Pague 7 Unidades O Preservativo Jontex Sensitive é uma camisinha lubrificada mais fina do que as comuns que proporciona maior sensação de contato devido a sua menor espessura. É indicado para quem quer a proteção de sempre, porém com mais intimidade e conforto durante a prática sexual. Afinal, quanto mais perto, melhor Indicação: Abrir somente na hora de uso. Não compre se a embalagem estiver violada. Modo de Uso: O envelope que contém o preservativo deve ser aberto pelo picote no sentido vertical e somente na hora do uso. Não utilizar objetos cortantes, afiados ou pontiagudos para abrir a embalagem. Colocar o preservativo no pênis assim que ocorrer a ereção, antes de qualquer contato genital ou penetração. Para colocá-lo, leve-o até a extremidade do pênis ereto e aperte a ponta do preservativo de modo a evitar a retenção de ar em seu interior. Desenrolá-lo até a base do pênis. Logo após a ejaculação, quando o pênis ainda estiver ereto, retire-o da vagina vagarosamente, segurando a borda do preservativo para que não haja vazamento de esperma. O produto deve ser utilizado uma única vez e deve ser descartado corretamente logo após o uso, não devendo ser jogado no vaso sanitário. Use um novo preservativo a cada relação sexual. Esse preservativo é mais fino que o padrão; fazendo com que os dois membros do casal sintam mais prazer sem arriscar sua segurança ou saúde. Experimente e conheça os benefícios de um preservativo que ajuda você a ter mais prazer, conforto e Jontex é a linha de camisinhas e géis de quem acredita em sexo com envolvimento, nas descobertas e no prazer da intimidade. Este produto está disponível em embalagens de 3, 6, 8 e 16 unidades. Não é testado em animais. O preservativo é o método contraceptivo mais eficaz para prevenir infecções sexualmente transmissíveis, além de uma gravidez indesejada, portanto, seu uso na privacidade é essencial. Composição/Material: Borracha natural vulcanizada com enxofre e lubrificante óleo de silicone.', 41.38, 41.38, NULL, 'Health > Sexual Wellness > Condoms', 'https://cf.shopee.com.br/file/sg-11134201-823py-mouwbx3h9a172e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F58250335729', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48055414508', 'Kit Macacão Bebê Suspensório – 3 Peças Elegantes', 'Tamanho P. Veste de 0 a 3 meses. Macacão mede 50cm do ombro ao pé. Pé fechado. Encante-se com esse kit de macacões para bebê, pensado para quem ama delicadeza, conforto e muito estilo desde os primeiros dias. O kit contém 3 macacões modelo suspensório, em cores clássicas e sofisticadas. O que acompanha o kit: 1 macacão com suspensório azul marinho 1 macacão com suspensório verde 1 macacão com suspensório vermelho', 119.9, 99.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjzk462bpwjka9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F432637056%2F48055414508', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
