INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897071595', 'Girl Friends: Volume 1 - NewPOP', 'Mariko é uma jovem cujo hobby é ler e tem uma vida simples e comum no ensino médio. Akko é o extremo oposto: Ela é um pouco extravagante e adora moda. As duas pareciam estar em mundos totalmente diferentes, mas por um acaso do destino acabam se tornando melhores amigos! Seria esse o início de uma bela história de “amizade”?!', 30.81, 30.81, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rbm0-ln4mvea7lvuz14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23897071595', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
