INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098557940', 'Martelo rompedor/perfurador SDS MAX MRV1625', 'Indicado para trabalhos de demolição em materiais de concretos ou similares. Pode ser usado, por exemplo, na instalação de tubos, cabos, sistemas sanitários de drenagem e outras obras de engenharia civil. A ferramenta deve ser utilizada somente com acessórios compatíveis. Possui 3 ajustes de função do martelo através de uma manopla. Perfuração com impacto, eixo livre e rompedor. Possui 6 níveis de ajuste de energia de impacto. Conta com punho auxiliar com ajuste e interruptor com botão trava, além de punho auxiliar lateral que confere maior conforto ao operador e facilidade no trabalho. Possui encaixe SDS MAX, que facilita a troca rápida do acessório, cabo tipo "D" com revestimento emborrachado e sistema de amortecimento, que diminui a vibração do equipamento. Conteúdo da Embalagem: -1 Martelo rompedor/perfurador. Acompanha: 1 punho auxiliar, 1 punho auxiliar lateral, 1 chave dois pinos e 1 maleta plástica -Detalhes Técnicos: -Modelo: MRV 1625 -Tensão: 127 V~ -Frequência: 50 Hz / 60 Hz -Potência: 1.600 W -Tipo de velocidade: Variável -Rotações por minuto (rpm): 550/min - 2.100/min -Tipo de encaixe: SDS MAX -Energia de impacto: 25 J -Impactos por minuto (ipm): 550/min - 2.100/min -Capacidade máxima de perfuração em concreto: 48 mm -Ajuste do sistema de trabalho do martelete: Rompedor / Eixo livre / Perfurador com impacto -Nº de velocidades: 6 velocidades -Sistema de reversão: Não -Aceleração transmitida nas mãos - braços do operador - ah: 18,04 m/s² -Massa aproximada (peso): 11,6 kg', 2512.0, 2099.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rash-maiu19nmgdbq09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F2309