INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12169471831', 'Amortecedor Dianteiro Fiesta 03...14 - Nakata', 'CONTEÚDO: 01 Amortecedor dianteiro MARCA: Nakata REF: HG31100 GARANTIA: 24 MESES MODELO : PRESSURIZADO Aplicação: Ford Fiesta SEDAN - 2003 A 2014 (EXCETO NEW FIESTA) A Nakata é pioneira na fabricação de amortecedores pressurizados no Brasil Linha completa para carros nacionais e importados Alta performance em todas as condições de uso INFORMAÇÕES SOBRE A MARCA A Nakata é fabricante de autopeças para o mercado de reposição para veículos leves, pesados e motocicletas, está presente no Brasil há mais de 65 anos. Possui uma linha completa de componentes para suspensão, transmissão, freios, motor e motopeças, e é líder no mercado de reposição na linha de pivôs de suspensão e juntas homocinéticas. Com pioneirismo, qualidade e compromisso com o mercado, a Nakata é reconhecida pela alta performance de seus produtos e elevado padrão de serviços.', 269.47, 269.47, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/53c8c7385b45b51157fd71e442439e30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F520909456%2F12169471831', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21905627528', 'Aparelho de Barbear Descartável Gillette Prestobarba UltraGrip3 c/4 Unidades', 'Aparelho de barbear descartável que pode facilmente lhe dar até 7 barbeadores suaves? A Gillette Prestobarba Ultragrip3 entrega graças a suas 3 lâminas cromadas com sensor de pele. A máquina de barbear apresenta uma tira lubrificante que facilita o deslizamento e o enxágüe das lâminas para um enxágüe 100% melhor*(*vs. Prestobeard Ultragrip). Possui também um cabo de fácil manuseio para uma excelente manobrabilidade. Experimente a Espuma de barbear Prestobarba para um barbear melhor. • Até 7 barbas bem feitas e rentes com menos irritação e cortes* (*vs. Prestobarba Ultragrip) • Fita lubrificante para um barbear suave • Três (3) lâminas de longa duração que se adaptam ao contorno de seu rosto • Cabeça fixa para um barbear preciso • Cabo de fácil manuseio • Lâminas fáceis de enxaguar e limpar', 30.69, 27.87, NULL, 'Beauty > Beauty Sets & Packages', 'https://cf.shopee.com.br/file/sg-11134201-23030-abxnnzk58lov41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F21905627528', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50453527558', 'Creme para Mãos Eucerin Anti-Pigment FPS 30 75ml', 'O Creme para Mãos Eucerin Anti-Pigment FPS 30 é um hidratante clareador de manchas que reduz visivelmente marcas de envelhecimento com o uso contínuo. - Reduz as manchas - Preenche as rugas - Hidrata a pele Os estudos clínicos e dermatológicos comprovam sua alta eficácia e tolerabilidade em todos os tipos de pele. Com FPS 30, o Creme para Mãos Anti-Pigment é indicado, para uso diário, por adicionar uma camada de proteção a esta área tão exposta. Cuidadosamente desenvolvido com a combinação de Thiamidol, o ativo patenteado Eucerin que controla melanina, e Ácido Hialurônico para hidratar profundamente, este Creme previne que manchas voltem a aparecer. Opinião dos consumidores: - 95% afirmaram que melhora a elasticidade da pele - 95% sentiram intensa hidratação - 94% perceberam tom de pele uniforme - 81% notaram que não surgiram novas manchas de envelhecimento', 182.25, 182.25, NULL, 'Health > Personal Care > Hand Sanitizers', 'https://cf.shopee.com.br/file/sg-11134201-81zvv-mim3018p76yu3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F50453527558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44027307944', 'Desodorante Antitranspirante Roll-on NIVEA MEN Deep MaxxTech Carvão Ativado 50ml', 'NIVEA MEN Antitranspirante Roll-on Deep MaxxTech Carvão Ativado 50ml - 72 horas de proteção contra suor e odor, reduzindo 99,9% das bactérias*', 15.2, 15.2, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-81zvr-mikfyglguxaef8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F44027307944', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699317452', 'Kit 3 Papel Higiênico Neve Supreme Folha Tripla Leve 12un cada', 'O Kit contém: 3 pacotes de Papel Higiênico Neve Supreme Folha Tripla Leve com 12un cada. O Novo Neve® Supreme recebe a textura acolchoada 3D, trazendo uma nova experiência de conforto em Folha Tripla, com a maciez que só Neve® pode garantir. Todos os papeis higiênicos Neve® contém a tecnologia Dermacare, que mantém o PH natural da pele. Contém 1 Pacote com 12 rolos de 20m cada de Papel Higiênico Neve Marca: Neve Tipo de Folha: Tripla Benefícios: Higiene e conforto para todos os dias Mantém o pH Natural da pele com a tecnologia Dermacare Toque macio e suave Textura Acolchoada 3D ATENÇÃO: *Conservar em local seco e fresco.', 109.09, 109.09, NULL, 'Home & Living > Home Care Supplies > Tissue & Paper Towels', 'https://cf.shopee.com.br/file/sg-11134201-7rd71-lw64n5ogx0tq05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F21699317452', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493723157', 'Cápsulas de Café Baggio Café Aroma Chocolate com Avelã, compatível com Nespresso, contém 20 cápsulas', 'O café aromatizado Chocolate com Avelã tem sabor equilibrado e intensidade média, perfeitamente equilibrados com textura encorpada e aveludada, e aftertaste prolongado, tornando a experiência de beber café ainda mais prazerosa. Você sentirá um delicioso aroma de nozes e notas de chocolate que deixam um sabor duradouro na boca. O equilíbrio entre o doce do chocolate ao leite e o sabor tostado da avelã oferecem um sabor único e marcante. Nossas cápsulas são de alumínio! Compatíveis com máquinas Nespresso®* linha Original. Aumente seu estoque Conheça nossa nova embalagem com 20 cápsulas, ideais para quem aprecia o café como uma parte essencial de sua rotina e não cogita a possibilidade de ficar sem sua cápsula preferida. Você pode desfrutar de mais xícaras do café que tanto ama por mais tempo. Intensidade: 07 Aroma: Chocolate com Avelã Notas: Nozes e castanhas tostadas, chocolate ao leite Harmoniza com: Sobremesas e finalizações Torra: Média Bebida: Mole | Qualidade: Pontuação acima de 85 | Café Especial', 58.01, 58.01, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/br-11134207-820l6-mott9djh2xoje2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1321479779%2F22493723157', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23705579303', 'Camisa de Ciclismo Feminina Respeite a Ciclista Pro Manga Curta Way', 'Camisa de Ciclismo - Conforto e Performance – Tecido esportivo que mantém o corpo seco e a temperatura estável. - Proteção Completa – UV +, tratamento antibacteriano e anti microbiano. - Alta Qualidade – Poliéster sublimado, cores vivas e durabilidade garantida. - Praticidade no Pedal – 3 bolsos traseiros para levar itens essenciais. - Design Funcional – Zíper de 15 cm e elástico na barra para melhor ajuste. Modelagem Slim – Confira a tabela de medidas para escolher o tamanho ideal. Pedale com conforto e estilo – garanta já a sua! Sobre a Loja Para Ciclistas: • Especializada em artigos para ciclistas, com produtos de qualidade e preços justos. • Apenas produtos à pronta entrega. • Atendimento de segunda a quinta, das 8h às 18h, e sexta, das 8h às 17h.', 59.9, 46.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-81ztv-mkmirphc36ki2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379576060%2F23705579303', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44223689249', 'Govee Envisual T2 Led para TV 75-85” Rgb Wi-Fi Alexa', 'Govee Envisual TV Backlight T2 75-85 pol, câmera de lente dupla para sincronizar cores da tela, RGBIC, Wi-Fi/Bluetooth, controle por voz Alexa e Google, app Govee Home, modo música 1. Govee Envisual TV Backlight T2 (H605C312): Kit de iluminação inteligente de fundo de TV, projetado para telas grandes de 75 a 85 polegadas. Transforma sua experiência visual com efeitos de iluminação atraentes e imersivos. 2. Tecnologia Govee Envisual e Câmera Dupla: Apresenta a inovadora Tecnologia Govee Envisual com esquema de captura por divisão de zonas, oferecendo correspondência de cores em tempo real. O Design Inovador de Câmera Dupla captura o conteúdo da tela com 40% mais precisão na identificação das cores. 3. Iluminação RGBIC Aprimorada: O dobro de esferas de luz é utilizado para criar uma iluminação RGBIC mais vívida e intensa. O controle de cor zonal e os visuais vibrantes aprimoram significativamente a experiência ao assistir filmes, séries e jogos. 4. Controle Smart Sem Hub: Oferece controle conveniente via aplicativo (Wi-Fi + BT) e por Comandos de Voz, sendo compatível com Alexa e Google Assistente. O sistema não requer hub adicional para o funcionamento. 5. Modo de Música Otimizado: O Modo de Música Aprimorado permite escolher entre 4 estilos (Energético, Ritmo, Espectro, Rolante), ajustando a iluminação para sincronizar com o áudio, ideal para energizar festas e criar um home theater envolvente. Garantia 90 dias', 1084.9, 1084.9, NULL, 'Mobile & Gadgets > Accessories > USB & Mobile Lights', 'https://cf.shopee.com.br/file/br-11134275-81z1k-mfofnnuoak1x2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163157664%2F44223689249', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
