INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397654220', 'Conjunto Picnic Ensolarado Irmãos Raposa Do Deserto - Epoch 5698', 'O Conjunto Piquenique Ensolarado - Irmã e Bebê Raposas-do-deserto – inclui membros da Família das Raposas-do-deserto, conhecidos por toda a parte por suas orelhas grandes e pontudas. Inclui a Menina e o Bebê Raposa-do-deserto, junto de um carrinho de passeio e equipamento para piquenique. Vem com pãezinhos em forma de Raposa-do-deserto, donuts, bombons e cupcakes. A cesta do carrinho de passeio pode ser removida para abrir espaço para que o bebê entre nele também. O conjunto inclui a Menina Raposa-do-deserto, Jasmine, seu irmão Bebê, Caleb, junto de um carrinho de passeio e equipamento para piquenique. Apresentando a Menina Raposa-do-deserto, Jasmine, e seu irmão Bebê, Caleb. O carrinho de passeio incluído pode ser anexado a carrinhos de passeio de outros conjuntos de gêmeos (vendidos separadamente). Combine com o Kit Inicial de Padaria (vendido separadamente) brincadeiras divertidas na padaria! Combine com os conjuntos Família das Raposas-do-deserto, Gêmeos Raposas-do-deserto e Trem Arco-Íris Flutuando na Nuvem (vendidos separadamente) para se divertir com todos os bonecos raposa-do-deserto.', 279.9, 239.0, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lt4bm6op8i0i90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567914216%2F20397654220', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209452030', 'Limpador Multiuso Veja Power Fusion Limão', 'Veja Power Fusion é a eficiência de Veja Multiuso, com a poderosa mistura de extrato de limão, bicarbonato e álcool. Máximo poder de limpeza nas sujeiras mais difíceis, restaura o brilho e seca rápido. O melhor multiuso de todos os tempos. Aplique o produto nas superfícies a serem limpas e, em seguida, passe um pano ou esponja macia. Para as sujeiras mais difíceis, deixar o produto agir por alguns instantes. Para superfícies verticais, recomenda-se aplicar o produto diretamente no pano. Atenção: para painéis de fogões: limpar com a superfície fria. Não usar em superfícies de madeira natural. Para superfícies de alumínio, mármore e superfícies pintadas/esmaltadas e com serigrafia, limpar imediatamente após a aplicação. Recomendação: Testar em uma pequena área escondida antes de usar.', 12.79, 12.79, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8259f-mqnel007hdzfca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302938%2F58209452030', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15451317005', 'Esferas Bbs 0,20g 2000un 6mm - Combat', 'BBs Airsoft Plástica COMBAT AIRSOFT 0.20g 2000un. Esferas para Airsoft da marca Combat Airsoft gramatura 0.20g cor branca de alta precisão com alto padrão de polimento e sem ''rebardas''. É importante não reutilizar as esferas, uma vez efetuado o disparo, descarte as munições, essas poderão ter resíduos,trincos ou outros defeitos, que poderão prejudicar sua arma. Características: - Marca: Combat Airsoft (NTK) - Gramatura: 0.20 gramas - Cor: Branco - Quantidade: 2000 Unidades Itens Inclusos: - 1x BBs Airsoft Munição Plástica COMBAT AIRSOFT 0.20g 2000un.', 61.18, 55.07, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-8261z-mjuc0i1mwwsje8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F618731843%2F15451317005', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
