INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23691520088', 'Defletor Calha de Chuva Fiorino 1989 a 2013 2 Portas Ecoflex', 'Defletor Calha de Chuva Fiorino 1989 a 2013 2 Portas Ecoflex A Ecoflex possui uma vasta linha de calhas defletores automotivas para os mais diversos modelos. Utiliza matéria-prima de primeira, 100% acrílico, com tecnologia 3M e instalação simples. Os produtos comercializados pela Ecoflex têm como objetivo trazer conforto e segurança em seu automóvel nos dias de chuva. Com a calha de chuva a água da chuva não entrará no interior do veículo e evita que os vidros embacem. Compatibilidade: • Fiorino 1989 a 2013 2 Portas Especificações: • 100% Acrílica; • Proteção e Design; • Contra chuva e sol; • Fixada por Fita Dupla Face 3M; • Não deixa os vidros embaçarem. Conteúdo da Embalagem: • 2 Calhas Defletores de Chuva • 1 Primer (anti-aderente) Garantia: • 5 Anos (defeito de fabricação) Se tiver alguma dúvida a equipe Renovaccio estará pronta para lhe atender.', 108.63, 108.63, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-7qvcz-li0qdt9gl8px08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1013208711%2F23691520088', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18398802313', 'Apoio De Braço Palio/Grand Siena 12/20 Couro Marrom Claro', 'PRODUTO: Apoio De Braço para encaixar no porta-copo central. ****ATENÇÃO ANTES DE COMPRAR VERIFIQUE SE O ENCAIXE DO APOIO DE BRAÇO COMBINA COM SEU PORTA-COPO DO CONSOLE CENTRAL*** COMPATIBILIDADE: - Carro: PALIO/GRAND SIENA 12/20 Mais que um acessório, o apoio de braço é também um porta objetos para o seu carro. Guarde seus pertences com muita praticidade, simples e prático, cabe tudo que você precisa levar no carro. INSTALAÇÃO: A instalação é muito simples e pode ser feita em casa, o apoio de braço é apenas encaixado. Sua base é de aço de carbono de alta resistência com a parte inferior emborrachada e moldada sob medida, tendo encaixe firme e perfeito no console do veículo. MATERIAIS E CORES -COURO COURVIN Apoios de Braço acolchoados e revestidos na tampa em couro courvin Opções de costura aparente: Costura Amarelo Costura Azul Claro Costura Azul Escuro Costura Bege Costura Branca Costura Cinza Costura Grafite Costura Laranja Costura Marrom Claro Costura Marrom Escuro Costura Preta Costura Vermelha GARANTIA: 30 dias para defeitos de fabricação', 162.11, 154.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7qvdz-lk1ekhdsz4zic3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1013208711%2F18398802313', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
